--destroy all the setup bags
function afterLoad()
	--Deploy the scenario map
	mapSetup()
	Wait.time(function()
		if gStates.startAtNight==true then gStates.dayRound=true end
		dayNight()--dayNight need to be after map setup to change the tile tint
		gStates.firstStarted=true
		gStates.turnNumber=1
		tacticToggle()
		--Delete Player Bags could this be done during setup
		local ToBeDeleted={"960fa0", "e573b9", "13d7b8", "b0d65f", "6fc671", "eefacc", "b8031f", "8f94bc", "708a80", "63f203", "77b3fd", "089e71", "11128e", "96878f", "aff5f6", "536ec1", "d41799", "2b3ca1"}
						--Arythea, Goldyx, Norowas, Tovak, Krang, Braevalar, Ymirgh, Wolfhawk, Jormund, Common, Volkare, Tile shuffler, Rise of the Forgemasters, shades, LL--, City Bag, Base Cards Preload
		for _, dest in pairs(ToBeDeleted) do
			if getObjectFromGUID(dest)~=nil then getObjectFromGUID(dest).destruct() end
		end
		--finalize mirrored source.
		getObjectFromGUID("b5a6ce").destruct()
		mirrorSourceUpdate("first started game")
		--Draw all the offers will double draw if I don't get the timing right.
		gStates.totalUnitCount=gStates.playerCount+gStates.blitz+2
		if gStates.positionMageKnight[5]=="Volkare" then gStates.totalUnitCount=gStates.totalUnitCount+1 end
		unitOffer()
		fillSlide()
		--display the help boxes
		DisplayHelp(nil, "-1", nil)
		getObjectFromGUID("ac75c4").UI.setAttribute("ac75c4ArtifactDownImage", "image", "Overkill Down")
		getObjectFromGUID("ac75c4").UI.setAttribute("ac75c4ArtifactOfferImage", "image", "Sliced Button/Button Object Active")
		getObjectFromGUID("ac75c4").UI.setAttribute("ac75c4ArtifactUpImage", "image", "Overkill Up")
		getObjectFromGUID("ac75c4").UI.setAttribute("ac75c4ArtifactDown", "active", "true")
		getObjectFromGUID("ac75c4").UI.setAttribute("ac75c4ArtifactOffer", "active", "true")
		getObjectFromGUID("ac75c4").UI.setAttribute("ac75c4ArtifactUp", "active", "true")
		UI.setAttribute("ResourceTracker", "active", "true")
		UI.setAttribute("cameraControl", "active", "true")
		if gStates.gameScenario=="One to Return" then UI.hide("ScoreButton") end

		broadcastToAll("-------------------", {1,1,0.5})
		--Stop player boards and dummy board from alt zooming
		local megaFreeze=  {"3d4319", "519f96",	playerBoard[1], playerBoard[2], playerBoard[3], playerBoard[4], dummyBoard}--player mats
		for i=1, #megaFreeze, 1 do
			local obj=getObjectFromGUID(megaFreeze[i])
			if obj~=nil then obj.interactable=false end --some boards may be missing depending on their states
		end
		addAvatarButtons()
		applyColorBarButtons()
		getObjectFromGUID("e4372a").UI.setXmlTable({	{tag="Button", attributes={id="e4372aOfferUp", onClick="global/offerAdjust", onMouseDown="global/ButtonClickDown", onMouseUp="global/ButtonClickUp", height=150, width=240, position="60 190 -10", rotation="0 180 180", scale="0.32 0.32"},
														children={	{tag="Image", attributes={id="e4372aOfferUpImage", image="Sliced Button/Button Object Active", type="Sliced"}},
																	{tag="Text", attributes={font="Fonts/MKCardText", fontSize="90", fontStyle="Normal", alignment="MiddleCenter", text=">"}}}},
														{tag="Button", attributes={id="e4372aOfferDown", onClick="global/offerAdjust", onMouseDown="global/ButtonClickDown", onMouseUp="global/ButtonClickUp", height=150, width=240, position="-60 190 -10", rotation="0 180 180", scale="0.32 0.32"},
														children={	{tag="Image", attributes={id="e4372aOfferDownImage", image="Sliced Button/Button Object Active", type="Sliced"}},
																	{tag="Text", attributes={font="Fonts/MKCardText", fontSize="90", fontStyle="Normal", alignment="MiddleCenter", text="<"}}}}})
		--record data
		Wait.time(function()
            if getObjectFromGUID("e7de55")~=nil then SendDataRequest("skip", "-1", "SendDataRequestYes") end
			--UI.setAttribute("SendDataRequest", "active", "true")
		end, 400)--time in seconds, 1800=1/2 hour, 3600=1 hour 400
		Wait.time(function() straightenCrooked() end, 10)
		Wait.time(function() dealAllHands() end, 4)
	end, 0.7)
end

--Layout starting map tiles
local firstTile=nil
function mapSetup()
	local TileShuffler=		getObjectFromGUID("089e71")
	local CityTileStack=	getObjectFromGUID("a0ba93")
	local CoreTileStack=	getObjectFromGUID("c87444")
	local CountryTileStack=	getObjectFromGUID("37d9b4")
	CityTileStack.shuffle()
	CoreTileStack.shuffle()
	CountryTileStack.shuffle()
	local pos=getObjectFromGUID("966e0e").getPosition()--tile stack location
	local tUp=2--Starts building the final tile stack from this high
	--Layout Starting map tile
	local a=scenarioList[gStates.scenarioRef][gStates.playersRef].mapShape:sub(5,5)
	if a=="O" or a=="F" or a=="P" then
		getObjectFromGUID(startTerrain.wedge).unlock()
		getObjectFromGUID(portal.terrainHex).unlock()
		getObjectFromGUID(startTerrain.wedge).setPosition({-36.0305, 0.98, -11.9267})--start terrain tile gets moved and state changed
		getObjectFromGUID(portal.terrainHex).setPosition({-36.0305, 1.1, -11.9267})--start terrain tile gets moved and state changed
		getObjectFromGUID(startTerrain.wedge).setState(2)
		Wait.frames(function() getObjectFromGUID(startTerrain.open).lock() getObjectFromGUID(portal.terrainHex).lock() end, 5)
	end

	--Add Grid
	local gridType=""
	if scenarioList[gStates.scenarioRef][gStates.playersRef].mapShape=="{en}Open Limited to 4 Columns{ru}Открытое поле с ограничением в 4 ряда{zh-cn}地图限制为 4 列{ko}4열 제한{es}Abierto Limitado a 4 Columnas{fr}Ouvert Limité à 4 Colonnes{pt-br}Aberto Limitado a 4 Colunas{de}Offen Begrenzt auf 4 Spalten" then gridType="https://steamusercontent-a.akamaihd.net/ugc/1674736055049111266/7BC768B7CD64E6018EBEC720559690409F4BA555/" end--4
	if scenarioList[gStates.scenarioRef][gStates.playersRef].mapShape=="{en}Open Limited to 3 Columns{ru}Открытое поле с ограничением в 3 ряда{zh-cn}地图限制为 3 列{ko}3열 제한{es}Abierto Limitado a 3 Columnas{fr}Ouvert Limité à 3 Colonnes{pt-br}Aberto Limitado a 3 Colunas{de}Offen Begrenzt auf 3 Spalten" then gridType="https://steamusercontent-a.akamaihd.net/ugc/1674736055049110361/978D612A44ADDE6E1630965A311722114BA28AE5/" end--3
	if scenarioList[gStates.scenarioRef][gStates.playersRef].mapShape=="{en}Fully Open{ru}Полностью открытое поле{zh-cn}完全开放地图{ko}전체 개방형{es}Totalmente Abierto{fr}Entièrement Ouvert{pt-br}Totalmente Aberto{de}Vollständig Offen" then gridType="https://steamusercontent-a.akamaihd.net/ugc/1674736055049031257/2457D03CE33118D57CD456183026FEB596CF6A3A/" end--fully
	if scenarioList[gStates.scenarioRef][gStates.playersRef].mapShape=="{en}Wedge{ru}Клиновидное поле{zh-cn}锥形地图{ko}쐐기형{es}En Cuña{fr}Coin{pt-br}Cônico{de}Keil" then gridType="https://steamusercontent-a.akamaihd.net/ugc/1674736055049113832/44EE3C6AA10498BCD1B46040AD18631BFD580AC4/" end--Wedge
	if gStates.gameScenario=="The Gauntlet" then gridType="https://steamusercontent-a.akamaihd.net/ugc/1673610837369514853/1BBAD048566E753F09184CBAE7022049D90B5471/" end
	Global.setDecals({})
	if gridType~="" then Global.addDecal({name="Terrain Grid", url=gridType, position={-16.825, 0.99, 0.55}, rotation={90.0, 0.0, 0.0}, scale={60, 60, 1}}) end

	--shuffle the order of data in a table
	function listShuffle(array)
		--Remove lost legion GUIDs
		if gStates.removeLostLegionExpansion==true then
			local tempArray={}
			local lostLegionTiles={"29a93c", "7ce33f", "0bf020", "de7fad", "cff250"}
			for a=1, #array, 1 do
				local found=false
				for b=1, #lostLegionTiles, 1 do
					if array[a]==lostLegionTiles[b] then found=true end
				end
				if found==false then tempArray[#tempArray+1]=array[a] end
			end
			array=tempArray
		end
		--shuffle the list
		math.randomseed(os.time())
		local tReturn={}
		for a=#array, 1, -1 do
			local b=math.random(a)
			array[a], array[b]=array[b], array[a]
			table.insert(tReturn, array[a])
		end
		return tReturn
	end

	--Pull City Tiles
	local warOfFourCityTilePos={{-32.4304, 1.15, -1.5341}, {-25.2302, 1.15, -9.8482}, {-28.8303, 1.15, 8.8586}, {-22.8301, 1.15, 6.7794}, {-15.6299, 1.15, -1.5341}, {-14.4298, 1.15, -7.7696}}
	local warOfFourCoreTilePos={{-24.0301, 1.15, 13.0156}, {-16.8299, 1.15,  4.7015}, {-9.6297, 1.15, -3.6126}}
	for i=1, gStates.cityTiles, 1 do
		local noShuffle=0
		local params={rotation={0, 180, 180}, smooth=false}
		if gStates.randomTileOrientation==true then params.rotation={0, math.random(1,6)*60, 180} end
		if i==1 and (gStates.gameScenario=="Mines Liberation" or gStates.gameScenario=="Life and Death" or gStates.gameScenario=="The Chaos Rift" or gStates.gameScenario=="Raiders of the Crusader Temple") then params.guid="53d847" end--Use Red City
		if i==1 and (gStates.gameScenario=="Dungeon Lords" or gStates.gameScenario=="The Realm of the Dead Blitz") then params.guid="63f201" end--Use Blue City
		if i==1 and (gStates.gameScenario=="Conquer and Hold" or gStates.gameScenario=="The Hidden Valley Blitz") then params.guid="a3ce11" end--Use White City
		if (gStates.gameScenario=="Druid Nights" and i==1) or (gStates.gameScenario=="The Realm of the Dead Blitz" and i==2) or (gStates.gameScenario=="Life and Death" and i==2) or (gStates.gameScenario=="The Hidden Valley Blitz" and i==2) then params.guid="314081" end--Use Green City
		if (gStates.gameScenario=="Volkare's Return" and i==1) or gStates.gameScenario=="Volkare's Return Blitz" or gStates.gameScenario=="The Chaos Rift" then params.position={pos.x, pos.y+tUp, pos.z} tUp=tUp+0.5 noShuffle=1 end--puts city at bottom of stack
		if gStates.gameScenario=="The Gauntlet" and i==1 then params.guid="53d847" params.position={4.7708, 0.96, 8.8586} noShuffle=1 end
		if gStates.gameScenario=="The War of Four" then
			local randPos=math.random(1,#warOfFourCityTilePos)
			if warOfFourCityTilePos[randPos][1]==-28.8303 or warOfFourCityTilePos[randPos][1]==-15.6299 then
				warOfFourCoreTilePos[#warOfFourCoreTilePos+1]=warOfFourCityTilePos[randPos+1]
				table.remove(warOfFourCityTilePos, randPos+1)
			end
			params.position=warOfFourCityTilePos[randPos]
			noShuffle=1
			if warOfFourCityTilePos[randPos][1]==-22.8301 or warOfFourCityTilePos[randPos][1]==-14.4298 then
				warOfFourCoreTilePos[#warOfFourCoreTilePos+1]=warOfFourCityTilePos[randPos-1]
				table.remove(warOfFourCityTilePos, randPos-1)
				table.remove(warOfFourCityTilePos, randPos-1)
			else
				table.remove(warOfFourCityTilePos, randPos)
			end
		end
		local obj=CityTileStack.takeObject(params)--take from the City Tile Bag
		if noShuffle==0 then TileShuffler.putObject(obj) end--Place in the Core Tile Shuffler if it is shuffled
		if gStates.gameScenario=="Ultimate Conquest" and i==4 then break end
	end

	--Pull Core Tiles
	local CoreKeepMageTiles={"155a31","be86ec","264fa0","cff250","de7fad"} CoreKeepMageTiles=listShuffle(CoreKeepMageTiles)
	local CoreGauntletTiles={"155a31","264fa0","cff250","de7fad"} CoreGauntletTiles=listShuffle(CoreGauntletTiles)
	local CoreMineTiles=	{"155a31","264fa0","be86ec"} CoreMineTiles=listShuffle(CoreMineTiles)
	local CoreRuinTiles=	{"be86ec","264fa0","155a31"} CoreRuinTiles=listShuffle(CoreRuinTiles)
	for i=1, scenarioList[gStates.scenarioRef][gStates.playersRef].coreTiles, 1 do
		local params={rotation={0, 180, 180}, smooth=false}
		if gStates.gameScenario=="Mines Liberation" then params.guid=CoreMineTiles[i] end
		if gStates.gameScenario=="Conquer and Hold" then params.guid=CoreKeepMageTiles[i] end
		if gStates.gameScenario=="Dungeon Lords" and i==1 then params.guid="584237" end
		if gStates.gameScenario=="The Gauntlet" and i<=4 then params.guid=CoreGauntletTiles[i] end
		if gStates.gameScenario=="Raiders of the Crusader Temple" and i<=3 then params.guid=CoreRuinTiles[i] end
		--local obj=CoreTileStack.takeObject(params)--Core Tile Bag
		TileShuffler.putObject(CoreTileStack.takeObject(params))--Core Tile Shuffler
	end
	--Ultimate Conquest Country mix
	if gStates.gameScenario=="Ultimate Conquest" then
		local megaCountry=14-scenarioList[gStates.scenarioRef][gStates.playersRef].countryTiles
		if gStates.removeLostLegionExpansion==true then megaCountry=megaCountry-3 end
		for i=1, megaCountry, 1 do
			local params={rotation={0, 180, 180}, smooth=false}
			TileShuffler.putObject(CountryTileStack.takeObject(params))
		end
	end

	--place core and city tiles on stack shuffled
	TileShuffler.shuffle()
	local VolQuestTilePos=		{{-18.0299, 1.15, 10.9371}, {-16.8299, 1.15,  4.7015}, {-22.8301, 1.15,  6.7794}, {-10.8297, 1.15,  2.6230}, {-15.6299, 1.15, -1.5341}, {-9.6297, 1.15, -3.6126}, {-14.4298, 1.15, -7.7696}, {-21.6300, 1.15, 0.5445}}
	local ConquerAndHoldTilePos={{-27.6302, 1.15,  2.6230}, {-21.6300, 1.15,  0.5445}, {-26.4302, 1.15, -3.6126}, {-20.4300, 1.15, -5.6911}}
	local GauntletTilePos=		{{ -0.0294, 1.15,  4.7015}, { -4.8295, 1.15,  0.5445}, { -9.6297, 1.15, -3.6126}}
	for i=1, TileShuffler.getQuantity(), 1 do
		local params={smooth=false}
		if gStates.randomTileOrientation==false then params.rotation={0, 180, 180} else params.rotation={0, math.random(1,6)*60, 180} end
		if gStates.gameScenario=="Volkare's Quest" then
			if i==6 and gStates.playersRef==5 then
				params.position=VolQuestTilePos[8]
			else
				params.position=VolQuestTilePos[i]
			end
		end
		if gStates.gameScenario=="The War of Four" then
			params.position=warOfFourCoreTilePos[i]
		end
		if gStates.gameScenario=="Conquer and Hold" then params.position=ConquerAndHoldTilePos[i] end
		if gStates.gameScenario=="The Gauntlet" then params.position=GauntletTilePos[i] end
		if params.position==nil then params.position={pos.x, pos.y+tUp, pos.z} tUp=tUp+0.5 end
		TileShuffler.takeObject(params)
	end

	--Pull Country Tiles
	local CountryGauntletTiles=			{"7ce33f", "0bf020", "29a93c", "6510ac", "05b612", "78fc79", "20607e", "208d84", "184fb7", "a26c4f", "a501d6", "ca8ad3", "e2ecf8"} CountryGauntletTiles=listShuffle(CountryGauntletTiles)
	local CountryTileOrder=				{"a501d6", "a26c4f", "184fb7", "208d84", "20607e", "78fc79", "05b612", "6510ac", "d21095", "ca8ad3", "e2ecf8"}--3,4,5,6,7,8,9,10,11,2,1
	local CountryNonMonasteryTiles=		{"7ce33f", "0bf020", "d21095", "6510ac", "78fc79", "20607e", "208d84", "a26c4f", "a501d6", "ca8ad3", "e2ecf8"} CountryNonMonasteryTiles=listShuffle(CountryNonMonasteryTiles)
	local CountryNonMineTiles=			{"20607e", "e2ecf8", "6510ac", "05b612", "78fc79", "d21095", "a26c4f", "29a93c"} CountryNonMineTiles=listShuffle(CountryNonMineTiles)
	local CountryNotGladeTiles=			{"a501d6", "a26c4f", "208d84", "05b612", "6510ac", "d21095", "29a93c", "7ce33f"} CountryNotGladeTiles=listShuffle(CountryNotGladeTiles)
	local CountryMonasteryMageTiles=	{"a26c4f", "184fb7", "20607e", "05b612", "d21095", "29a93c", "0bf020"} CountryMonasteryMageTiles=listShuffle(CountryMonasteryMageTiles)
	local CountryNotMonasteryMageTiles=	{"e2ecf8", "ca8ad3", "a501d6", "208d84", "78fc79", "6510ac", "7ce33f"} CountryNotMonasteryMageTiles=listShuffle(CountryNotMonasteryMageTiles)
	local CountryKeepMageTiles=			{"a501d6", "a26c4f", "05b612", "6510ac", "d21095", "0bf020", "7ce33f"} CountryKeepMageTiles=listShuffle(CountryKeepMageTiles)
	local CountryGladeTiles=			{"e2ecf8", "ca8ad3", "20607e", "78fc79", "0bf020", "184fb7"} CountryGladeTiles=listShuffle(CountryGladeTiles)
	local CountryMineTiles=				{"a501d6", "ca8ad3", "208d84", "184fb7"}
	local CountryMonasteryTiles=		{"184fb7", "05b612", "29a93c"} CountryMonasteryTiles=listShuffle(CountryMonasteryTiles)
	local CountryDungeonTiles=			{"05b612", "20607e"}
	local CountryRuinTiles=				{"6510ac", "d21095", "78fc79"} CountryRuinTiles=listShuffle(CountryRuinTiles)
	local count=0
	if gStates.removeTerrain==true then
		getObjectFromGUID(trashCan).putObject(CountryTileStack.takeObject({guid="e2ecf8"}))
		getObjectFromGUID(trashCan).putObject(CountryTileStack.takeObject({guid="ca8ad3"}))
	end
	for i=1, scenarioList[gStates.scenarioRef][gStates.playersRef].countryTiles, 1 do
		local params={rotation={0, 180, 180}, smooth=false}
		if gStates.gameScenario=="First Reconnaissance" and i<=scenarioList[gStates.scenarioRef][gStates.playersRef].countryTiles-2 then params.guid=CountryTileOrder[i] end
		if gStates.gameScenario=="First Reconnaissance" and i>=scenarioList[gStates.scenarioRef][gStates.playersRef].countryTiles-1 then params.guid=CountryTileOrder[i+(11-scenarioList[gStates.scenarioRef][gStates.playersRef].countryTiles)] end
		if gStates.gameScenario=="Mines Liberation" and i<=4 then params.guid=CountryMineTiles[i] end
		if gStates.gameScenario=="Mines Liberation" and i>=5 then params.guid=CountryNonMineTiles[i-4] end
		if gStates.gameScenario=="Conquer and Hold" then params.guid=CountryKeepMageTiles[i] end
		if gStates.gameScenario=="The Gauntlet" then params.guid=CountryGauntletTiles[i] end
		if gStates.gameScenario=="Druid Nights" and i<=5 then params.guid=CountryGladeTiles[i] end
		if gStates.gameScenario=="Druid Nights" and i>5 then params.guid=CountryNotGladeTiles[i-5] end
		if gStates.gameScenario=="Dungeon Lords" and i<=2 then params.guid=CountryDungeonTiles[i] end
		if (gStates.gameScenario=="Quest for the Golden Grail" or gStates.gameScenario=="The Chaos Rift") and i<=4 then params.guid=CountryMonasteryMageTiles[i] end
		if (gStates.gameScenario=="Quest for the Golden Grail" or gStates.gameScenario=="The Chaos Rift") and i>=5 then params.guid=CountryNotMonasteryMageTiles[i-4] end
		if gStates.gameScenario=="Life and Death" and ((i<=gStates.playerCount+1 and gStates.playerCount>=2) or (i<=gStates.playerCount+2 and gStates.playerCount==1)) then params.guid=CountryGladeTiles[i] count=count+1 end
		if gStates.gameScenario=="Life and Death" and ((i>=gStates.playerCount+2 and gStates.playerCount>=2) or (i>=gStates.playerCount+3 and gStates.playerCount==1)) then params.guid=CountryNotGladeTiles[i-count] end
		if gStates.gameScenario=="The Realm of the Dead Blitz" and ((i<=gStates.playerCount+1 and gStates.coop==1) or (i<=gStates.playerCount and gStates.coop==0)) then params.guid=CountryGladeTiles[i] count=count+1 end
		if gStates.gameScenario=="The Realm of the Dead Blitz" and ((i>=gStates.playerCount+2 and gStates.coop==1) or (i>=gStates.playerCount+1 and gStates.coop==0)) then params.guid=CountryNotGladeTiles[i-count] end
		if gStates.gameScenario=="Raiders of the Crusader Temple" and i<=3 then params.guid=CountryRuinTiles[i] end
		--local obj=CountryTileStack.takeObject(params)--Country Tile Bag
		TileShuffler.putObject(CountryTileStack.takeObject(params))
	end

	--place Country tiles on stack shuffled
	if gStates.gameScenario~="First Reconnaissance" then TileShuffler.shuffle() end
	local rot={}
	if scenarioList[gStates.scenarioRef][gStates.playersRef].mapShape:sub(5,5)=="W" then
		if gStates.randomTileOrientation==false then rot={0, 180, 180} else rot={0, math.random(1,6)*60, 180} end
		TileShuffler.takeObject({position={-25.2302, 1.07, -9.8482}, rotation=rot, smooth=false, callback_function=function(obj) Wait.time(function() gStates.firstStarted=true firstTile=obj.guid obj.flip() end, 1) end})
		if gStates.randomTileOrientation==false then rot={0, 180, 180} else rot={0, math.random(1,6)*60, 180} end
		TileShuffler.takeObject({position={-19.2300, 1.07, -11.9267}, rotation=rot, smooth=false, callback_function=function(obj) Wait.time(function() obj.flip() end, 2) end})
		if gStates.gameScenario=="The Chaos Rift" then
			if gStates.randomTileOrientation==false then rot={0, 180, 180} else rot={0, math.random(1,6)*60, 180} end
			TileShuffler.takeObject({position={-20.4300, 1.09, -5.6911}, rotation=rot, smooth=false})
		end
	else
		if gStates.randomTileOrientation==false then rot={0, 180, 180} else rot={0, math.random(1,6)*60, 180} end
		if gStates.gameScenario~="The Gauntlet" and gStates.gameScenario~="Volkare's Return" and gStates.gameScenario~="Volkare's Return Blitz" then TileShuffler.takeObject({position={-37.2305, 1.07, -5.6911}, rotation=rot, smooth=false, callback_function=function(obj) tile1=obj Wait.time(function() gStates.firstStarted=true firstTile=tile1.guid tile1.flip() end, 1) end}) end
		if gStates.gameScenario=="Volkare's Return" or gStates.gameScenario=="Volkare's Return Blitz" then Wait.time(function() getObjectFromGUID("835c91").setPosition({-37.2305, 1.15, -5.6911}) getObjectFromGUID("835c91").flip() end, 1) end
		if gStates.randomTileOrientation==false then rot={0, 180, 180} else rot={0, math.random(1,6)*60, 180} end
		TileShuffler.takeObject({position={-31.2303, 1.07, -7.7696}, rotation=rot, smooth=false, callback_function=function(obj) Wait.time(function() obj.flip() end, 2) end})
		if gStates.randomTileOrientation==false then rot={0, 180, 180} else rot={0, math.random(1,6)*60, 180} end
		if gStates.gameScenario~="The Gauntlet" then TileShuffler.takeObject({position={-30.0303, 1.07, -14.0000}, rotation=rot, smooth=false, callback_function=function(obj) Wait.time(function() obj.flip() end, 3) end}) end
		if gStates.gameScenario=="Volkare's Quest" or gStates.gameScenario=="The War of Four" then Wait.time(function() getObjectFromGUID("835c91").setPosition({-12.0297, 1.15, 8.8586}) getObjectFromGUID("835c91").flip() end, 3) end
	end
	local VolQuestTilePos=		  {{-32.4304, 1.15, -1.5341}, {-27.6302, 1.15,   2.6230}, {-26.4302, 1.15, -3.6126}, {-25.2302, 1.15, -9.8482}, {-20.4300, 1.15,  -5.6911}, {-21.6300, 1.15,   0.5445}, {-24.0301, 1.15, -16.0837}, {-19.2300, 1.15, -11.9267}, {-14.4298, 0.15, -7.7696}}
	local warOfFourCountryTilePos={{-38.4306, 1.15,  0.5445}, {-27.6302, 1.15,   2.6230}, {-26.4302, 1.15, -3.6126}, {-33.6304, 1.15, 4.7015},  {-20.4300, 1.15,  -5.6911}, {-21.6300, 1.15,   0.5445}, {-24.0301, 1.15, -16.0837}, {-19.2300, 1.15, -11.9267}, {-18.0299, 1.15, 10.9371}, {-10.8297, 1.15, 2.6230}}
	local GauntletTilePos=		  {{-14.4298, 1.15, -7.7696}, {-19.2300, 1.15, -11.9267}, {-12.0297, 1.15,  8.8586}, {-16.8299, 1.15,  4.7015}, {-21.6300, 1.15,   0.5445}, {-26.4302, 1.15,  -3.6126}}
	local ConquerAndHoldTilePos=  {{-32.4304, 1.15, -1.5341}, {-25.2302, 1.15,  -9.8482}}
	for i=1, TileShuffler.getQuantity(), 1 do
		local params={smooth=false}
		if gStates.randomTileOrientation==false then params.rotation={0, 180, 180} else params.rotation={0, math.random(1,6)*60, 180} end
		if gStates.gameScenario=="Volkare's Quest" then params.position=VolQuestTilePos[i] end
		if gStates.gameScenario=="Conquer and Hold" then params.position=ConquerAndHoldTilePos[i] end
		if gStates.gameScenario=="The War of Four" then params.position=warOfFourCountryTilePos[i] end
		if gStates.gameScenario=="The Gauntlet" then params.position=GauntletTilePos[i] end
		if params.position==nil then params.position={pos.x, pos.y+tUp, pos.z} tUp=tUp+0.5 end
		TileShuffler.takeObject(params)
	end
end

------------------
-- During the Game
------------------
--Update the text in the Main User Interface
local mainUIPause=nil
local levelUpcalled=false
local gameOver=false
function mainUIUpdate(source)
	if gStates.firstStarted==true then
		if mainUIPause~=nil then Wait.stop(mainUIPause) end
		mainUIPause=Wait.time(function()
			local playerAreaCards={}
			local nextPlayer=nextTurnMerged("nextMage")
			local nextPlayerEndCalled=turnOrder[nextPlayer].endCalled
			if nextPlayerEndCalled~=true then nextPlayerEndCalled=turnOrder[nextTurnMerged("nextMageSkipDummy")].endCalled end

			--add missing skill locations and seperate any over lapping.
			local double={}
			for skillGUID, _ in pairs(skillTokens) do
				if getObjectFromGUID(skillGUID)~=nil then
					local objPos=getObjectFromGUID(skillGUID).getPosition()
					if gStates.mageSkills[skillGUID]==nil then
						gStates.mageSkills[skillGUID]={objPos[1], objPos[2], objPos[3]}
					end
					if double[(math.floor(gStates.mageSkills[skillGUID][1]/0.3)*0.3)..(math.floor(gStates.mageSkills[skillGUID][3]/0.3)*0.3)]~=nil then
						gStates.mageSkills[skillGUID][1]=gStates.mageSkills[skillGUID][1]+0.4
						gStates.mageSkills[skillGUID][3]=gStates.mageSkills[skillGUID][3]-0.4
					end
					double[(math.floor(gStates.mageSkills[skillGUID][1]/0.3)*0.3)..(math.floor(gStates.mageSkills[skillGUID][3]/0.3)*0.3)]="taken"
				end
			end

			--count cards in play area
			local playAreaObjects={}
			if getObjectFromGUID(playerPlayAreas[turnOrder[gStates.turnNumber].seatPos])~=nil then playAreaObjects=getObjectFromGUID(playerPlayAreas[turnOrder[gStates.turnNumber].seatPos]).getObjects() end
			for _, obj in pairs(playAreaObjects) do
				--seperate any cards that have acidently combined
				if obj.type=="Deck" and obj.getQuantity()==2 and turnOrder[gStates.turnNumber].gameEnder~=true then
					obj.takeObject({position={obj.getPosition()[1]+0.7, obj.getPosition()[2]+0.1, obj.getPosition()[3]+0.7}})
				end
				if (gameCards[obj.guid]~=nil and gameCards[obj.guid].full==nil) or (gameCards[obj.guid]~=nil and gStates.bannercard[obj.guid]==nil) or obj.getName()=="Wound" then playerAreaCards[#playerAreaCards+1]=obj end
			end

			--shrink cards when too many in play area
			for _, obj in pairs(playAreaObjects) do
				if ((gameCards[obj.guid]~=nil and gameCards[obj.guid].full==nil) or obj.getName()=="Wound") then
					if #playerAreaCards>7 then obj.setScale({1.2, 1, 1.2}) else obj.setScale({1.5, 1, 1.5})	end
				end
			end

			--seperate any units that have acidently combined
			local unitAreaCards=getObjectFromGUID(playerUnitAreas[turnOrder[gStates.turnNumber].seatPos])
			if unitAreaCards~=nil then
				for _, obj in pairs(unitAreaCards.getObjects()) do
					--seperate any cards that have acidently combined
					if obj.type=="Deck" and obj.getQuantity()==2 then
						obj.takeObject({position={obj.getPosition()[1]+0.7, obj.getPosition()[2]+0.1, obj.getPosition()[3]+0.7}})
					end
				end
			end

			--Relocate city scripting zones
			for _, cityDetails in pairs(cityScriptZones) do
				if gStates.cityCard[cityDetails.cityGUID]~=nil then cityDetails.cityCard=gStates.cityCard[cityDetails.cityGUID] end
			end
			for zone, cityDetails in pairs(cityScriptZones) do
				if getObjectFromGUID(zone)~=nil then
					if getObjectFromGUID(cityDetails.cityCard)~=nil and gStates.cityMonsterQty[cityDetails.cityGUID]~=nil and (gStates.cityMonsterQty[cityDetails.cityGUID].extra.megapolisPair==nil or gStates.cityMonsterQty[cityDetails.cityGUID].extra.megapolisPair~=cityDetails.cityGUID) then
						local zonescale={x=4.6, y=1, z=3.3}
						local monsterOffset={1.15, -0.7}
						local count=0
						if zone==volkare.discZone then zonescale={x=7.5, y=1, z=7.5} monsterOffset={5.5, -1} end
						if zone==darkCrusader.discZone or zone==elementalist.discZone then zonescale={x=7.5, y=1, z=7.5} monsterOffset={-5.5, -1} end
						if getObjectFromGUID(cityDetails.cityCard).getScale()[1]==1.5 then zonescale={x=4.6, y=1, z=4.6} end
						getObjectFromGUID(zone).setScale(zonescale)
						local tempPos=getObjectFromGUID(cityDetails.cityCard).getPosition()
						getObjectFromGUID(zone).setPosition({tempPos[1], 1.4, tempPos[3]})
						--update defender location to current city card position.
						if gStates.cityMonsterQty[cityDetails.cityGUID]~=nil then
							for monsterGUID, state in pairs(gStates.cityMonsterQty[cityDetails.cityGUID]) do
								if monsterGUID~="shieldNeeded" and gStates.monsterPlayLocation[monsterGUID]~=nil and getObjectFromGUID(monsterGUID)~=nil then
									gStates.monsterPlayLocation[monsterGUID][1]=tempPos[1]+monsterOffset[1]
									gStates.monsterPlayLocation[monsterGUID][2]=1+(0.6*count)
									gStates.monsterPlayLocation[monsterGUID][3]=tempPos[3]+monsterOffset[2]+(0.4*count)
									count=count+1
								end
							end
						end
					end
				end
			end

			--Update the Fame for all Mage Knight
			for a=1, #turnOrder, 1 do
				if turnOrder[a].mage~=gStates.positionMageKnight[5] then
					local fameVerticle=math.ceil((topOfFameBoard-getObjectFromGUID(turnOrder[a].fameGUID).getPosition()[3])/heightOfFameBoard*gStates.rowsOnBoard)
					local levelRowFameQuantity=(((fameVerticle-1)*cellGainPerLevel)+normalCellAmount)
					local levelRowLength=(((fameVerticle-1)*gStates.rowLengthGainPerLevel)+gStates.normalRowLength)
					local fameHorizontal=math.ceil((getObjectFromGUID(turnOrder[a].fameGUID).getPosition()[1]-leftOfFameBoard)/levelRowLength*levelRowFameQuantity)
					local fameValue=(3*(fameVerticle-1)+2*(fameVerticle-2)*(fameVerticle-1)/2-1+fameHorizontal)+(gStates.scoreIfLooped*turnOrder[a].scoreLoop)
					local test=fameValue-turnOrder[a].fame
					turnOrder[a].fame=fameValue
					if test<-20 then turnOrder[a].scoreLoop=turnOrder[a].scoreLoop+1 turnOrder[a].fame=fameValue+gStates.scoreIfLooped end
					if test>80 then turnOrder[a].scoreLoop=turnOrder[a].scoreLoop-1 turnOrder[a].fame=fameValue-gStates.scoreIfLooped end
					if turnOrder[a].scoreLoop>0 then getObjectFromGUID(turnOrder[a].fameGUID).highlightOn({1, 0.9, 0}) end -- else getObjectFromGUID(turnOrder[a].fameGUID).highlightOff({1, 0.9, 0}) end
				end
			end

			--Out of Turn Menu visibility
			UI.setAttribute("OutOfTurnActions", "active", "false")
			local count=0
			if gStates.tacticRemove==false and gStates.tacticShown==false then
				for a=1, #turnOrder, 1 do
					UI.setAttribute("Plunder"..tostring(turnOrder[a].seatPos), "active", "false")
					UI.setAttribute("Pursuit"..tostring(turnOrder[a].seatPos), "active", "false")
					UI.setAttribute("NightTactic2-"..tostring(turnOrder[a].seatPos), "active", "false")
					UI.setAttribute("NightTactic4-"..tostring(turnOrder[a].seatPos), "interactable", "false")
					UI.setAttribute("NightTactic4-"..tostring(turnOrder[a].seatPos), "active", "false")
					UI.setAttribute("NightTactic6Store"..tostring(turnOrder[a].seatPos), "active", "false")
					UI.setAttribute("NightTactic6Claim"..tostring(turnOrder[a].seatPos), "active", "false")
					UI.setAttribute("MasterOfChaos"..tostring(turnOrder[a].seatPos), "active", "false")
					for skillGUID, stats in pairs(gStates.motivationSkill) do
						UI.setAttribute(skillGUID.."-Motivation"..tostring(turnOrder[a].seatPos), "active", "false")
					end

					--Plunder Village Buttons
					if turnOrder[a].mage~=gStates.positionMageKnight[5] and turnOrder[a].avatarLocation~=nil and turnOrder[a].avatarLocation=="village" and (a~=gStates.turnNumber or (a==gStates.turnNumber and #playerAreaCards<1 and gStates.preEndTurn~=true)) and turnOrder[a].pillagedVillage~=true then
						UI.setAttribute("Plunder"..tostring(turnOrder[a].seatPos), "active", "true")
						UI.setAttribute("Plunder"..tostring(turnOrder[a].seatPos.."Text"), "text", joinLang({translateWord[turnOrder[a].mage], "{en} Plunders the Village{ru} разграбляет деревню{zh-cn}掠夺村庄{ko} 마을약탈{es} Saquea la Aldea{fr} Pille le Village{pt-br} saqueia a Vila{de} Plündert das Dorf"}))
						UI.setAttribute("Plunder"..tostring(turnOrder[a].seatPos.."Image"), "color", positionToColor(a))
						count=count+1
					end

					--skip movement button.
					local found=false
					if gStates.pursuingMonsters[turnOrder[gStates.turnNumber].mage]~=nil then
						for _, state in pairs(gStates.pursuingMonsters[turnOrder[gStates.turnNumber].mage]) do
							if state~=nil and state.state=="Pursuing" then found=true end
						end
					end
					if found==true and a==gStates.turnNumber and gStates.skippedMove==false and gStates.preEndTurn==false then
						local playerPos={}
						for _, details in pairs(mageKnights) do
							if details.mage==turnOrder[gStates.turnNumber].mage then
								if getObjectFromGUID(details.model)~=nil then playerPos=getObjectFromGUID(details.model).getPosition() end
								if getObjectFromGUID(details.token)~=nil then playerPos=getObjectFromGUID(details.token).getPosition() end
								if getObjectFromGUID(details.standee)~=nil then playerPos=getObjectFromGUID(details.standee).getPosition() end
							end
						end
						if math.sqrt(((turnOrder[gStates.turnNumber].turnStartLoc.x-playerPos[1])^2)+((turnOrder[gStates.turnNumber].turnStartLoc.z-playerPos[3])^2))<1.5 then
							UI.setAttribute("Pursuit"..tostring(turnOrder[gStates.turnNumber].seatPos), "active", "true")
							UI.setAttribute("Pursuit"..tostring(turnOrder[gStates.turnNumber].seatPos.."Text"), "text", joinLang({translateWord[turnOrder[gStates.turnNumber].mage], "{en} skips their Move Phase{ru} пропускает свою фазу движения{zh-cn}跳过他们的移动阶段{ko} 이동 단계 건너뛰기{es} se salta su Fase de Movimiento{fr} saute sa Phase de Mouvement{pt-br} Pula sua fase de movimentação{de} überspringt seine Bewegungsphase"}))
							UI.setAttribute("Pursuit"..tostring(turnOrder[gStates.turnNumber].seatPos.."Image"), "color", positionToColor(a))
							count=count+1
						end
					end

					--Night tactic 2 buttons
					if turnOrder[a].tactic==2 and gStates.dayRound==false and gStates.tacticTwoState~="Used" and turnOrder[a].mage~=gStates.positionMageKnight[5] then
						local found=false
						for c, b in pairs(getObjectFromGUID(deedDeckZones[turnOrder[a].seatPos]).getObjects()) do
							if b.type=="Deck" or b.type=="Card" then found=true break end
						end
						if found==false then
							UI.setAttribute("NightTactic2-"..tostring(turnOrder[a].seatPos), "active", "true")
							UI.setAttribute("NightTactic2-"..tostring(turnOrder[a].seatPos.."Text"), "text", joinLang({translateWord[turnOrder[a].mage], "{en} Uses Night Tactic 2{ru} Использует ночную Тактику 2{zh-cn}发动战术卡2的效果{ko} 밤 전략 2 사용{es} Usa Táctica de Noche 2{fr} Utilise de nuit 2{pt-br} Usa Tática da Noite 2{de} Benutzt Nacht-Taktik 2"}))
							UI.setAttribute("NightTactic2-"..tostring(turnOrder[a].seatPos.."Image"), "color", positionToColor(a))
							count=count+1
						end
					end

					--Night Tactic 4 Buttons
					if turnOrder[a].tactic==4 and (a~=gStates.turnNumber or (a==gStates.turnNumber and #playerAreaCards<1)) and gStates.dayRound==false and gStates.tacticFourState~="Used" and turnOrder[a].mage~=gStates.positionMageKnight[5] then
						--check if deed deck is bigger than recorded
						for _, b in pairs(getObjectFromGUID(deedDeckZones[turnOrder[a].seatPos]).getObjects()) do
							if b.type=="Deck" or b.type=="Card" then
								local deedDeckSize=1
								if b.type=="Deck" then deedDeckSize=b.getQuantity() end
								UI.setAttribute("NightTactic4-"..tostring(turnOrder[a].seatPos), "active", "true")
								UI.setAttribute("NightTactic4-"..tostring(turnOrder[a].seatPos.."Text"), "text", joinLang({translateWord[turnOrder[a].mage], "{en} Tactic 4 ReDraw {ru} Тактика 4 - Вытянуть {zh-cn}战术卡4-声明重选{ko} 전략 4 사용{es} Táctica 4 Volver a Robar {fr} Tactique 4 Redessiner {pt-br} Tatica 4 Re-Compre {de} Taktik 4 Nachziehen ", deedDeckSize-turnOrder[a].deedCount, "{en} Card(s){ru} Карт(у/ы){zh-cn}张卡{ko} 장의 카드{es} Carta(s){fr} Cartes){pt-br} Carta(s){de} Karte(n)"}))
								UI.setAttribute("NightTactic4-"..tostring(turnOrder[a].seatPos.."Image"), "color", positionToColor(a))
								count=count+1
								if turnOrder[a].deedCount<deedDeckSize then
									--count all cards in deck that have been recorded as part of your hand
									if deedDeckSize-turnOrder[a].deedCount>0 and deedDeckSize-turnOrder[a].deedCount<6 then UI.setAttribute("NightTactic4-"..tostring(turnOrder[a].seatPos), "interactable", "true") end
								end
								break
							end
						end
					end

					--Night Tactic 6 Buttons - and a~=gStates.turnNumber
					if turnOrder[a].tactic==6 and (a~=gStates.turnNumber or (a==gStates.turnNumber and #playerAreaCards<1)) and gStates.dayRound==false and gStates.tacticSixState~="Stored" and gStates.tacticSixState~="Used" and turnOrder[a].mage~=gStates.positionMageKnight[5] then
						local found=false
						for x, b in pairs(getObjectFromGUID(deedDeckZones[turnOrder[a].seatPos]).getObjects()) do
							if b.name=="Card" or b.name=="Deck" then
								UI.setAttribute("NightTactic6Store"..tostring(turnOrder[a].seatPos), "active", "true")
								UI.setAttribute("NightTactic6Store"..tostring(turnOrder[a].seatPos).."Text", "text", joinLang({translateWord[turnOrder[a].mage], "{en} Tactic 6 - Store a Card{ru} Тактика 6 — Сберечь карту{zh-cn}战略6-储存一张卡牌{ko} 전략 6 - 카드 비축{es} Táctica 6 - Almacenar Carta{fr} Tactique 6 - Stocker une Carte{pt-br} Tática 6 - Guardar uma Carta{de} Taktik 6 - Eine Karte aufbewahren"}))
								UI.setAttribute("NightTactic6Store"..tostring(turnOrder[a].seatPos).."Image", "color", positionToColor(a))
								count=count+1
								found=true
								break
							end
						end
						if found==false then nightTactic6({color="Black"}, "-1", "NightTactic6Claim") end
						if #gStates.powerStored>0 then
							UI.setAttribute("NightTactic6Claim"..tostring(turnOrder[a].seatPos), "active", "true")
							UI.setAttribute("NightTactic6Claim"..tostring(turnOrder[a].seatPos).."Text", "text", joinLang({translateWord[turnOrder[a].mage], "{en} Tactic 6 - Claim {ru} Тактика 6 - Забрать {zh-cn}战术卡6-声明使用{ko} 전략 6 사용 - {es} Táctica 6 - Reclamar {fr} Tactique 6 - Réclamation {pt-br} Tática 6 - Clamar {de} Taktik 6 – Anspruch ", tostring(#gStates.powerStored), "{en} Card(s){ru} Карт(у/ы){zh-cn}张卡{ko} 장의 카드{es} Carta(s){fr} Cartes){pt-br} Carta(s){de} Karte(n)"}))
							UI.setAttribute("NightTactic6Claim"..tostring(turnOrder[a].seatPos).."Image", "color", positionToColor(a))
							count=count+1
						end
					end

					--Motivation Skills
					for skillGUID, stats in pairs(gStates.motivationSkill) do
						if stats.pos==turnOrder[a].seatPos and stats.state=="active" then
							--check if another motivation skill has been used
							local test=false
							for _, stats2 in pairs(gStates.motivationSkill) do
								if stats2.pos==turnOrder[a].seatPos and stats2.state=="used" then test=true end
							end
							if test==false then
								UI.setAttribute(skillGUID.."-Motivation"..tostring(turnOrder[a].seatPos), "active", "true")
								UI.setAttribute(skillGUID.."-Motivation"..tostring(turnOrder[a].seatPos).."Text", "text", joinLang({"{en}Use {ru}{zh-cn}使用{ko}{es}Usa la Habilidad Motivación de {fr}Utilisez la compétence de motivation de {pt-br}Habilidade Motivacional de {de}Verwenden ", translateWord[skillTokens[skillGUID].mage], "{en}'s Motivation Skill{ru} использует навык Мотивация{zh-cn}的“激励”技能{ko}의 동기부여 스킬 사용{es}.{fr}.{pt-br}.{de}'s Motivations Fähigkeit"}))
								UI.setAttribute(skillGUID.."-Motivation"..tostring(turnOrder[a].seatPos), "tooltip", "Draw two cards")
								local lowestFame=1
								--Work out lowest fame
								for b=2, #turnOrder, 1 do
									if turnOrder[b].mage~=gStates.positionMageKnight[5] then
										if turnOrder[b].fame<turnOrder[lowestFame].fame or turnOrder[lowestFame].mage==gStates.positionMageKnight[5] then lowestFame=b end
									end
								end
								for b=1, #turnOrder, 1 do if turnOrder[b].fame==turnOrder[lowestFame].fame and b~=lowestFame then lowestFame=0 break end end--find tied lowest fame
								if a==lowestFame then
									UI.setAttribute(skillGUID.."-Motivation"..tostring(turnOrder[a].seatPos).."Text", "text", joinLang({"{en}Use {ru}{zh-cn}使用{ko}{es}Usa la Habilidad Motivación de {fr}Utilisez la compétence de motivation de {pt-br}Habilidade Motivacional de {de}Verwenden ", translateWord[skillTokens[skillGUID].mage], "{en}'s Motivation Skill (+){ru} использует навык Мотивация (+){zh-cn}的“激励”技能 (+){ko}의 동기부여 스킬 사용 (+){es}. (+){fr}. (+){pt-br}. (+){de}'s Motivations Fähigkeit (+)"}))
									UI.setAttribute(skillGUID.."-Motivation"..tostring(turnOrder[a].seatPos), "tooltip", "Draw 2 Cards"..stats.bonus)
								end
								UI.setAttribute(skillGUID.."-Motivation"..tostring(turnOrder[a].seatPos).."Image", "color", positionToColor(a))
								count=count+1
							end
						end
					end

					--Master of Chaos
					if getObjectFromGUID("1ff34f")~=nil and getObjectFromGUID("1ff34f").getPosition()[3]<-25 and math.floor(((getObjectFromGUID("1ff34f").getPosition()[1]+107.3)/40)+0.5)==turnOrder[a].seatPos and (a~=gStates.turnNumber or (a==gStates.turnNumber and #playerAreaCards<1)) and turnOrder[a].masterOfChaos=="available" and turnOrder[a].mage~=gStates.positionMageKnight[5] then
						UI.setAttribute("MasterOfChaos"..tostring(turnOrder[a].seatPos).."Text", "text", "{en}Increment 'Master of Chaos' Skill{ru}Передвинуть навык «Мастер магии Хаоса»{zh-cn}增加'混乱大师'技能(格朗的技能){ko} '혼돈의 달인' 스킬 한 칸 이동{es}Incrementa la Habilidad 'Maestro del Caos'{fr}Augmenter la Compétence 'Maître du Chaos'{pt-br}Incrementar a Habilidade 'Mestre do Caos'{de}Erhöht die Fertigkeit 'Meister des Chaos'")
						UI.setAttribute("MasterOfChaos"..tostring(turnOrder[a].seatPos), "active", "true")
						UI.setAttribute("MasterOfChaos"..tostring(turnOrder[a].seatPos).."Image", "color", positionToColor(a))
						count=count+1
					end
				end
			end
			if count>0 then
				UI.setAttribute("OutOfTurnActions", "active", "true")
				UI.setAttribute("OutOfTurnActions", "height", 35+(count*30))
				UI.setAttribute("OutOfTurnActionsSub", "height", 5+(count*30))
				UI.setAttribute("OutOfTurnActions", "offsetXY", "0 "..tostring(55+(count*30)))
			end

			--change End turn button to say End Round on the last player turn
			gameOver=false
			UI.setAttribute("EndTurnButton", "interactable", "True")
			UI.setAttribute("EndTurnButton", "tooltip", "At least one card must be played or discarded to 'End Your Turn'.")
			UI.setAttribute("EndTurnButtonImage", "image", "Sliced Button/Button New Active")
			UI.setAttribute("EndTurnButtonText", "text", "{en}End Turn{ru}Конец хода{zh-cn}结束回合{ko}차례 종료{es}Fin de Turno{fr}Fin de Tour{pt-br}Fim de Turno{de}Zug Beenden")
			UI.setAttribute("EndTurnButtonAltText", "text", "{en}End Turn{ru}Конец хода{zh-cn}结束回合{ko}차례 종료{es}Fin de Turno{fr}Fin de Tour{pt-br}Fim de Turno{de}Zug Beenden")
			UI.setAttribute("EndTurnButtonAlt", "interactable", "True")
			UI.setAttribute("EndTurnButtonAltImage", "image", "Sliced Button/Button New Active")
			UI.setAttribute("ExtraTurnTacticButton", "interactable", "True")
			UI.setAttribute("ExtraTurnTacticButtonImage", "image", "Sliced Button/Button New Active")
			--UI.setAttribute("PreEndTurnImage", "image", "Sliced Button/Button New Active")
			UI.setAttribute("PreEndTurnText", "text", "{en}Rewards Claimed{ru}Награды получены{zh-cn}继  续{ko}보상 처리 완료{es}Recompensas Reclamadas{fr}Récompenses réclamées{pt-br}Recompensas Coletadas{de}Belohnungen Beansprucht")
			--UI.setAttribute("PreEndTurn", "interactable", "True")
			if nextPlayerEndCalled==true then
				UI.setAttribute("EndTurnButtonText", "text", "{en}End Turn and Round{ru}Конец хода и Раунда{zh-cn}结束回合及本轮次{ko}차례 및 라운드 종료{es}Fin de Turno y Ronda{fr}Fin du Tour et du Round{pt-br}Fim de Turno e Rodada{de}Zug und Runde Beenden")
				UI.setAttribute("EndTurnButtonAltText", "text", "{en}End Turn and Round{ru}Конец хода и Раунда{zh-cn}结束回合及本轮次{ko}차례 및 라운드 종료{es}Fin de Turno y Ronda{fr}Fin du Tour et du Round{pt-br}Fim de Turno e Rodada{de}Zug und Runde Beenden")
				UI.setAttribute("DummyButtonText", "text", "{en}End Turn and Round{ru}Конец хода и Раунда{zh-cn}结束回合及本轮次{ko}차례 및 라운드 종료{es}Fin de Turno y Ronda{fr}Fin du Tour et du Round{pt-br}Fim de Turno e Rodada{de}Zug und Runde Beenden")
				UI.setAttribute("EndTurnButton", "tooltip", "")
				if gStates.currentRound>=gStates.rounds then
					UI.setAttribute("PreEndTurnImage", "image", "Sliced Button/Button New Deactive")
					UI.setAttribute("PreEndTurnText", "text", "{en}Game Over{ru}Игра окончена{zh-cn}游戏结束{ko}게임 종료{es}Fin de Partida{fr}Jeu Terminé{pt-br}Fim de Jogo{de}Game over")
					gameOver=true
					UI.setAttribute("PreEndTurn", "interactable", "False")
					UI.setAttribute("DummyButtonText", "Text", "{en}Game Over{ru}Игра окончена{zh-cn}游戏结束{ko}게임 종료{es}Fin de Partida{fr}Jeu Terminé{pt-br}Fim de Jogo{de}Game over")
					UI.setAttribute("DummyButton", "interactable", "False")
					UI.setAttribute("DummyButtonImage", "image", "Sliced Button/Button New Deactive")
				end
			end
			if (gStates.endGameAchieved=="true" and turnOrder[gStates.turnNumber].gameEnder==true) or
				(gStates.endGameAchieved=="started" and turnOrder[nextPlayer].mage=="Volkare" and turnOrder[nextPlayer].gameEnder==true and #turnOrder<=2) then
				UI.setAttribute("PreEndTurnImage", "image", "Sliced Button/Button New Deactive")
				UI.setAttribute("PreEndTurnText", "text", "{en}Game Over{ru}Игра окончена{zh-cn}游戏结束{ko}게임 종료{es}Fin de Partida{fr}Jeu Terminé{pt-br}Fim de Jogo{de}Game over")
				gameOver=true
				UI.setAttribute("PreEndTurn", "interactable", "False")
			end
			if turnOrder[nextPlayer].mage~=gStates.positionMageKnight[5] and getObjectFromGUID(turnOrder[nextPlayer].turnOrderTokenGUID).is_face_down==true then
				UI.setAttribute("EndTurnButtonText", "text", "{en}Next Assaulter{ru}Следующий штурмующий{zh-cn}下一个袭击者{ko}다음 강습자{es}Siguiente Asaltante{fr}Prochain Agresseur{pt-br}Próximo Invasor{de}Nächster Spieler")
				UI.setAttribute("EndTurnButtonAltText", "text", "{en}Next Assaulter{ru}Следующий штурмующий{zh-cn}下一个袭击者{ko}다음 강습자{es}Siguiente Asaltante{fr}Prochain Agresseur{pt-br}Próximo Invasor{de}Nächster Spieler")
			end

			--If dummy turn activate his menu else setup the players menu
			local fameForUp=0
			UI.setAttribute("DummyButton", "onClick", "dummyTurn")
			UI.setAttribute("DummyButtonText", "Text", "{en}Process Dummy{ru}Ход виртуального игрока{zh-cn}虚拟玩家行动{ko}가상 플레이어 진행{es}Procesar Jugador Virtual{fr}Processus fantôme{pt-br}Processar Jog.Fictício{de}Dummy aktivieren")
			UI.setAttribute("DummyButton", "interactable", "True")
			UI.setAttribute("DummyButtonImage", "image", "Sliced Button/Button New Active")
			UI.setAttribute("DummyTurn", "active", "false")
			UI.setAttribute("ExtraTurnTactic", "active", "false")
			if turnOrder[gStates.turnNumber].mage==gStates.positionMageKnight[5] then
				UI.setAttribute("DummyTurn", "active", "true")
				if gStates.positionMageKnight[5]~="Volkare" then
					UI.setAttribute("DummyNotes", "Text", "{en}Dummy will draw three cards.\nHe then draws cards up to the amount of Crystals that match the third card.{ru}Виртуальный игрок вытащит три карты.\nЗатем он вытащит дополнительно столько карт, сколько он имеет Кристаллов цвета последней перевернутой карты.{zh-cn}虚拟玩家将抽三张牌。\n然后继续抽牌，数量等于他角色面板上同色魔晶的数量。{ko}가상 플레이어의 더미에서\n카드 세 장을 뒤집습니다.\n가상 플레이어의 저장 칸에서, 마지막으로 뒤집힌 카드 색상과 동일한 수정의 개수 만큼 더 뒤집습니다.{es}El Jugador Virtual robará tres cartas\nDespués robará una carta más por cada cristal del color de la última carta robada.{fr}Le fantôme piochera trois cartes.\nIl pioche ensuite des cartes jusqu'à concurrence du nombre de cristaux correspondant à la troisième carte.{pt-br}Jog. Fictício comprará 3 cartas.\nEle então compra cartas equivalentes ao número de cristais que possui da cor da terceira carta.{de}Der Dummy zieht drei Karten.\nEr zieht dann Karten bis zu der Menge an Kristallen, die zur dritten Karte passen.")
				end
				if gStates.positionMageKnight[5]=="Volkare" and gStates.volkareState=="Start" then
					UI.setAttribute("DummyButtonText", "Text", "{en}Process Volkare{ru}Ход Волкара{zh-cn}沃里卡的回合{ko}볼케어 진행{es}Procesar Volkare{fr}Processus Volkare{pt-br}Processar Volkare{de}Volkare Aktivieren")
					UI.setAttribute("DummyNotes", "Text", "{en}Volkare is close to fully programmed.<size=6>\n\n</size>If you feel he has moved incorrectly, unlock and move him where he should have gone.{ru}Волкар почти полностью заскриптован.<size=6>\n\n</size>Если вы считаете, что он двигается неправильно, разблокируйте его и переместите туда, куда он должен был пойти.{zh-cn}沃里卡按脚本移动\n如果你觉得他走错了，解除并移动他到该去的地方。{ko}볼케어의 스크립트는 거의 문제을 일으키지 않으나,<size=6>\n\n</size>만약 잘못된다면 볼케어의 고정을 풀고 직접 원하는 곳에 놓으세요.{es}Volkare está cerca de estar completamente programado.\nSi crees que se ha movido incorrectamente, desbloquealo y muévelo a donde debería haberse movido.{fr}Volkare est presque entièrement programmé.<size=6>\n\n</size>Si vous pensez qu'il a mal bougé, déverrouillez-le et déplacez-le là où il aurait dû aller.{pt-br}Volkare está perto de ser completamente programado.<size=6>\n\n</size>Se você sentir que ele está morrendo de forma incorreta, desbloqueie-o e o mova para aonde ele deveria ter ido.{de}Volkare ist so gut wie fertig programmiert.<size=6>\n\n</size>Wenn Sie das Gefühl haben, dass er sich falsch bewegt hat, entsperren Sie ihn und bewegen Sie ihn dorthin, wo er hingehört.")
				end
				if gStates.positionMageKnight[5]=="Volkare" and gStates.volkareState~="Start" then
					UI.setAttribute("DummyNotes", "Text", gStates.blurb)
					UI.setAttribute("DummyButtonText", "Text", "{en}Volkare Processed{ru}Волкар сходил{zh-cn}沃里卡动完了{ko}진행 완료{es}Volkare Procesado{fr}Volkare Traité{pt-br}Volkare Processado{de}Volkare Verarbeitet")
				end
				if gStates.tacticRemove==true or gStates.tacticShown==true then
					if gStates.tacticRemove==true then
						UI.setAttribute("DummyButton", "interactable", "False")
						UI.setAttribute("DummyButtonImage", "image", "Sliced Button/Button New Deactive")
					end
					UI.setAttribute("DummyNotes", "Text", "{en}Click the button in the Center to claim a random tactic.{ru}Нажмите кнопку в центре, чтобы выбрать случайную Тактику.{zh-cn}点击中间的按钮，可以使用随机战术。{ko}중앙에 있는 버튼을 클릭하여 무작위 전략 카드를 고르세요.{es}Pulsar el Botón del Centro para Robar una Táctica al Azar.{fr}Cliquez sur le bouton dans le Centre pour réclamer une tactique aléatoire.{pt-br}Clique no botão no centro para pegar uma tática aleatória.{de}Klicken Sie auf die Schaltfläche in der Mitte, um eine zufällige Taktik zu fordern.")
				end
				if (gStates.endRoundCalled==true and gStates.currentRound>=gStates.rounds) or gStates.volkareWon==true then
					UI.setAttribute("DummyButtonText", "Text", "{en}Game Over{ru}Игра окончена{zh-cn}游戏结束{ko}게임 종료{es}Fin de Partida{fr}Jeu Terminé{pt-br}Fim de Jogo{de}Game over")
					UI.setAttribute("PreEndTurnText", "text", "{en}Game Over{ru}Игра окончена{zh-cn}游戏结束{ko}게임 종료{es}Fin de Partida{fr}Jeu Terminé{pt-br}Fim de Jogo{de}Game over")
					gameOver=true
					UI.setAttribute("DummyButton", "interactable", "False")
					UI.setAttribute("DummyButtonImage", "image", "Sliced Button/Button New Deactive")
					if gStates.positionMageKnight[5]=="Volkare" and gStates.volkareState=="Start" then
						UI.setAttribute("DummyNotes", "Text", "{en}Final round of turns is complete. For most players this would have meant just flipping your Turn Order token back upright.{ru}Завершен последний круг ходов. Для большинства игроков это означало бы просто перевернуть жетон очередности хода обратно в вертикальное положение.{zh-cn}最后一轮的最终回合完成。对于大多数玩家来说，你只需将你的顺序标记翻转回来即可。{ko}차례의 마지막 순서가 끝났습니다. 대부분의 플레이어들은 라운드 순서 토큰을 앞면으로 뒤집었을겁니다.{es}La Última Ronda de Turnos se ha completado. Para la mayoría de jugadores esto significa simplemente poner boca arriba el marcador de turno.{fr}Le dernier tour est terminé. Pour la plupart des joueurs, cela aurait signifié simplement retourner votre jeton Ordre du tour à la verticale.{pt-br}Rodada Final de turnos está completa. Para a maioria dos jogadores isso significa apenas virar sua ficha de ordem de turno de volta para cima.{de}Die letzte Zugrundelegung ist abgeschlossen. Für die meisten Spieler würde dies bedeuten, dass sie ihr Zugreihenfolgeplättchen einfach wieder umdrehen.")
						if (gStates.gameScenario=="Volkare's Return" or gStates.gameScenario=="Volkare's Return Blitz") and gStates.volkareArmyDefeated<gStates.playerCount then
							UI.setAttribute("DummyNotes", "Text", "{en}Volkare has conquered the city.<size=6>\n\n</size>You have Lost.{ru}Волкар захватил город.<size=6>\n\n</size>Вы проиграли.{zh-cn}沃里卡已经占领了这个城市。<size=6>\n\n</size>你输了。{ko}볼케어가 도시를 정복했습니다.<size=6>\n\n</size>게임 패배{es}Volkare ha conquistado la ciudad.<size=6>\n\n</size>Has perdido.{fr}Volkare a conquis la ville.<size=6>\n\n</size>Vous avez perdu.{pt-br}Volkare conquistou a Cidade<size=6>\n\n</size>Você Perdeu.{de}Volkare hat die Stadt erobert.<size=6>\n\n</size>Du hast verloren.")
						end
					end
				end
				if scenarioList[gStates.scenarioRef][gStates.playersRef].dummyTacticSelection=="F" then turnOrder[gStates.turnNumber].fame=-1 else turnOrder[gStates.turnNumber].fame=999 end
			else--normal players
				UI.setAttribute("VolkareAttacked", "active", "false")
				--Work out the Reputation for the current Mage Knight
				for repValue, repDetail in pairs(reputationTable) do
					for _, obj in pairs(getObjectFromGUID(repDetail.repZone).getObjects()) do
						if obj.guid==turnOrder[gStates.turnNumber].reputationGUID then turnOrder[gStates.turnNumber].reputation=repValue break break end
					end
				end
				recourceTrackerReset("update")

				--work out how much more fame is needed until a level up is required
				local fameZValue=getObjectFromGUID(turnOrder[gStates.turnNumber].fameGUID).getPosition()[3]
				local fameXValue=getObjectFromGUID(turnOrder[gStates.turnNumber].fameGUID).getPosition()[1]
				local fameVerticle=math.ceil((topOfFameBoard-fameZValue)/heightOfFameBoard*gStates.rowsOnBoard)
				if turnOrder[gStates.turnNumber].level<gStates.rowsOnBoard then
					local fameToLevel=math.floor(math.sqrt(turnOrder[gStates.turnNumber].fame+1))
					if fameToLevel>gStates.rowsOnBoard then fameToLevel=gStates.rowsOnBoard end
					if fameVerticle<gStates.rowsOnBoard then fameForUp=((fameToLevel+1)*(fameToLevel+1))-1-turnOrder[gStates.turnNumber].fame end
					--see if the current fame value would cause a level up
					turnOrder[gStates.turnNumber].levelUp=0
					if fameToLevel>turnOrder[gStates.turnNumber].level then
						if fameToLevel==2 or fameToLevel==4 or fameToLevel==6 or fameToLevel==8 or fameToLevel==10 or fameToLevel==12 or fameToLevel-turnOrder[gStates.turnNumber].level>1 then gStates.levelingUp=true end
						turnOrder[gStates.turnNumber].levelUp=fameToLevel-turnOrder[gStates.turnNumber].level
						if gStates.preEndTurn==true and levelUpcalled==false then levelUpcalled=true levelUp(gStates.turnNumber) end
					end
				end

				--Read all objects found in play area. Used to decide on off states of "End.." buttons, plus fame and rep gains
				local timeBending=false
				local avatarLocation=turnOrder[gStates.turnNumber].avatarLocation
				for a, b in pairs(gStates.gainList) do b.exists=false end
				if gStates.preEndTurn==false then
					local hiddenValleyKeep=false
					for _, obj in pairs(getObjectFromGUID(playerPlayAreas[turnOrder[gStates.turnNumber].seatPos]).getObjects()) do
						--Read Monster tokens in current play area and update fame and reputation gain values.
						if obj.guid=="2eb8e2" then timeBending=true end
						if monsterPugs[obj.guid]~=nil and gStates.summonStates[obj.guid]~="summoned" then
							local doMath=false
							local cityRepLoss=false
							for cityguid, monsters in pairs(gStates.cityMonsterQty) do
								if monsters[obj.guid]=="alive" then cityRepLoss=true break end
							end
							--If no entry found create a new entry for this token
							if gStates.gainList[obj.guid]==nil then
								--record token orientation and do the math if face up.
								gStates.gainList[obj.guid]={exists=true}
								if obj.is_face_down==false then
									gStates.gainList[obj.guid].tokenDirection=1
									doMath=true
								else
									gStates.gainList[obj.guid].tokenDirection=-1
								end
								--store leader overkil value
								if obj.guid==darkCrusader.token or obj.guid==elementalist.token then gStates.gainList[obj.guid].overkill=0 end
								--just existing is enough orientation has no effect
								--city rep loss
								for cityguid, monsters in pairs(gStates.cityMonsterQty) do
									if cityguid~=darkCrusader.terrainHex and cityguid~=elementalist.terrainHex and cityguid~=volkare.model and cityguid~=volkare.terrainHex and monsters[obj.guid]=="alive" and gStates.gainList[cityguid]==nil then
									 	turnOrder[gStates.turnNumber].repGain=turnOrder[gStates.turnNumber].repGain-1
										gStates.gainList[cityguid]={exists=true}
										if monsters.extra.megapolisPair~=nil and monsters.extra.megapolisPair~=cityguid then gStates.gainList[monsters.extra.megapolisPair]={exists=true} end
										break
									end
								end
								--Mage Tower and keep rep loss
								local count=0
								for c, d in pairs(gStates.gainList) do
									if c==gStates.hiddenValleyKeep[1] or c==gStates.hiddenValleyKeep[2] then count=count+1 end
								end
								if count==2 then hiddenValleyKeep=true end
								if cityRepLoss==false and
								   ((monsterPugs[obj.guid].pugType=="gray" and avatarLocation=="keep") or
	   							   (monsterPugs[obj.guid].pugType=="purple" and avatarLocation=="mage tower") or
								   ((obj.guid==gStates.hiddenValleyKeep[1] or obj.guid==gStates.hiddenValleyKeep[2]) and hiddenValleyKeep==false)) then
									turnOrder[gStates.turnNumber].repGain=turnOrder[gStates.turnNumber].repGain-1
									if obj.guid==gStates.hiddenValleyKeep[1] or obj.guid==gStates.hiddenValleyKeep[2] then hiddenValleyKeep=true end
								end
								--monastery rep loss
								if avatarLocation~=nil then
									if monsterPugs[obj.guid].pugType=="purple" and gStates.monsterPlayLocation[obj.guid]==nil and avatarLocation=="monastery" then
										turnOrder[gStates.turnNumber].repGain=turnOrder[gStates.turnNumber].repGain-3
									end
								end
							end
							--existing token found, but it has been flipped
							if (obj.is_face_down==false and gStates.gainList[obj.guid].tokenDirection==-1)
							or (obj.is_face_down==true and gStates.gainList[obj.guid].tokenDirection==1) then
								gStates.gainList[obj.guid].tokenDirection=gStates.gainList[obj.guid].tokenDirection*-1
								doMath=true
							end
							--mines liberation corect fame and rep
							local minesLibMonster=false
							for terrainguid, monsters in pairs(gStates.mineMonsterQty) do
								if monsters[obj.guid]~=nil and gStates.gameScenario~="The Hidden Valley Blitz" then
									minesLibMonster=true--current monster has come from a mine
									if gStates.gameScenario~="The Realm of the Dead Blitz" then
										for monsterGUID, state in pairs(monsters) do
											if monsterGUID~=obj.guid then--found second mine monster
												if (state=="alive" and gStates.gainList[monsterGUID]~=nil) or state=="dead" then
													local x=1
													if terrainTiles[terrainguid].tileType=="core" then x=2 end--and gStates.gameScenario~="Mines Liberation"
													if gStates.gainList[terrainguid]==nil then
														gStates.gainList[terrainguid]={exists=true}
														gStates.gainList[terrainguid].tokenDirection=-1
														if gStates.gainList[obj.guid].tokenDirection==1 and (state=="dead" or gStates.gainList[monsterGUID].tokenDirection==1) then
															gStates.gainList[terrainguid].tokenDirection=1
															turnOrder[gStates.turnNumber].repGain=turnOrder[gStates.turnNumber].repGain+(x*gStates.gainList[terrainguid].tokenDirection)
														end
													else
														gStates.gainList[terrainguid].exists=true
														if (gStates.gainList[obj.guid].tokenDirection==1 and (state=="dead" or gStates.gainList[monsterGUID].tokenDirection==1) and gStates.gainList[terrainguid].tokenDirection==-1)
														or ((gStates.gainList[obj.guid].tokenDirection==-1 or (state=="alive" and gStates.gainList[monsterGUID].tokenDirection==-1)) and gStates.gainList[terrainguid].tokenDirection==1) then
															gStates.gainList[terrainguid].tokenDirection=gStates.gainList[terrainguid].tokenDirection*-1
															turnOrder[gStates.turnNumber].repGain=turnOrder[gStates.turnNumber].repGain+(x*gStates.gainList[terrainguid].tokenDirection)
														end
													end
													break
												end
											end
										end
									end
									break
								end
							end
							--Check if leader Overkill Changed
							if gStates.gainList[obj.guid].overkill~=nil and gStates.gainList[obj.guid].overkill~=gStates.leaderOverkill and obj.is_face_down==false then doMath=true end
							--if allowed add or subtract fame and reputation
							if doMath==true then
								--All tokens Fame
								if gStates.monsterPlayLocation[obj.guid]==nil and monsterPugs[obj.guid].pugType=="gray" and avatarLocation=="keep" then
									turnOrder[gStates.turnNumber].fameGain=turnOrder[gStates.turnNumber].fameGain+(math.ceil(monsterPugs[obj.guid].fame/2)*gStates.gainList[obj.guid].tokenDirection)
								else
									local multiple=1
									if obj.guid==darkCrusader.token or obj.guid==elementalist.token then
										if gStates.gainList[obj.guid].overkill~=gStates.leaderOverkill then turnOrder[gStates.turnNumber].fameGain=turnOrder[gStates.turnNumber].fameGain-(monsterPugs[obj.guid].fame*gStates.gainList[obj.guid].overkill) end
										multiple=gStates.leaderOverkill
										gStates.gainList[obj.guid].overkill=gStates.leaderOverkill
									end
									if gStates.druidNightsSummon==true then multiple=2 end
									turnOrder[gStates.turnNumber].fameGain=turnOrder[gStates.turnNumber].fameGain+(monsterPugs[obj.guid].fame*multiple*gStates.gainList[obj.guid].tokenDirection)
								end
								if getObjectFromGUID("f469f4")==nil and getObjectFromGUID("33de41")==nil and monsterPugs[obj.guid].reward~=nil and type(monsterPugs[obj.guid].reward)=="number" then
									turnOrder[gStates.turnNumber].fameGain=turnOrder[gStates.turnNumber].fameGain+(monsterPugs[obj.guid].reward*gStates.gainList[obj.guid].tokenDirection)
									if gStates.druidNightsSummon==true then turnOrder[gStates.turnNumber].fameGain=turnOrder[gStates.turnNumber].fameGain+(monsterPugs[obj.guid].reward*gStates.gainList[obj.guid].tokenDirection) end
								end
								--Rampaging Reputation
								if gStates.monsterPlayLocation[obj.guid]~=nil and minesLibMonster==false and cityRepLoss==false and (gStates.ruinMonsters==nil or gStates.ruinMonsters[obj.guid]==nil) and
									obj.guid~=gStates.hiddenValleyKeep[1] and obj.guid~=gStates.hiddenValleyKeep[2] then
									if monsterPugs[obj.guid].pugType=="green" or monsterPugs[obj.guid].pugType=="tan" then turnOrder[gStates.turnNumber].repGain=turnOrder[gStates.turnNumber].repGain+(1*gStates.gainList[obj.guid].tokenDirection) end --Why do I have Tan??
									if monsterPugs[obj.guid].pugType=="red" and gStates.gameScenario~="The Lost Relic Blitz" then turnOrder[gStates.turnNumber].repGain=turnOrder[gStates.turnNumber].repGain+(2*gStates.gainList[obj.guid].tokenDirection) end
								end
								--add hero and thug reputation
								if monsterPugs[obj.guid].reputation~=nil then turnOrder[gStates.turnNumber].repGain=turnOrder[gStates.turnNumber].repGain+(monsterPugs[obj.guid].reputation*gStates.gainList[obj.guid].tokenDirection) end
							end
							gStates.gainList[obj.guid].exists=true
						end
					end
					--if a token has been removed subtract it's values
					hiddenValleyKeep=false
					for a, b in pairs(gStates.gainList) do
						if b.exists==false and monsterPugs[a]~=nil then
							local cityRepLoss=false
							for cityguid, monsters in pairs(gStates.cityMonsterQty) do
								if monsters[a]=="alive" then cityRepLoss=true break end
							end
							if b.tokenDirection==1 then
								--fame
								if gStates.monsterPlayLocation[a]==nil and monsterPugs[a].pugType=="gray" and avatarLocation=="keep" then
									turnOrder[gStates.turnNumber].fameGain=turnOrder[gStates.turnNumber].fameGain-math.ceil(monsterPugs[a].fame/2)
								else
									local multiple=1
									if a==darkCrusader.token or a==elementalist.token then multiple=gStates.leaderOverkill end
									if gStates.druidNightsSummon==true then multiple=2 end
									turnOrder[gStates.turnNumber].fameGain=turnOrder[gStates.turnNumber].fameGain-(monsterPugs[a].fame*multiple)
								end
								if getObjectFromGUID("f469f4")==nil and getObjectFromGUID("33de41")==nil and monsterPugs[a].reward~=nil then
									turnOrder[gStates.turnNumber].fameGain=turnOrder[gStates.turnNumber].fameGain-monsterPugs[a].reward
									if gStates.druidNightsSummon==true then turnOrder[gStates.turnNumber].fameGain=turnOrder[gStates.turnNumber].fameGain-monsterPugs[a].reward end
								end
								--Mine Liberation Reputation gStates.gameScenario=="Mines Liberation"
								local minesLibMonster=false
								for terrainguid, monsters in pairs(gStates.mineMonsterQty) do
									if monsters[a]~=nil then
										minesLibMonster=true--current monster has come from a mine
										if gStates.gainList[terrainguid]~=nil and gStates.gainList[terrainguid].tokenDirection==1 then
											local x=1
											if terrainTiles[terrainguid].tileType=="core" then x=2 end
											turnOrder[gStates.turnNumber].repGain=turnOrder[gStates.turnNumber].repGain-x
											gStates.gainList[terrainguid]=nil
										end
										break
									end
								end
								--Rampaging reputation
								if gStates.monsterPlayLocation[a]~=nil and minesLibMonster==false and cityRepLoss==false and (gStates.ruinMonsters==nil or gStates.ruinMonsters[a]==nil) and
									a~=gStates.hiddenValleyKeep[1] and a~=gStates.hiddenValleyKeep[2] then
									if monsterPugs[a].pugType=="green" or monsterPugs[a].pugType=="tan" then turnOrder[gStates.turnNumber].repGain=turnOrder[gStates.turnNumber].repGain-1 end
									if monsterPugs[a].pugType=="red" and gStates.gameScenario~="The Lost Relic Blitz" then turnOrder[gStates.turnNumber].repGain=turnOrder[gStates.turnNumber].repGain-2 end
								end
								--Hero and thug reputation
								if monsterPugs[a].reputation~=nil then turnOrder[gStates.turnNumber].repGain=turnOrder[gStates.turnNumber].repGain-monsterPugs[a].reputation end
							end
							--City monsters
							for cityguid, monsters in pairs(gStates.cityMonsterQty) do
								if cityguid~=darkCrusader.terrainHex and cityguid~=elementalist.terrainHex and monsters[a]=="alive" and gStates.gainList[cityguid]~=nil then
									local found=false
									for monsterGUID, state in pairs(monsters) do
										if gStates.gainList[monsterGUID]~=nil then
											if gStates.gainList[monsterGUID].exists==true then found=true end
										end
									end
									if found==false then
										turnOrder[gStates.turnNumber].repGain=turnOrder[gStates.turnNumber].repGain+1
										gStates.gainList[cityguid]=nil
										if monsters.extra.megapolisPair~=nil and monsters.extra.megapolisPair~=cityguid then gStates.gainList[monsters.extra.megapolisPair]=nil end
									end
									break
								end
							end
							--Mage tower and keep
							local count=0
							for c, d in pairs(gStates.gainList) do
								if c==gStates.hiddenValleyKeep[1] or c==gStates.hiddenValleyKeep[2] then count=count+1 end
							end
							if count==1 then hiddenValleyKeep=true end
							if cityRepLoss==false and
							   ((monsterPugs[a].pugType=="gray" and avatarLocation=="keep") or
	   						   (monsterPugs[a].pugType=="purple" and avatarLocation=="mage tower") or
							   ((a==gStates.hiddenValleyKeep[1] or a==gStates.hiddenValleyKeep[2]) and hiddenValleyKeep==true)) then
								turnOrder[gStates.turnNumber].repGain=turnOrder[gStates.turnNumber].repGain+1
							end
							--monastery
							if avatarLocation~=nil and monsterPugs[a]~=nil then
								if monsterPugs[a].pugType=="purple" and gStates.monsterPlayLocation[a]==nil and avatarLocation=="monastery" then
									turnOrder[gStates.turnNumber].repGain=turnOrder[gStates.turnNumber].repGain+3
								end
							end
							gStates.gainList[a]=nil
						end
					end
					--Cap the gain values if exceeding limits
					if turnOrder[gStates.turnNumber].fameGain<0 then turnOrder[gStates.turnNumber].fameGain=0 end
					if turnOrder[gStates.turnNumber].repGain<(-7-turnOrder[gStates.turnNumber].reputation) then turnOrder[gStates.turnNumber].repGain=(-7-turnOrder[gStates.turnNumber].reputation) end
					if turnOrder[gStates.turnNumber].repGain>(7-turnOrder[gStates.turnNumber].reputation) then turnOrder[gStates.turnNumber].repGain=(7-turnOrder[gStates.turnNumber].reputation) end
				end

				--Change End turn button text if level up expected
				if (fameForUp<=turnOrder[gStates.turnNumber].fameGain or turnOrder[gStates.turnNumber].levelUp>0) and turnOrder[gStates.turnNumber].fame<gStates.scoreIfLooped and fameVerticle<gStates.rowsOnBoard then
					UI.setAttribute("EndTurnButtonText", "text", "{en}End Turn & Level Up{ru}Конец хода и Повышение уровня{zh-cn}结束回合并升级{ko}차례 종료 & 레벨 업{es}Fin de turno y Subir Nivel{fr}Fin du Tour et Level Up{pt-br}Finalizar Turno e Subir Nível{de}Zug beenden und aufleveln")
					UI.setAttribute("EndTurnButtonAltText", "text", "{en}End Turn & Level Up{ru}Конец хода и Повышение уровня{zh-cn}结束回合并升级{ko}차례 종료 & 레벨 업{es}Fin de turno y Subir Nivel{fr}Fin du Tour et Level Up{pt-br}Finalizar Turno e Subir Nível{de}Zug beenden und aufleveln")
					local expectedFame=turnOrder[gStates.turnNumber].fame+turnOrder[gStates.turnNumber].fameGain
					local excessLevels=math.floor(math.sqrt(expectedFame+1))-turnOrder[gStates.turnNumber].level
					expectedFame=expectedFame+(1*excessLevels*gStates.blitz)
					excessLevels=math.floor(math.sqrt(expectedFame+1))-turnOrder[gStates.turnNumber].level
					if excessLevels>1 then 
						UI.setAttribute("EndTurnButtonText", "text", joinLang({"{en}End Turn & {ru}Конец хода и {zh-cn}结束回合 & {ko}엔드 턴 & {es}Fin de Turno & {fr}Fin du tour & {pt-br}Fim do turno & {de}Ende der Runde & ", excessLevels, "{en} Level Ups{ru} Повышения уровня{zh-cn} 水平提升{ko} 레벨 업{es} Subidas de nivel{fr} Montée en niveau{pt-br} Subidas de nível{de} Level Ups"}))
						UI.setAttribute("EndTurnButtonAltText", "text", joinLang({"{en}End Turn & {ru}Конец хода и {zh-cn}结束回合 & {ko}엔드 턴 & {es}Fin de Turno & {fr}Fin du tour & {pt-br}Fim do turno & {de}Ende der Runde & ", excessLevels, "{en} Level Ups{ru} Повышения уровня{zh-cn} 水平提升{ko} 레벨 업{es} Subidas de nivel{fr} Montée en niveau{pt-br} Subidas de nível{de} Level Ups"}))						
					end
					if turnOrder[nextPlayer].mage~=gStates.positionMageKnight[5] and getObjectFromGUID(turnOrder[nextPlayer].turnOrderTokenGUID).is_face_down==true then
						UI.setAttribute("EndTurnButtonText", "text", "{en}Next Assaulter & Level Up{ru}Следующий штурмующий и Повышение уровня{zh-cn}下一个袭击者并升级{ko}다음 강습자 & 레벨 업{es}Siguiente Asaltante & Subir Nivel{fr}Agresseur Suivant & Level Up{pt-br}Próximo Invasor e Subir Nível{de}Nächster Spieler & Aufleveln")
						UI.setAttribute("EndTurnButtonAltText", "text", "{en}Next Assaulter & Level Up{ru}Следующий штурмующий и Повышение уровня{zh-cn}下一个袭击者并升级{ko}다음 강습자 & 레벨 업{es}Siguiente Asaltante & Subir Nivel{fr}Agresseur Suivant & Level Up{pt-br}Próximo Invasor e Subir Nível{de}Nächster Spieler & Aufleveln")
						if excessLevels>1 then 
							UI.setAttribute("EndTurnButtonText", "text", joinLang({"{en}Next Assaulter & {ru}Следующий штурмующий и {zh-cn}下一个攻击者 & {ko}다음 어썰터 & {es}Siguiente Asaltante & Subir Nivel{fr}Assaillant suivant & {pt-br}Próximo Assaltante & {de}Nächster Angreifer & ", excessLevels, "{en} Level Ups{ru} Повышения уровня{zh-cn} 水平提升{ko} 레벨 업{es} Subidas de nivel{fr} Montée en niveau{pt-br} Subidas de nível{de} Level Ups"}))
							UI.setAttribute("EndTurnButtonAltText", "text", joinLang({"{en}Next Assaulter & {ru}Следующий штурмующий и {zh-cn}下一个攻击者 & {ko}다음 어썰터 & {es}Siguiente Asaltante & Subir Nivel{fr}Assaillant suivant & {pt-br}Próximo Assaltante & {de}Nächster Angreifer & ", excessLevels, "{en} Level Ups{ru} Повышения уровня{zh-cn} 水平提升{ko} 레벨 업{es} Subidas de nivel{fr} Montée en niveau{pt-br} Subidas de nível{de} Level Ups"}))
						end
					end
					if nextPlayerEndCalled==true then
						UI.setAttribute("EndTurnButtonText", "text", "End Turn, Rnd & Lev Up")
						UI.setAttribute("EndTurnButtonAltText", "text", "End Turn, Rnd & Lev Up")
						if excessLevels>1 then 
							UI.setAttribute("EndTurnButtonText", "text", joinLang({"{en}End Turn, Rnd & {ru}Конец хода, Раунда и {zh-cn}结束回合，回合 & {ko}엔드 턴, Rnd & {es}Fin de turno, ronda y {fr}Fin du tour, Rnd & {pt-br}Fim de turno, ronda & {de}Ende der Runde, Rnd & ", excessLevels, "{en} Level Ups{ru} Повышения уровня{zh-cn} 水平提升{ko} 레벨 업{es} Subidas de nivel{fr} Montée en niveau{pt-br} Subidas de nível{de} Level Ups"}))
							UI.setAttribute("EndTurnButtonAltText", "text", joinLang({"{en}End Turn, Rnd & {ru}Конец хода, Раунда и {zh-cn}结束回合，回合 & {ko}엔드 턴, Rnd & {es}Fin de turno, ronda y {fr}Fin du tour, Rnd & {pt-br}Fim de turno, ronda & {de}Ende der Runde, Rnd & ", excessLevels, "{en} Level Ups{ru} Повышения уровня{zh-cn} 水平提升{ko} 레벨 업{es} Subidas de nivel{fr} Montée en niveau{pt-br} Subidas de nível{de} Level Ups"}))
						end
					end
				end

				--Change Reward text to be player location sensitive
				local count=1
				local rewardText="{en}Have you:-\n{ru}Проверьте, что вы:-\n{zh-cn}你是否已经：\n{ko}차례 종료 과정 진행:-\n{es}Has:-\n{fr}Avez-vous:-\n{pt-br}Você já:-\n{de}Haben sie:-\n"
				local linefeed=false
				if gStates.gameScenario=="Mines Liberation" and gStates.endRoundCalled==true and gStates.turnForfeited==false then
					rewardText=joinLang({rewardText, count, "{en}. Gained a Crystal from all Liberated Mines.{ru}. Получили кристалл из всех Освобожденных шахт.{zh-cn}从所有解放的矿山中获得一块魔晶{ko}. 정복한 모든 광산에서 수정 획득{es}. Obtenido un Cristal de todas las Minas Liberadas.{fr}. Vous avez obtenu un cristal de toutes les mines libérées.{pt-br}. Ganhou um Cristal de Todas as Minas Liberadas.{de}. Einen Kristall aus allen befreiten Minen gewonnen."})
					count=count+1 linefeed=true
				end
				if avatarLocation~=nil then
					--see if a matching shield is near the avatar
					function nearOwnShield()
						local nearOwnShield="false"
						local avPos={}
						for _, details in pairs(mageKnights) do
							if turnOrder[gStates.turnNumber].mage==details.mage then
								if getObjectFromGUID(details.model)~=nil then avPos=getObjectFromGUID(details.model).getPosition() end
								if getObjectFromGUID(details.token)~=nil then avPos=getObjectFromGUID(details.token).getPosition() end
								if getObjectFromGUID(details.standee)~=nil then avPos=getObjectFromGUID(details.standee).getPosition() end
								break
							end
						end
						if (gStates.gameScenario=="Volkare's Return" or gStates.gameScenario=="Volkare's Return Blitz" or gStates.gameScenario=="Volkare's Quest" or gStates.gameScenario=="The War of Four") and
							getObjectFromGUID(volkare.model)~=nil and math.sqrt(((getObjectFromGUID(volkare.model).getPosition()[1]-avPos[1])^2)+((getObjectFromGUID(volkare.model).getPosition()[3]-avPos[3])^2))<1 then
							return volkare.model
						end
						if avatarLocation:sub(1, 4)=="city" or avatarLocation=="Volkare's Camp" or avatarLocation=="necropolis" or avatarLocation=="hidden valley" then
							cityBeatCheck()
							--check if avatar dropped on city card, then use the city model as the avatar location
							for zone, citySearch in pairs(cityScriptZones) do
								for obj, detail in pairs(getObjectFromGUID(zone).getObjects()) do
									for _, avatar in pairs(mageKnights) do
										if detail.guid==avatar.model or detail.guid==avatar.standee or detail.guid==avatar.token then
											if zone==volkare.discZone and (gStates.gameScenario=="Volkare's Return" or gStates.gameScenario=="Volkare's Return Blitz" or gStates.gameScenario=="Volkare's Quest" or gStates.gameScenario=="The War of Four") then
												return volkare.model
											else
												return citySearch.cityGUID
											end
										end
									end
								end
							end
						end
						for _, shieldCheck in pairs(getObjectFromGUID(mapArea).getObjects()) do
							if (shieldCheck.getName()=="Shield" or shieldCheck.getName()=="Hidden Valley" or shieldCheck.getName()=="Necropolis" or shieldCheck.getName()=="Volkare's Camp" or shieldCheck.getName()=="Volkare" or
								shieldCheck.getGMNotes()=="White City" or shieldCheck.getGMNotes()=="Red City" or shieldCheck.getGMNotes()=="Green City" or shieldCheck.getGMNotes()=="Blue City") and
								math.sqrt(((shieldCheck.getPosition()[1]-avPos[1])^2)+((shieldCheck.getPosition()[3]-avPos[3])^2))<1 then
								nearOwnShield=shieldCheck.guid break
							end
						end
						return nearOwnShield
					end

					--Victory Shield
					if (avatarLocation=="glade" and gStates.gameScenario=="Druid Nights") then
						if nearOwnShield()=="false" and gStates.turnForfeited==false then
							rewardText=joinLang({rewardText, count, "{en}. Placed a Victory Shield{ru}. Разместили Жетон щита{zh-cn}放置胜利盾牌{ko}. 방패 토큰 놓기{es}. Colocado un Escudo de Conquista.{fr}. Placé un Bouclier de Victoire{pt-br}. Colocou um Escudo de Vitória.{de}. Einen Siegesschild platziert"})
							count=count+1 linefeed=true
						end
					end
					--Victory Shield
					if avatarLocation=="graveyard" and gStates.gameScenario=="The Realm of the Dead Blitz" and nearOwnShield()=="false" and gStates.turnForfeited==false then
						rewardText=joinLang({rewardText, count, "{en}. Paid to Seal the Graveyard{ru}. Заплатили за запечатывание Кладбища{zh-cn}付费封印墓地{ko}. 묘지 봉인 마나 지불(선택){es}. Pagado para Sellar el Cementerio{fr}. Payé pour Sceller le Cimetière{pt-br}Pago para Selar o Cemitério{de}. Für die Versiegelung des Friedhofs bezahlt."})
						count=count+1 linefeed=true
					end
					if linefeed==true then rewardText=joinLang({rewardText, "\n"}) linefeed=false end
					if gStates.turnForfeited==false and
						(((avatarLocation=="keep" or avatarLocation=="mage tower") and nearOwnShield()=="false") or
						((avatarLocation:sub(1, 4)=="city" or avatarLocation=="Volkare's Camp") and gStates.friendlyCity[nearOwnShield()]~=true and ((gStates.gameScenario~="The Lost Relic Blitz" and gStates.defeatedCities[nearOwnShield()]~=true) or (gStates.gameScenario=="The Lost Relic Blitz" and nearOwnShield()=="false"))) or
						((avatarLocation=="necropolis" or avatarLocation=="hidden valley") and (gStates.defeatedFactionTest==nil or gStates.defeatedFactionTest[nearOwnShield()]~="Beat")) or
						(nearOwnShield()==volkare.model)) then
						rewardText=joinLang({rewardText, count, "{en}. Retreated to a Safe space{ru}. Отступили в Безопасное место{zh-cn}被强制撤离到一个安全的位置{ko}. 안전한 칸으로 후퇴{es}. Acabado en un Espacio Seguro{fr}. Retraité dans un espace sûr{pt-br}. Recuou para um espaço seguro{de}. Sich in einen sicheren Raum zurückgezogen"})
						count=count+1 linefeed=true
					end
					if linefeed==true then rewardText=joinLang({rewardText, "\n"}) linefeed=false end
					if gStates.turnForfeited==false and gladeFreeCheck()==true and (avatarLocation=="glade" or avatarLocation=="hidden valley" or
					(gStates.gameScenario=="The War of Four" and (avatarLocation=="necropolis" or avatarLocation=="graveyard"))) then
						rewardText=joinLang({rewardText, count, "{en}. Removed One Wound{ru}. Вернули в ступку одну рану{zh-cn}移除一点创伤{ko}. 부상 하나 제거{es}. Eliminado una Herida{fr}. Suppression d'une blessure{pt-br}. Removeu Um Ferimento{de}. Eine Wunde Wurde Entfernt"})
						count=count+1 linefeed=true
					end
					if linefeed==true then rewardText=joinLang({rewardText, "\n"}) linefeed=false end
					if gStates.turnForfeited==false and avatarLocation:sub(1,4)=="mine" and
						(gStates.gameScenario~="Mines Liberation" or (gStates.gameScenario=="Mines Liberation" and nearOwnShield()~="false")) then
						rewardText=joinLang({rewardText, count, "{en}. Gained a Crystal from the Mine{ru}. Получили Кристалл из Шахты{zh-cn}从矿山里得到一块魔晶{ko}. 광산의 수정 하나 획득{es}. Obtenido un Cristal de la Mina{fr}. Vous avez obtenu un cristal de la mine{pt-br}. Ganhou um Cristal da Mina{de}. Einen Kristall aus der Mine gewonnen"})
						count=count+1 linefeed=true
					end
					if linefeed==true then rewardText=joinLang({rewardText, "\n"}) linefeed=false end
					if gStates.turnForfeited==false and ((gStates.shieldsDropped[nearOwnShield()]~=nil and (avatarLocation=="mage tower" or avatarLocation=="labyrinth"		or avatarLocation=="maze" or avatarLocation=="monastery" or avatarLocation=="monster den" or avatarLocation=="dungeon" or avatarLocation=="spawning grounds" or avatarLocation=="tomb"
					or (avatarLocation=="ruin" and gStates.crytalRuin~=true)
					or ((avatarLocation=="graveyard" or avatarLocation=="glade") and gStates.gameScenario=="Life and Death")))
					or (avatarLocation=="graveyard" and gStates.gameScenario=="The Realm of the Dead Blitz")) then
						rewardText=joinLang({rewardText, count, "{en}. Gained Site Conquest Rewards{ru}. Получили награды за завоевание Места{zh-cn}获得板块征服奖励{ko}. 장소 정복 보상 획득{es}. Obtenido la Recompensa de Conquista{fr}. Récompenses de conquête de site obtenues{pt-br}. Ganhou As Recompensas de Conquista{de}. Gewonnene Eroberungsprämien"})
						count=count+1 linefeed=true
					end
				end
				if linefeed==true then rewardText=joinLang({rewardText, "\n"}) linefeed=false end
				if gStates.levelingUp==true then
					rewardText=joinLang({rewardText, count, "{en}. Gained a New Skill Token{ru}. Получили новый Жетон навыка{zh-cn}获得新的技能{ko}. 새로운 스킬 획득{es}. Obtuvo una ficha de habilidad nueva{fr}. Vous avez obtenu un nouveau jeton de compétence{pt-br}. Ganhou uma Nova Ficha de Habilidade{de}. Neues Skill Token Erhalten"})
					count=count+1 rewardText=joinLang({rewardText, "\n"})
					rewardText=joinLang({rewardText, count, "{en}. Gained a New Advanced Action{ru}. Получили новое Особое действие{zh-cn}获得新的高级行动卡{ko}. 새로운 상급 액션 획득{es}. Obtuvo una nueva acción avanzada{fr}. Vous avez obtenu une nouvelle action avancée{pt-br}. Ganhou uma Nova Ação Avançada{de}. Eine neue fortgeschrittene Aktion erhalten"})
					count=count+1 linefeed=true
				end
				if linefeed==true then rewardText=joinLang({rewardText, "\n"}) linefeed=false end
				if gStates.turnForfeited==true then
					rewardText=joinLang({rewardText, count, "{en}. Forfeit Turn, no site Rewards{ru}. Пропустили ход, и не получаете Награды за Места{zh-cn}放弃回合，无放置奖励{ko}. 차례 포기, 장소 혜택 사용불가{es}. Saltar Turno, sin Recompensas de Lugar{fr}. Forfait Turn, pas de récompenses de site{pt-br}. Desistir do Turno. Sem Recompensas de Local{de}. Forfeit Turn, keine Site Rewards"})
					count=count+1 linefeed=true
				end
				if linefeed==true then rewardText=joinLang({rewardText, "\n"}) linefeed=false end
				if gameOver==false then
					rewardText=joinLang({rewardText, count, "{en}. Confirmed your hand size{ru}. Проверили предел карт в вашей руке{zh-cn}更新你的手牌上限{ko}. 카드 보유 제한 체크{es}. Confirmado tu tamaño de Mano{fr}. Confirmé votre taille de main{pt-br}. Confirmou seu tamanho de Mão{de}. Bestätigt Ihre Handgröße"})
				else
					rewardText=joinLang({rewardText, count, "{en}. Looked at your final Score{ru}. Посмотрели на ваш окончательный результат{zh-cn}看过你最终的分数{ko}. 최종 점수 확인{es}. Revisado tu Puntuación Final{fr}. Regardé votre score final{pt-br}. Ollhou para a sua Pontuação Final{de}. Ich habe mir Ihr Endergebnis angesehen."})
				end
				UI.setAttribute("RewardNotes", "text", rewardText)

				--lock end turn button if no cards are played or discarded
				--discard object detection
				local discardAreaCards=0
				for _, b in pairs(getObjectFromGUID(deedDeckDiscardZones[turnOrder[gStates.turnNumber].seatPos]).getObjects()) do
					if b.type=="Card" then discardAreaCards=1 break end
					if b.type=="Deck" then discardAreaCards=b.getQuantity() break end
				end
				if (#playerAreaCards<1 and gStates.endRoundCalled==false and discardAreaCards==turnOrder[gStates.turnNumber].discardCount)
				or gStates.tacticShown==true or gStates.tacticRemove==true then
					UI.setAttribute("EndTurnButton", "interactable", "False")
					UI.setAttribute("EndTurnButtonImage", "image", "Sliced Button/Button New Deactive")
					UI.setAttribute("EndTurnButtonAlt", "interactable", "False")
					UI.setAttribute("EndTurnButtonAltImage", "image", "Sliced Button/Button New Deactive")
					UI.setAttribute("ExtraTurnTacticButton", "interactable", "False")
					UI.setAttribute("ExtraTurnTacticButtonImage", "image", "Sliced Button/Button New Deactive")
				end

				--Show extra button for day tactic 6 and time bending
				if ((turnOrder[gStates.turnNumber].tactic==6 and gStates.dayRound==true and gStates.tacticSixState~="Used") or timeBending==true)
				and gStates.tacticRemove==false and gStates.tacticShown==false then
					UI.setAttribute("ExtraTurnTactic", "active", "true")
					if timeBending==true then
						UI.setAttribute("ExtraTurnTacticButtonText", "text", "{en}Time Bend{ru}Изгиб Времени{zh-cn}时间扭曲{ko}시간 왜곡{es}Salto en el Tiempo{fr}Courbe du Temps{pt-br}Dobrar Tempo{de}Zeitkrümmung")
					else
						UI.setAttribute("ExtraTurnTacticButtonText", "text", "{en}Use Tactic{ru}Использовать Тактику{zh-cn}使用战术卡{ko}전략카드 사용{es}Usar la Táctica{fr}Utiliser la Tactique{pt-br}Usar Tática{de}Taktik Benutzen")
					end
				end

				--Update Fame and Reputation menus
				UI.setAttribute("EndRoundPlusFameText", "text", joinLang({"{en}Gain {ru}Получить {zh-cn}增加{ko}획득 {es}Ganar {fr}Gagner {pt-br}Ganhe {de}Erhalte ", tostring(turnOrder[gStates.turnNumber].fameGain), "{en} Fame{ru} Славу(ы){zh-cn}名望{ko} 명성{es} Fama{fr} Gloire{pt-br} Fama{de} Ruhm"}))
				local prefix="{en}Lose {ru}Потерять {zh-cn}减少{ko}감소 {es}Perder {fr}Perdez {pt-br}Perca {de}Verliere "
				if turnOrder[gStates.turnNumber].repGain>-1 then prefix="{en}Gain {ru}Получить {zh-cn}增加{ko}획득 {es}Ganar {fr}Gagner {pt-br}Ganhe {de}Erhalte " end
				local sufix1="{en} Reputation{ru} Репутацию(и){zh-cn}声誉{ko} 평판{es} Reputación{fr} Réputation{pt-br} Reputação{de} Ansehen"
				if turnOrder[gStates.turnNumber].repGain~=0 and turnOrder[gStates.turnNumber].repGain==(-7-turnOrder[gStates.turnNumber].reputation) or turnOrder[gStates.turnNumber].repGain==(7-turnOrder[gStates.turnNumber].reputation) then
					sufix1="{en} Rep. Max.{ru} Макс. Реп.{zh-cn}最高声誉{ko} 최대 평판{es} Rep. Máx.{fr} Rép. Max.{pt-br} Rep. Máx.{de} Ruf Max."
				end
				local sufix2=""
				if turnOrder[gStates.turnNumber].repGain~=0 and reputationTable[turnOrder[gStates.turnNumber].reputation+turnOrder[gStates.turnNumber].repGain]~=nil then
					sufix2=" ('"..reputationTable[turnOrder[gStates.turnNumber].reputation+turnOrder[gStates.turnNumber].repGain].repDisplay.."')"
					if turnOrder[gStates.turnNumber].reputation+turnOrder[gStates.turnNumber].repGain==-7 then sufix2=" ('X')" end
				end
				UI.setAttribute("EndRoundPlusRepText", "text", joinLang({prefix, tostring(math.abs(turnOrder[gStates.turnNumber].repGain)), sufix1, sufix2}))
			end

			--Check if the current turn mage has started with no deed deck and enable end round buttom.
			UI.setAttribute("EndRoundButton", "interactable", "False")
			UI.setAttribute("EndRoundButtonImage", "image", "Sliced Button/Button New Deactive")
			UI.setAttribute("EndRoundButtonText", "fontSize", "20")
			UI.setAttribute("EndRoundButtonText", "text", joinLang({"{en}Call End of Round {ru}Объявить конец Раунда {zh-cn}宣布结束轮次{ko}라운드 종료 선언 {es}Llamar a Fin de Ronda {fr}Appel fin de Round{pt-br}Fim da Rodada {de}Ende der Runde Einläuten ", gStates.currentRound, "{en} of {ru} из {zh-cn} / {ko} / {es} / {fr} de {pt-br} de {de} von ", gStates.rounds}))
			if gStates.rounds>=10 and gStates.currentRound>=10 then UI.setAttribute("EndRoundButtonText", "fontSize", "18") end
			local found=false
			for _, b in pairs(getObjectFromGUID(deedDeckZones[turnOrder[gStates.turnNumber].seatPos]).getObjects()) do
			 	if b.type=="Deck" or b.type=="Card" then found=true break end
			end
			if found==false then
				--Is this a player or Dummy & Volkare
				if turnOrder[gStates.turnNumber].mage==gStates.positionMageKnight[5] then
					if gStates.positionMageKnight[5]=="Volkare" and gStates.volkareWon==false and gStates.volkareFrenzied==true then
						if gStates.volkareState=="Start" then
							UI.setAttribute("DummyNotes", "Text", "{en}Volkare's Deck is Empty.\n-< FRENZY >-\nVolkare acts as if he drew a Blue Spell and doesn't Reroll any Die.{ru}Колода Волкара пуста.\n-< ЯРОСТЬ >-\nВолкар действует так, как будто он вытащил Синее Заклинание, и не перебрасывает кубики.{zh-cn}沃里卡牌堆是空的。\n-<狂暴>-\n接下来每个回合，沃里卡视为翻开一张法术牌来行动(即移动或攻击两次）。当沃里卡处于狂暴状态时，选择移动方向时始终视为蓝色，但不重掷任何骰子。{ko}볼케어의 더미가 비었습니다.\n-< 광폭 >-\n이제 볼케어는 파란색 마법을 뽑은 것처럼 행동하며, 주사위를 굴리지 않습니다.{es}El mazo de Volkare está vacío.\n-< FRENESÍ >-\nVolkare actúa como si hubiera robado un Hechizo Azul, y no vuelve a lanzar ningún dado.{fr}Le Deck de Volkare est vide.\n-< FRÈSIE >-\nVolkare agit comme s'il avait pioché un sort bleu et ne relance aucun dé.{pt-br}Deck do Volkare está vazio.\n-< FRENESI >-\nVolkare age como se ele tirasse um Feitiço azul e não re-rola nenhum dado.{de}Volkare Deck ist leer.\n-< FRENZY >-\nVolkare tut so, als ob er einen blauen Zauberspruch gezogen hätte und würfelt nicht neu.")
						 	UI.setAttribute("DummyButtonText", "Text", "{en}Process Frenzied Volkare{ru}Ход Волкара в состоянии Ярости{zh-cn}狂暴的沃里卡回合{ko}볼케어(광폭) 진행{es}Procesar Volkare en Frenesí{fr}Processus Volkare Frénétique{pt-br}Processar Volkare em Frenesi{de}Prozess Rasende Volkare")
						else
							UI.setAttribute("DummyButtonText", "Text", "{en}Frenzied Volkare Processed{ru}Волкар в состоянии Ярости сходил{zh-cn}狂暴的沃里卡动完了{ko}진행 완료{es}Volkare en Frenesí Procesado{fr}Volkare Frénétique Traité{pt-br}Volkare em Frenesi Processado{de}Rasende Volkare Verarbeitet")
						end
					end
					if gStates.positionMageKnight[5]~="Volkare" then
						if gStates.endRoundCalled==false then
							UI.setAttribute("DummyButtonText", "Text", joinLang({"{en}Call End of Round {ru}Объявить конец Раунда {zh-cn}宣布结束轮次{ko}라운드 종료 선언 {es}Llamar a Fin de Ronda {fr}Appel fin de Round{pt-br}Fim da Rodada {de}Ende der Runde Einläuten ", gStates.currentRound, "{en} of {ru} из {zh-cn} / {ko} / {es} / {fr} de {pt-br} de {de} von ", gStates.rounds}))
							UI.setAttribute("DummyButton", "onClick", "PreEndRound")
						end
					end
				else
					if getObjectFromGUID(turnOrder[gStates.turnNumber].turnOrderTokenGUID).is_face_down==false
						and gStates.tacticShown==false and gStates.tacticRemove==false and gStates.endRoundCalled==false and #playerAreaCards<1 then
						UI.setAttribute("EndRoundButton", "interactable", "True")
						UI.setAttribute("EndRoundButtonImage", "image", "Sliced Button/Button New Active")
					end
				end
			end
			if gStates.endRoundCalled==true then UI.setAttribute("EndRoundButton", "Text", "{en}End of Round Called{ru}Конец Раунда объявлен{zh-cn}轮次结束宣布完毕{ko}라운드 종료 선언됨{es}Fin de Ronda Llamado{fr}Fin de Round Appelée{pt-br}Fim da Rodada Chamada{de}Ende der Runde Eingeläutet") end

			local notice=false
			local UIColor=positionToColor(gStates.turnNumber)
			--Display Info Pannel if pursuing monsters have two options.
			if gStates.pursuitTwoOption==true then
				UI.setAttribute("NoticeText", "Text", "{en}Pursuing Monster(s) have two Options for the current Player to decide between.{ru}Игрок, чьего героя преследуют, решает, на какую из двух клеток переместится враг.{zh-cn}追击的怪物有两个选项供当前玩家选择. {ko}현재 플레이어는 추적 중인 몬스터의 두 옵션 중 하나를 결정하세요.{es}Los Monstruos que persiguen tienen dos Opciones para que el Jugador actual decida entre ellas.{fr}Les Monstres Poursuivants ont deux Options entre lesquelles le Joueur actuel doit choisir.{pt-br}Monstro(s) Perseguidor(es) tem 2 opções para o jogador atual escolher.{de}Verfolgende Monster haben zwei Optionen, zwischen denen der aktuelle Spieler wählen kann.")
				UI.setAttribute("NoticeBoard", "visibility", "")
				UI.setAttribute("NoticeBoard", "height", "50")
				notice=true
			end

			--Display Info pannel if player needs to deploy a tomb or dungeon token
			if #gStates.locationPlace>0 then
				local site="{en}Village{ru}Деревней{zh-cn}\n要求2: 挨着刚翻开的村庄{ko}마을{es}una Aldea{fr}Village{pt-br}Vila{de}Dorf"
				if gStates.locationPlace[#gStates.locationPlace]=="Secret Tomb" then site="{en}Monastery{ru}Монастырем{zh-cn}\n要求2: 挨着刚翻开的修道院{ko}수도원{es}un Monasterio{fr}Monastère{pt-br}Mosteiro{de}Kloster" end
				UI.setAttribute("NoticeText", "Text", joinLang({"{en}Place a {ru}Поместите жетон {zh-cn}在地图上放置一个{ko}{es}Coloca una ficha de {fr}Placer un{pt-br}Coloque uma ficha de {de}Platziere ein ", translateWord[gStates.locationPlace[#gStates.locationPlace]], "{en} token on an accessible non-swamp, non-feature space next to the {ru} на любую доступную клетку без болота на которой нет никаких мест, соседнюю с {zh-cn}\n要求1: 可进入、非沼泽、上面无地点{ko}을 비어있고, 늪이 아니면서 다음의 장소 주변인 칸에 설치하세요: {es} en un espacio accesible que no sea un pantano, o no tenga ningún elemento adyacente a {fr} jeton sur un espace non marécageux accessible à côté du {pt-br} em um espaço acessível sem ser pântano ou que já tenha algo próximo a {de} plättchen auf ein zugängliches Nicht-Sumpf-, Nicht-Feature-Feld neben dem ", site}))
				UI.setAttribute("NoticeBoard", "visibility", "")
				UI.setAttribute("NoticeBoard", "height", "50")
				notice=true
			end

			--Display Info pannel if End of round is immenant
			if ((nextPlayerEndCalled==true and gStates.playerCount>1) or (gStates.endRoundCalled==true and gStates.playerCount==1)) and
				(gStates.preEndTurn==true or turnOrder[gStates.turnNumber].mage==gStates.positionMageKnight[5]) and gStates.currentRound<gStates.rounds then
				local boxHeight=50
				local endRoundText="{en}The game is about to experience end of round updates.\nPut Banners in discard if desired.{ru}Конец раунда. Скрипт произведет нужные обновления.\nЕсли хотите, можете сбросить знамёна с отрядов.{zh-cn}回合即将结束, 如果需要, 将清理弃牌区{ko}이제 라운드가 종료됩니다.\n원한다면 지금 깃발 장착을 해제하세요.{es}El juego está a punto de experimentar actualizaciones de fin de ronda.\nDescarte los Banners si lo desea.{fr}Le jeu est sur le point de connaître des mises à jour de fin de manche.\nMettez les bannières au rebut si vous le souhaitez.{pt-br}O jogo está prestes a executar as atualizações de fim de Rodada.<size=6>\n\n</size>Coloque os Estandartes na pilha de descarte se assim desejar.{de}Das Spiel wird zum Ende der Runde aktualisiert.\nLegt die Banner auf den Ablagestapel, falls gewünscht."
				if gStates.playerCount==1 then endRoundText=joinLang({endRoundText, "{en}\nDiscard the 2nd offer if playing 'Control over the Offers'{ru}\nПри 'Контроле над доступными картами', сбросьте среднюю доступную карту{zh-cn}\n如果使用“控制供应区”变体规则, 弃掉最左侧两个供应的卡牌{ko}\n변형 규칙 '공급처 갱신 조정'을 적용하려면 지금 하세요.{es}\nDescarta la segunda oferta si juegas 'Control sobre las Ofertas'{fr}\nJetez la 2e offre si vous jouez à 'Contrôle des Offres'{pt-br}\nDiscarte a 2a oferta se estiver jogando com 'Controle sobre ofertas'{de}\nWirf das 2. Angebot ab, wenn du 'Kontrolle über die Angebote' spielst."}) boxHeight=boxHeight+20 end
				if gStates.gameScenario=="Mines Liberation" then endRoundText=joinLang({endRoundText, "{en}\nCollect a crystal for each Liberated Mine.{ru}Получите кристалл из всех Освобожденных шахт.{zh-cn}为每个解放了的矿山收集一块魔晶{ko}\n각 해방된 광산에서 수정을 얻으세요.{es}\nRecoge un cristal por cada Mina Liberada.{fr}\nRécupérez un cristal pour chaque Mine Libérée.{pt-br}\nColete um Cristal para cada Mina Liberada.{de}\nSammle einen Kristall für jede befreite Mine."}) boxHeight=boxHeight+20 end
				UI.setAttribute("NoticeBoard", "height", boxHeight)
				UI.setAttribute("NoticeText", "Text", endRoundText)
				UI.setAttribute("NoticeBoard", "visibility", "")
				notice=true
			end

			--Display Info pannel if tactics are shown
			UI.setAttribute("DrawOne", "interactable", "true")
			UI.setAttribute("DrawOneImage", "image", "Sliced Button/Button New Active")
			if gStates.tacticRemove==true or gStates.tacticShown==true then
				if gStates.tacticRemove==true then
					UI.setAttribute("NoticeText", "Text", "{en}Choose tactic(s) to be removed from the Game{ru}Выберите тактику(и), которая будет удалена из игры{zh-cn}选择要从游戏中移除的战术卡{ko}게임에서 제거할 전략 카드를 고르세요.{es}Elige la táctica(s) que quieres eliminar del Juego{fr}Choisissez la tactique(s) à retirer du Jeu{pt-br}Escolha tática(s) a ser(em) removida(s) do jogo.{de}Wähle die Taktik(en), die aus dem Spiel entfernt werden sollen")
				else
					UI.setAttribute("NoticeText", "Text", joinLang({translateWord[turnOrder[gStates.turnNumber].mage], "{en} needs to choose a tactic from the center{ru} должен(на) выбрать Тактику из центра{zh-cn}需要从中间选择一个战术{ko}의 전략 카드를 선택하세요.{es} necesita elegir una táctica del centro{fr} doit choisir une tactique du centre{pt-br} precisa escolher uma tática do centro.{de} muss eine Taktik aus dem Zentrum wählen"}))
				end
				UI.setAttribute("DrawOne", "interactable", "False")
				UI.setAttribute("DrawOneImage", "image", "Sliced Button/Button New Deactive")
				UI.setAttribute("NoticeBoard", "visibility", "")
				UI.setAttribute("NoticeBoard", "height", "50")
				notice=true
			else --turn off help notes after first round of tactic selection
				gStates.help=true
				DisplayHelp(nil, "-1", "Game Started")
			end

			--Remove or Display the notice board as needed
			if notice==false and gStates.noticeShown==true then
				UI.hide("NoticeBoard")
				gStates.noticeShown=false
			end
			if notice==true and gStates.noticeShown==false then
				UI.show("NoticeBoard")
				gStates.noticeShown=true
			end

			--Update Model Bases and color bars to hand color
			for a=1, 4, 1 do--run through all positions
				for b=1, #turnOrder, 1 do
					if turnOrder[b].seatPos==a then--figure out which turn order matches the position
						local turnColor=1
						for _, seat in pairs(Player.getAvailableColors()) do
							if math.ceil((Player[seat].getHandTransform().position[1]+97.59)/40)==turnOrder[b].seatPos then break end
							turnColor=turnColor+1
						end
						if turnColor<=#Player.getAvailableColors() then
							local color=Player.getAvailableColors()[turnColor]
							for c=1, #mageKnights,1 do
								if mageKnights[c].mage==turnOrder[b].mage and turnOrder[b].mage~=gStates.positionMageKnight[5] then--figures out which Mage is in that position
									if getObjectFromGUID(mageKnights[c].model)~=nil then getObjectFromGUID(mageKnights[c].model).setColorTint(color) end
									if getObjectFromGUID(mageKnights[c].standee)~=nil then getObjectFromGUID(mageKnights[c].standee).setColorTint(color) end
									if getObjectFromGUID(colorBand[a])~=nil then getObjectFromGUID(colorBand[a]).setColorTint(color) end
									break
								end
							end
						end
					end
				end
			end

			--update Deed and discard deck discriptions
			local obj={}
			for _, playerStats in pairs(turnOrder) do
				local objSearch={["deed"]=getObjectFromGUID(deedDeckZones[playerStats.seatPos]).getObjects(), ["discard"]=getObjectFromGUID(deedDeckDiscardZones[playerStats.seatPos]).getObjects()}
				for zoneType, objInZone in pairs(objSearch) do
					for _, posibleDeck in pairs(objInZone) do
						if posibleDeck.type=="Deck" then
							if playerStats.mage~=gStates.positionMageKnight[5] then
								for color, playerZone in pairs(gStates.handColors) do
									if playerZone==playerStats.seatPos then posibleDeck.setGMNotes(color) end
								end
							end
							local deckStats={	["Red"]={0, "{en}Red Card(s){ru}Красная(ых) карточка(и){zh-cn}红色卡{ko}빨간색 카드{es}Tarjeta(s) Roja{fr}Carte(s) Rouge{pt-br}Cartas Vermelhas{de}Rote Karten"},
												["Green"]={0, "{en}Green Card(s){ru}Зеленая(ых) карточка(и){zh-cn}绿色卡{ko}녹색 카드{es}Tarjeta(s) Verde{fr}Carte(s) Verte{pt-br}Cartas Verdes{de}Grüne Karten"},
												["Blue"]={0, "{en}Blue Card(s){ru}Синяя(ых) карточка(и){zh-cn}蓝色卡{ko}파란색 카드{es}Tarjeta(s) Azul{fr}Carte(s) Bleue{pt-br}Cartas Azuis{de}Blaue Karten"},
												["White"]={0, "{en}White Card(s){ru}Белая(ых) карточка(и){zh-cn}白色卡{ko}흰색 카드{es}Tarjeta(s) Blanca{fr}Carte(s) Blanche{pt-br}Cartas Brancas{de}Weiße Karten"},
												["Starting"]={0, "{en}Basic Action(s){ru}Базовое(ых) действие(я){zh-cn}基本行动卡{ko}기본 액션 카드{es}Acciones Básicas{fr}Action(s) de Base{pt-br}Ações Básicas{de}Basis Aktionen"},
												["Advanced Action"]={0, "{en}Advanced Action(s){ru}Особое(ые) действие(я){zh-cn}高级行动卡{ko}상급 액션 카드{es}Acciones Avanzadas{fr}Action(s) Avancée{pt-br}Ações Avançadas{de}Erweiterte Aktionen"},
												["Spell"]={0, "{en}Spell(s){ru}Заклинание(я){zh-cn}法术卡{ko}마법 카드{es}Hechizo(s){fr}Sort(s){pt-br}Feitiços{de}Zauber"},
												["Wound"]={0, "{en}Wound(s){ru}Рана(ы){zh-cn}创伤卡{ko}부상{es}Herida(s){fr}Blessure(s){pt-br}Ferimentos{de}Wunde(n)"},
												["Artifact"]={0, "{en}Artifact(s){ru}Артефакт(а){zh-cn}圣器卡{ko}유물{es}Artefacto(s){fr}Artefact(s){pt-br}Artefatos{de}Artefakt(e)"},
												["Move"]={0, "{en}Card(s) are Move{ru}Карта(ы) - это Движение{zh-cn}移动卡{ko}장의 이동 카드{es}Las Cartas se Mueven{fr}Les cartes sont Mouvements{pt-br}Cartas são Movimento{de}Karte(n) sind Bewegung"},
												["Combat"]={0, "{en}Card(s) are Combat{ru}Карта(ы) - это Боевые{zh-cn}战斗卡{ko}장의 전투 카드{es}Las Cartas son de Combate{fr}Les cartes sont Combat{pt-br}Cartas são Combate{de}Karte(n) sind Angriff"},
												["Influence"]={0, "{en}Card(s) are Influence{ru}Карта(ы) - это Влияние{zh-cn}影响力卡{ko}장의 영향력 카드{es}Las Cartas tienen Influencia{fr}Les cartes sont Influence{pt-br}Cartas são Influência{de}Karte(n) sind Einfluss"},
												["Special"]={0, "{en}Card(s) are Special{ru}Карта(ы) - это Особая{zh-cn}特殊卡{ko}장의 특수효과 카드{es}Las Cartas son Especiales{fr}Les cartes sont Spéciales{pt-br}Cartas são Especiais{de}Karte(n) sind Spezial"},
												["Heal"]={0, "{en}Card(s) are Heal{ru}Карта(ы) - это Лечение{zh-cn}健康卡{ko}장의 치유 카드{es}Las Cartas se Curan{fr}Les cartes sont Guéries{pt-br}Cartas são Cura{de}Karte(n) sind Heilung"},
												["Action"]={0, "{en}Card(s) are Action{ru}Карта(ы) - это Действие{zh-cn}基础行动卡{ko}장의 행동 카드{es}Las Cartas son Acción{fr}Les cartes sont des Actions{pt-br}Cartas são Ações{de}Karte(n) sind Aktionen"}}
							--count card types colours, and abilities
							local cardSearch={["deed"]=posibleDeck.getObjects()}
							posibleDeck.setName("{en}Deed Cards{ru}Колода Деяний{zh-cn}行动卡{ko}행동 카드{es}Tarjetas de Escritura{fr}Cartes D'acte{pt-br}Cartas de Façanha{de}Tatkarten")
							if zoneType=="deed" and playerStats.tactic==6 and gStates.dayRound==false and #gStates.powerStored>0 then
								cardSearch={["deed"]=posibleDeck.getObjects(), ["stored"]=gStates.powerStored}
								posibleDeck.setName(joinLang({"{en}Deed Cards +{ru}Карты Деяний +{zh-cn}行动卡+{ko}행동 카드 +{es}Tarjetas de Escritura +{fr}Cartes D'acte +{pt-br}Cartas de Façanha +{de}Tatkarten +", #gStates.powerStored, "{en} Stored{ru} Сбережено{zh-cn}储存{ko} 장 저장됨{es} Almacenado{fr} Stockée{pt-br} Armazenada{de} Gelagert"}))
							end
							for _, cardpile in pairs(cardSearch) do
								for _, deedCard in pairs(cardpile) do
									if gameCards[deedCard.guid]~=nil and gameCards[deedCard.guid].cardType~="Regular Unit" and gameCards[deedCard.guid].cardType~="Elite Unit" then
										deckStats[gameCards[deedCard.guid].cardType][1]=deckStats[gameCards[deedCard.guid].cardType][1]+1
										for _, cardColor in pairs(gameCards[deedCard.guid].color) do deckStats[cardColor][1]=deckStats[cardColor][1]+1 end
										for _, cardAction in pairs(gameCards[deedCard.guid].action) do if cardAction~="Banner" then deckStats[cardAction][1]=deckStats[cardAction][1]+1 end end
									else
										deckStats["Wound"][1]=deckStats["Wound"][1]+1
									end
								end
							end
							--write a description
							local deckDescription=""
							for statName, statValue in pairs(deckStats) do
								if statValue[1]>0 then
									deckDescription=joinLang({deckDescription, statValue[1], " ", statValue[2], "\n"})
								end
								if statName=="White" or statName=="Artifact" then deckDescription=joinLang({deckDescription, "----------\n"}) end
							end
							deckDescription=joinLang({deckDescription, "----------"})
							posibleDeck.setDescription(deckDescription)
						end
					end
				end
			end

			--Increase hand size for day tactic 4
			local cardsInHand=0
			if turnOrder[gStates.turnNumber].seatPos<5 then
				for a, possibleCards in pairs(getObjectFromGUID(handZones[turnOrder[gStates.turnNumber].seatPos]).getObjects()) do
					if possibleCards.type=="Card" then cardsInHand=cardsInHand+1 end
				end
			end
			if turnOrder[gStates.turnNumber].tactic==4 and gStates.dayRound==true and gStates.tacticShown==false and cardsInHand>=2 then
				gStates.tactic4HandBonus=1
			else
				gStates.tactic4HandBonus=0
			end

			UI.setAttribute("RewardCheck", "active", "false")
			UI.setAttribute("EndGameButton", "active", "false")
			if gStates.preEndTurn==true then
				UI.setAttribute("RewardCheck", "active", "true")
				UI.setAttribute("EndGameButton", "active", "true")
				if gStates.timeBending=="Started" or (gStates.endRoundCalled==true and gStates.currentRound>=gStates.rounds) then
					UI.setAttribute("EndGameButton", "active", "false")
				end
			end
			if UIColor=="Black" then UIColor="rgb(0,0,0)" end
			UI.setAttribute("MainGameNotes", "color", UIColor)
			UI.setAttribute("RewardNotes", "color", UIColor)
			UI.setAttribute("DrawHandText", "text", joinLang({"{en}Draw up to {ru}Добрать до {zh-cn}抽满至{ko}카드 보유 제한 {es}Roba hasta {fr}Piochez jusqu'à {pt-br}Compre até {de}Zieh auf ", tostring(turnOrder[gStates.turnNumber].hand+turnOrder[gStates.turnNumber].handBonus+gStates.tactic4HandBonus), "{en} cards{ru} карт{zh-cn}张手牌{ko} 장{es} cartas{fr} cartes{pt-br} cartas{de} karten"}))
			UI.setAttribute("DrawHandText", "color", "Black")
			if turnOrder[gStates.turnNumber].hand+turnOrder[gStates.turnNumber].handBonus+gStates.tactic4HandBonus>turnOrder[gStates.turnNumber].baseHand then UI.setAttribute("DrawHandText", "color", "rgb(0.4, 0.1, 0.2)") end
			if turnOrder[gStates.turnNumber].mage~=gStates.positionMageKnight[5] then
				local mainText=joinLang({"{en}<size=25>{ru}<size=25>{zh-cn}<size=25>{ko}<size=25>{es}<size=25>Turno de {fr}<size=25>Au tour de {pt-br}<size=25>Turno de {de}<size=25>", translateWord[turnOrder[gStates.turnNumber].mage], "{en}'s Turn</size><size=6>\n\n</size>Reputation = {ru} Ходит</size><size=6>\n\n</size>Репутация =  {zh-cn}的回合</size><size=6>\n\n</size>声誉={ko} 차례</size><size=6>\n\n</size>평판 = {es}</size><size=6>\n\n</size>Reputación = {fr}</size><size=6>\n\n</size>Réputation = {pt-br}</size><size=6>\n\n</size>Reputação = {de}'s Turn</size><size=6>\n\n</size>Ansehen = ", reputationTable[turnOrder[gStates.turnNumber].reputation].repDisplay, "{en}\nFame = {ru}\nСлава = {zh-cn}\n名望={ko}\n명성 = {es}\nFama = {fr}\nGloire = {pt-br}\nFama = {de}\nRuhm = ", turnOrder[gStates.turnNumber].fame})
				local levelUpType="{en}\n(Skill & Advanced Action){ru}\n(Навык и Особое действие){zh-cn}\n技能和高级动作{ko}\n(스킬 및 고급 액션){es}\n(Habilidad y Acción Avanzada){fr}\n(Compétence et Action Avancée){pt-br}\n(Habilidade e Ação Avançada){de}\n(Geschicklichkeit & Fortgeschrittene Aktion)"
				if turnOrder[gStates.turnNumber].level==2 or turnOrder[gStates.turnNumber].level==4 or turnOrder[gStates.turnNumber].level==6 or turnOrder[gStates.turnNumber].level==8 or turnOrder[gStates.turnNumber].level==10 or turnOrder[gStates.turnNumber].level==12 then levelUpType="{en}\n(Command Token){ru}\n(Жетон командования){zh-cn}\n命令令牌{ko}\n(명령 토큰){es}\n(Token de Comando){fr}\n(Jeton de Commande){pt-br}\n(Token de Comando){de}\n(Kommando-Token)" end
				if fameForUp>0 then mainText=joinLang({mainText, "{en}<size=6>\n\n</size>Next Level in {ru}<size=6>\n\n</size>До повышения уровня {zh-cn}<size=6>\n\n</size>升级还需{ko}<size=6>\n\n</size>다음 레벨까지 {es}<size=6>\n\n</size>Siguiente nivel en {fr}<size=6>\n\n</size>Niveau suivant dans {pt-br}<size=6>\n\n</size>Próximo Nível em {de}<size=6>\n\n</size>Nächstes Level in ", fameForUp, "{en} Fame{ru} Слава(ы){zh-cn}名望{ko} 명성 남음{es} Fama{fr} Gloire{pt-br} Fama{de} Ruhm", levelUpType}) else mainText=joinLang({mainText, "\n "}) end
				UI.setAttribute("MainGameNotes", "text", mainText)
			else
				UI.setAttribute("MainGameNotes", "text", joinLang({"{en}<size=25>{ru}<size=25>{zh-cn}<size=25>{ko}<size=25>{es}<size=25>Turno de {fr}<size=25>Au tour de {pt-br}<size=25>Turno de {de}<size=25>", translateWord[turnOrder[gStates.turnNumber].mage], "{en}'s Turn</size>{ru} Ходит</size>{zh-cn}的回合</size>{ko} 차례</size>{es}</size>{fr}</size>{pt-br}</size>{de}'s Turn</size>"}))
			end
			UI.show("MainGame")
			mainUIPause=nil
		end, 0.1)
	end
end

--work out which color hand has the current turns mage
function positionToColor(turnNumber)
	local color="Black"
	if turnOrder[turnNumber].mage~=gStates.positionMageKnight[5] then
		for _, handColor in pairs(Player.getAvailableColors()) do
			if turnOrder[turnNumber].seatPos==math.ceil((Player[handColor].getHandTransform().position[1]+97.59)/40) then color=handColor break end
		end
	end
	return color
end

--Tactic Showing and Hiding
function tacticToggle()
	--rearanges the turn order tokens
	function turnOrderSort()
		for a=1, #turnOrder, 1 do
			getObjectFromGUID(turnOrder[a].turnOrderTokenGUID).unlock()
			getObjectFromGUID(turnOrder[a].turnOrderTokenGUID).setPositionSmooth({-1.90, 1.2, -18.00-(1.4*a)})
		end
	end

	--Show all tactics available
	if gStates.tacticShown==true then
		broadcastToAll("{en}Turn order Re-Organised based on tactic card selection{ru}Порядок хода игроков изменился в соответствии с выбранными Тактиками{zh-cn}玩家行动顺序基于战术卡的选择改变了{ko}라운드 순서가 전략 카드에 따라 배치되었습니다{es}Orden de turnos reorganizado según la selección de la tarjeta de táctica{fr}Ordre de tour réorganisé en fonction de la sélection de la carte tactique{pt-br}Ordem de Turno re-organizada baseada nas seleções de táticas{de}Zugreihenfolge neu organisiert basierend auf der Auswahl der Taktikkarten", {1,1,0.5})
		turnOrderSort()
		Wait.time(function()
			local depth=-8
			if gStates.dayRound==true then depth=-4 end
			for a=1, 6, 1 do
				for _, obj in pairs(getObjectFromGUID(tacticZones[a]).getObjects()) do
					if obj.getName():sub(1,3)=="Day" or obj.getName():sub(1,3)=="Nig" then
						obj.lock()
						obj.setPosition({obj.getPosition()[1], depth, obj.getPosition()[3]})
						break
					end
				end
			end
		end, 0.5)--allow time for the smooth claim to pull the cards out of the zone
		UI.setAttribute("ScoreButtonActual", "interactable", "True")
		UI.setAttribute("ScoreButtonActualImage", "image", "Sliced Button/Button New Active")
		gStates.tacticShown=false
		--remove note about re-areanging turn tokens
		if getObjectFromGUID("0934f2")~=nil then getObjectFromGUID("0934f2").destruct()	end
	else
		gStates.tacticSixState="notClaimed"
		gStates.tacticShown=true
		broadcastToAll("{en}Start of a Round. Please select a tactic Card for the round.{ru}Начало раунда. Пожалуйста, выберите Тактику на этот раунд из центра.{zh-cn}轮次开始了, 请选择本轮战术卡.{ko}라운드가 시작되었습니다. 전략 카드를 고르세요.{es}Inicio de una Ronda. Selecciona una carta de táctica para la Ronda.{fr}Début d'une Manche. Veuillez sélectionner une carte tactique pour le Rounde.{pt-br}Início de Rodada. Por favor selecione uma carta de Tática para a Rodada.{de}Beginn einer Runde. Bitte wählen Sie eine taktische Karte für die Runde", {1,1,0.5})
		local hide=0
		local show=6
		local depth=-8
		if gStates.dayRound==true then hide=6 show=0 depth=-4 end
		for a=1, 6, 1 do
			if getObjectFromGUID(tacticCard[a+hide])~=nil then
				getObjectFromGUID(tacticCard[a+hide]).setPosition({-16.50+(4*a), depth, 24.00})
				getObjectFromGUID(tacticCard[a+hide]).lock()
			end
			if getObjectFromGUID(tacticCard[a+show])~=nil then
				getObjectFromGUID(tacticCard[a+show]).unlock()
				getObjectFromGUID(tacticCard[a+show]).setRotation({0.00, 180, 0.00})
				getObjectFromGUID(tacticCard[a+show]).setPosition({-16.50+(4*a), 1.5, -14.00})
				getObjectFromGUID(tacticCard[a+show]).lock()
			end
		end
		UI.setAttribute("ScoreButtonActual", "interactable", "False")
		UI.setAttribute("ScoreButtonActualImage", "image", "Sliced Button/Button New Deactive")
		if getObjectFromGUID("0934f2")==nil then turnOrderSort() end
		mainUIUpdate("Tactic Togle")
	end
	claimButtonRefresh()
	cameraControl(nil, "-1", "tacticChanged")
end

--Move's an offer or tactic card to a player's location
local fillWait=false
function claimMove(player, mouseButton, id)
	if mouseButton~="-3" then
		if legalPlayerCheck(player.color, turnOrder[gStates.turnNumber].seatPos)==true and turnOrder[gStates.turnNumber].mage~=gStates.positionMageKnight[5] then
			local claimedCard=getObjectFromGUID(id:sub(1, 6))
			if claimedCard~=nil then
				claimedCard.unlock()
				local source=id:sub(7, string.len(id))
				if source~="unit" then
					if source:sub(1, string.len(source)-1)=="tactic" then
						claimedCard.setPositionSmooth({(turnOrder[gStates.turnNumber].seatPos*40)-117.83 , 3.0, -43.16})
					else
						claimedCard.setPosition({claimedCard.getPosition()[1], claimedCard.getPosition()[2]+3, claimedCard.getPosition()[3]})
					end
					cardClaim=true
					Wait.time(function() cardClaim=false end, 2)
					--add decal to tactic if playing Ultimate Conquest
					if gStates.gameScenario=="Ultimate Conquest" then
						for _, mage2 in pairs(mageKnights) do
							if mage2.mage==turnOrder[gStates.turnNumber].mage then
								local posX=-1*((turnOrder[gStates.turnNumber].seatPos*0.34)-0.85)
								Wait.time(function()
									claimedCard.addDecal({name="Used Already Shield", url=mage2.shieldImage,
									position={posX, 0.11, -0.9}, rotation={90.0, 180.0, 0.0}, scale={0.4, 0.4, 1}})
								end, 1)
							end
						end
					end
					--put the card into the deck to get around shrinking deck problem.
					local deedDeckFound=false
					if mouseButton=="-1" and source:sub(1, string.len(source)-1)~="tactic" then
						for a, b in pairs(getObjectFromGUID(deedDeckZones[turnOrder[gStates.turnNumber].seatPos]).getObjects()) do
							if (b.type=="Deck") and source~="tactic" then--b.type=="Card" or
								b.putObject(claimedCard)
								turnOrder[gStates.turnNumber].deedCount=turnOrder[gStates.turnNumber].deedCount+1
								deedDeckFound=true
								break
							end
						end
					end
					if mouseButton=="-2" and source:sub(1, string.len(source)-1)~="tactic" then
						deedDeckFound=true
						claimedCard.setPositionSmooth({(turnOrder[gStates.turnNumber].seatPos*40)-105.0 , 4.59, -47.55})
					end
					if deedDeckFound==false and source:sub(1, string.len(source)-1)~="tactic" then claimedCard.flip() claimedCard.setPositionSmooth({(turnOrder[gStates.turnNumber].seatPos*40)-114.19 , 3.0, -43.16}) end
					if source=="offer" and fillWait==false then fillWait=true Wait.time(function() fillSlide() fillWait=false end, 1.2) end
					if source=="artifactReward" then
						if turnOrder[gStates.turnNumber].avatarLocation:sub(1, 4)=="city" then gStates.theGauntletArtifactClaimed=true end
						gStates.dealtArtifacts[id:sub(1, 6)]=false
						claimedCard.UI.setXmlTable({{}})
						local remainingGUID={}
						for GUID, state in pairs(gStates.dealtArtifacts) do if state==true then remainingGUID[#remainingGUID+1]=GUID end end
						if #remainingGUID==1 then
							--return last card
							local PosOrigin=getObjectFromGUID("ac75c4").getPosition()
							getObjectFromGUID("ac75c4").setPositionSmooth({getObjectFromGUID("ac75c4").getPosition()[1], getObjectFromGUID("ac75c4").getPosition()[2]+2, getObjectFromGUID("ac75c4").getPosition()[3]})
							getObjectFromGUID(remainingGUID[1]).unlock()
							getObjectFromGUID(remainingGUID[1]).setRotation({0, 180, 180})
							getObjectFromGUID(remainingGUID[1]).setPositionSmooth(PosOrigin)
							getObjectFromGUID(remainingGUID[1]).UI.setXmlTable({{}})
							--reset buttons
							getObjectFromGUID("ac75c4").UI.setAttribute("ac75c4ArtifactDown", "active", "true")
							getObjectFromGUID("ac75c4").UI.setAttribute("ac75c4ArtifactOffer", "active", "true")
							getObjectFromGUID("ac75c4").UI.setAttribute("ac75c4ArtifactUp", "active", "true")
							gStates.artifactRewards=1
							gStates.dealtArtifacts=nil
							getObjectFromGUID("ac75c4").UI.setAttribute("ac75c4ArtifactOfferText", "text", joinLang({"{en}Reward {ru}Награда {zh-cn}奖励{ko}보상 {es}Premiar {fr}Reward {pt-br}Premiar {de}Belohnung ", gStates.artifactRewards}))
						end
					end
					if gameCards[claimedCard.guid]~=nil and source~="artifactReward" then
						broadcastToAll(joinLang({translateWord[turnOrder[gStates.turnNumber].mage], "{en} gained {ru} получает {zh-cn}增加了{ko}의 획득:  {es} ganó {fr} a subi {pt-br} ganhou {de} gewonnen ", gameCards[claimedCard.guid].name[1], "."}), positionToColor(gStates.turnNumber))
					else
						broadcastToAll(joinLang({translateWord[turnOrder[gStates.turnNumber].mage], "{en} gained {ru} получает {zh-cn}增加了{ko}의 획득:  {es} ganó {fr} a subi {pt-br} ganhou {de} gewonnen ", getObjectFromGUID(claimedCard.guid).getName(), "."}), positionToColor(gStates.turnNumber))
					end
				else
					if fillWait==false then--Move the Unit card to an empty unit spot
						local unitArray={{command=false, unit=false},{command=false, unit=false},{command=false, unit=false},{command=false, unit=false},{command=false, unit=false},{command=false, unit=false}}
						for a, obj in pairs(getObjectFromGUID(playerUnitAreas[turnOrder[gStates.turnNumber].seatPos]).getObjects()) do
							--if obj.getName()~=nil then
								if obj.getGMNotes()=="Command Token" or obj.getGMNotes()=="Bonds of Loyalty" or obj.guid=="8dbce4" then unitArray[math.ceil((obj.getPosition()[1]+105.36-(turnOrder[gStates.turnNumber].seatPos*40))/3.75)].command=true end
								if obj.getName()=="Regular Unit" or obj.getName()=="Elite Unit" then unitArray[math.ceil((obj.getPosition()[1]+105.36-(turnOrder[gStates.turnNumber].seatPos*40))/3.75)].unit=true end
							--end
						end
						local found=false
						for a=1, 6, 1 do
							if unitArray[a].command==true and unitArray[a].unit==false then
								found=true
								local adjust=107.41-(a*3.84)
								claimedCard.setPositionSmooth({(turnOrder[gStates.turnNumber].seatPos*40)-adjust, 2.0, -34.74})
								fillWait=true
								Wait.frames(function() Wait.condition(function() fillWait=false end, function() return claimedCard.resting end) end, 5)
								if gameCards[claimedCard.guid]~=nil then
									broadcastToAll(joinLang({translateWord[turnOrder[gStates.turnNumber].mage], "{en} gained {ru} получает {zh-cn}增加了{ko}의 획득:  {es} ganó {fr} a subi {pt-br} ganhou {de} gewonnen ", gameCards[claimedCard.guid].name[1], "."}), positionToColor(gStates.turnNumber))
								end
								break
							end
						end
						if found==false then broadcastToAll("{en}You have no free command tokens to enlist another unit{ru}У вас нет свободного жетона командования, чтобы нанять еще один отряд{zh-cn}你没有闲置的位置招募新部队{ko}유닛을 고용할 지휘 토큰이 부족합니다{es}No tienes fichas de mando gratuitas para alistar otra unidad{fr}Vous n'avez pas de jetons de commande gratuits pour enrôler une autre unité{pt-br}Você não tem Fichas de Comando livres para recrutar outra unidade{de}Du hast keine freien Befehlsmarken, um eine andere Einheit anzuwerben.", {1,0,0}) end
						--give warning if claiming a unit from a spot you are not on.
						if gameCards[claimedCard.guid]~=nil then
							local found=false
							for a, b in pairs(gameCards[claimedCard.guid].recruit) do
								if b==turnOrder[gStates.turnNumber].avatarLocation then found=true break end
								if b==turnOrder[gStates.turnNumber].avatarLocation:sub(1,4) or turnOrder[gStates.turnNumber].avatarLocation=="city white" then found=true break end
								if gStates.gameScenario=="The Chaos Rift" and turnOrder[gStates.turnNumber].avatarLocation=="keep" and b=="village" then found=true break end
							end
							if found==false then broadcastToAll("{en}Claimed Unit normally isn't recruited from the location you're currently at.{ru}Забранный Отряд обычно не нанимается из того места, где вы в данный момент находитесь.{zh-cn}你所在的位置通常不能招募这个部队{ko}보통은, 그 유닛을 현재 장소에서 고용할 수 없습니다{es}La Unidad reclamada normalmente no se recluta en la ubicación en la que se encuentra actualmente.{fr}L'Unité réclamée n'est normalement pas recrutée à l'endroit où vous vous trouvez actuellement.{pt-br}Unidade Clamada normalmente não é recrutada da localização que você está agora.{de}Die beanspruchte Einheit wird normalerweise nicht von dem Ort rekrutiert, an dem Sie sich gerade befinden.", positionToColor(gStates.turnNumber)) end
						end
					else
						broadcastToAll("{en}Let the last card settle before claiming the next unit.{ru}Не спешите. Позвольте предыдущей карте переместиться, прежде чем брать следующую.{zh-cn}征召下一个部队前, 把上一个结算清{ko}이전 유닛이 완전히 놓일 때 까지 기다려주세요{es}Deje que la última carta se asiente antes de reclamar la siguiente unidad.{fr}Laissez la dernière carte s'installer avant de réclamer l'unité suivante.{pt-br}Deixe a última carta se encaixar antes de clamar a próxima unidade.{de}Lassen Sie die letzte Karte ruhen, bevor Sie die nächste Einheit beanspruchen.", {1,0,0})
					end
				end
				--activate some of the tactics effects.
				if source:sub(1, string.len(source)-1)=="tactic" then
					turnOrder[gStates.turnNumber].tactic=tonumber(source:sub(7, string.len(source)))
					if gStates.dayRound==true and turnOrder[gStates.turnNumber].tactic==5 then
						drawUpTo({color="Black"}, "-1", "DrawOne")
						drawUpTo({color="Black"}, "-1", "DrawOne")
					end
					if gStates.dayRound==true and turnOrder[gStates.turnNumber].tactic==2 then
						if getObjectFromGUID("a000a4")~=nil then getObjectFromGUID("a000a4").Call("buttonActivate") end--activate Day Tactic 2 buttons
					end
					nextTurnMerged("incrementTurn")
				end
			end
		else
			if turnOrder[gStates.turnNumber].mage==gStates.positionMageKnight[5] then
				if turnOrder[gStates.turnNumber].mage=="Volkare" then
					broadcastToAll("{en}Volkare doesn't claim cards{ru}Волкар не берет карты{zh-cn}傻孩子, 沃里卡不选卡{ko}볼케어는 카드를 획득하지 않습니다{es}Volkare no reclama cartas{fr}Volkare ne réclame pas de cartes{pt-br}Volkare não clama cartas{de}Volkare beansprucht keine Karten", {1,0,0})
				else
					broadcastToAll("{en}Dummy doesn't claim cards this way{ru}Виртуальный игрок не получает карты таким образом{zh-cn}虚拟玩家不会这样选卡{ko}가상 플레이어는 카드를 이런 방식으로 얻지 않습니다{es}El muñeco no reclama cartas de esta manera{fr}Le mannequin ne réclame pas les cartes de cette façon{pt-br}Jog. Fictício não clama cartas desta forma{de}Dummy beansprucht auf diese Weise keine Karten", {1,0,0})
				end
			end
		end
	end
end

--Moves claimed skill to player location
local masterOfChaosPause=false
function skillMove(player, mouseButton, id)
	if mouseButton=="-1" then
		if legalPlayerCheck(player.color, gStates.skillButtons)==true then--and turnOrder[gStates.turnNumber].mage~=gStates.positionMageKnight[5]
			--convert button pressed to xy coordinates
			local claimedSkill=getObjectFromGUID(id:sub(1, 6))
			local source=tonumber(id:sub(7, string.len(id)))
			local buttonToXYZ={(math.floor(source/8)*3.7)+11, 2, ((source-(math.floor(source/8)*8))*1.35)-25.3}
			--use cooordinates to find matching recorded skills
			for skillGUID, skillPos in pairs(gStates.mageSkills) do
				if math.floor(buttonToXYZ[1])==math.floor(skillPos[1]) and math.floor(buttonToXYZ[3])==math.floor(skillPos[3]) then
					--update skill location register with a free spot on player board
					local count=0
					for skillGUID, skillPos in pairs(gStates.mageSkills) do
						if skillPos[3]<-36.9 and math.floor(skillPos[1])==math.floor(((gStates.skillButtons*40)-107.45)) then count=count+1 end
					end
					gStates.mageSkills[skillGUID]={((gStates.skillButtons*40)-107.45), 1.1, -38.67-(1.48*count)}
					--Bonds of Loyalty goes to unit area
					if skillGUID=="f30dd4" then
						gStates.mageSkills[skillGUID]={((gStates.skillButtons*40)-84.38), 1.1, -31.19}
						local unitPlace={{36.0, 1.25, -4.2}, {31.2, 1.25, -4.2}, {26.4, 1.25, -4.2}, {21.6, 1.25, -4.2}, {16.8, 1.25, -4.2}, {12.0, 1.25, -4.2}, {7.2, 1.25, -4.2}, {2.4, 1.25, -4.2}, {-2.4, 1.25, -4.2}}
						local params={smooth=true, rotation={0, 180, 0}}
						--Place Unit Cards
						for a=gStates.totalUnitCount+1, gStates.totalUnitCount+2, 1 do
							params.position=unitPlace[a]
							getObjectFromGUID(getObjectFromGUID("4fa2f2").getObjects()[1].guid).takeObject(params)
						end
						broadcastToAll("{en}Two more Regular units added to the Unit Offer for this round.{ru}Два дополнительных обычных отряда доступны в этом раунде{zh-cn}本轮增加了两个部队供应{ko}일반 유닛 두 개를 공급처에 추가합니다{es}Se agregaron dos unidades regulares más a la oferta de unidades para esta ronda.{fr}Deux autres unités régulières ajoutées à l'offre d'unités pour ce tour.{pt-br}2 unidades Regulares a mais adicionadas a Oferta de Unidades por esta Rodada{de}Zwei weitere reguläre Einheiten wurden dem Einheitenangebot für diese Runde hinzugefügt.", {1,1,0.5})
					end
					--Master of Chaos
					if skillGUID=="1ff34f" then	masterOfChaosSetup(gStates.skillButtons) end
					--move selected skill
					getObjectFromGUID(skillGUID).unlock()
					getObjectFromGUID(skillGUID).setPositionSmooth(gStates.mageSkills[skillGUID])
					if gStates.motivationSkill[skillGUID]~=nil then
						gStates.motivationSkill[skillGUID].pos=gStates.skillButtons
						gStates.motivationSkill[skillGUID].state="active"
						mainUIUpdate("Skill Claimed")
					end
					break
				end
			end
			--move remaining skills down
			for skillGUID, skillPos in pairs(gStates.mageSkills) do
				if math.floor(buttonToXYZ[1])==math.floor(skillPos[1]) and skillPos[3]>buttonToXYZ[3] then
					gStates.mageSkills[skillGUID][3]=gStates.mageSkills[skillGUID][3]-1.35
					getObjectFromGUID(skillGUID).unlock()
					getObjectFromGUID(skillGUID).setPositionSmooth(gStates.mageSkills[skillGUID])
					Wait.time(function() Wait.condition(function() getObjectFromGUID(skillGUID).lock() end, function() return getObjectFromGUID(skillGUID).resting end) end, 1)
				end
			end
			--Lock Reward claim check button

			--limit advanced action selection if another players skill chosen

			--deploy a dummy skill for next level up.
			if gStates.playersRef==5 then
				local exist=0
				local dummyPos=0
				for a=1, #turnOrder, 1 do
					if turnOrder[a].mage==gStates.positionMageKnight[5] then dummyPos=a break end
				end
				for skillGUID, skillPos in pairs(gStates.mageSkills) do
					if math.floor(skillPos[1])==math.floor((turnOrder[dummyPos].seatPos*3.7)+7.3) then exist=exist+1 end
				end
				local pos={(turnOrder[dummyPos].seatPos*3.7)+7.3, 2.00, -23.95+(exist*1.35)}
				local b={}
				if getObjectFromGUID("219c37")~=nil then--use "all Skills" bag if it exists
					b=getObjectFromGUID("219c37").takeObject({position=pos, rotation={0, 180, 0}})
					Wait.condition(function() b.lock() end, function() return b.resting end)
				else
					b=getObjectFromGUID(turnOrder[dummyPos].skillBagGUID).takeObject({position=pos, rotation={0, 180, 0}})
					Wait.condition(function() b.lock() end, function() return b.resting end)
				end
				gStates.mageSkills[b.guid]=pos
			end
			--turn off skill claim buttons
			local found=false
			for a=1, #turnOrder, 1 do
				if turnOrder[a].seatPos==gStates.skillButtons and turnOrder[a].levelUp>0 then levelUp(a) found=true end
			end
			if found==false then
				gStates.skillButtons=0
				Wait.frames(function()
					for skillGUID, x in pairs(gStates.mageSkills) do
						getObjectFromGUID(skillGUID).UI.setXmlTable({{}})
					end
				end, 5)
			end
		else
			if turnOrder[gStates.turnNumber].mage==gStates.positionMageKnight[5] then
				broadcastToAll("{en}Dummy doesn't claim skill!{ru}Виртуальный игрок не получает навыков!{zh-cn}虚拟玩家不会选技能{ko}가상 플레이어는 스킬을 얻지 않습니다!{es}¡Dummy no dice tener habilidad!{fr}Le mannequin ne réclame pas de compétence !{pt-br}Jog. Fictício não clama habilidades{de}Dummy beansprucht keine Fertigkeit!", {1,0,0})
			end
		end
	end
end

--Removes all claim buttons and re-activates only buttons with cards
function claimButtonRefresh()
	--Remove buttons if dummy is choosing
	getObjectFromGUID("483ed5").UI.setXmlTable({{}})
	if gStates.tacticShown==false or turnOrder[gStates.turnNumber].mage==gStates.positionMageKnight[5] then
		for zoneGUID, cardSource in pairs(tacticClaimingZones) do
			for _, obj in pairs(getObjectFromGUID(zoneGUID).getObjects()) do
				if obj.getName():sub(1,3)=="Day" or obj.getName():sub(1,3)=="Nig" then
					obj.UI.setXmlTable({{}})
				end
			end
		end
	end
	--Add buttons
	Wait.time(function()
		if gStates.tacticShown==true then
			--Tactic card claim buttons
			if turnOrder[gStates.turnNumber].mage==gStates.positionMageKnight[5] then
				getObjectFromGUID("483ed5").UI.setXmlTable({createClaimButton("483ed5", "tactic7")})
			else
				for zoneGUID, cardSource in pairs(tacticClaimingZones) do
					if getObjectFromGUID(zoneGUID).getObjects()~=nil then
						for _, obj in pairs(getObjectFromGUID(zoneGUID).getObjects()) do
							for a=1, 12, 1 do
								if obj.guid==tacticCard[a] then
									obj.UI.setXmlTable({createClaimButton(obj.guid, cardSource)})
									break
								end
							end
						end
					end
				end
			end
		end
		if gStates.tacticRemove==true then
			--Remove Tactic Claim Button
			if gStates.discardTactics==2 then
				getObjectFromGUID("483ed5").UI.setXmlTable({createClaimButton("483ed5", "removeTactic5")})
			else
				for zoneGUID, cardSource in pairs(tacticClaimingZones) do
					if cardSource:sub(1,6)=="tactic" then
						local cardSourceRemove="removeTactic"..cardSource:sub(7,8)
						local card=getObjectFromGUID(zoneGUID).getObjects()
						if #card>=1 then
							card[1].UI.setXmlTable({createClaimButton(card[1].guid, cardSourceRemove)})
						end
					end
				end
			end
		end
		if gStates.tacticRemove==false and gStates.tacticShown==false then
			--offer buttons
			for zoneGUID, cardSource in pairs(cardClaimingZones) do
				for _, card in pairs(getObjectFromGUID(zoneGUID).getObjects()) do
					if card.type=="Card" and gameCards[card.guid]~=nil then
						card.UI.setXmlTable({{}})
						if gStates.preEndTurn==false or (cardSource~="monastery" and gStates.preEndTurn==true) then
							card.UI.setXmlTable({createClaimButton(card.guid, cardSource)})
						end
					end
				end
			end
			--artifact buttons
			local count=0
			if gStates.dealtArtifacts~=nil then
				for guid, state in pairs(gStates.dealtArtifacts) do
					if state==true then
						count=count+1
						getObjectFromGUID(guid).UI.setXmlTable({createClaimButton(guid, "artifactReward")})
					end
				end
			end
			if count==0 then
				getObjectFromGUID("ac75c4").UI.setAttribute("ac75c4ArtifactDown", "active", "true")
				getObjectFromGUID("ac75c4").UI.setAttribute("ac75c4ArtifactOffer", "active", "true")
				getObjectFromGUID("ac75c4").UI.setAttribute("ac75c4ArtifactUp", "active", "true")
				getObjectFromGUID("ac75c4").UI.setAttribute("ac75c4ArtifactDownImage", "image", "Overkill Down")
				getObjectFromGUID("ac75c4").UI.setAttribute("ac75c4ArtifactOfferImage", "image", "Sliced Button/Button Object Active")
				getObjectFromGUID("ac75c4").UI.setAttribute("ac75c4ArtifactUpImage", "image", "Overkill Up")
			end
		end
	end, 0.3)
end

--Get's the dummy to pick a tactic card
function dummyTurn(player, mouseButton, id)
	if mouseButton=="-1" then
		if gStates.tacticShown==true then
			--pick a random tactic if they are displayed
			local dummyTactic=nil
			local claimedCard=nil
			math.randomseed(os.time())
			while dummyTactic==nil do
				dummyTactic=math.random(1,6)
				for _, obj in pairs(getObjectFromGUID(tacticZones[dummyTactic]).getObjects()) do
					if obj.getName():sub(1,3)=="Day" or obj.getName():sub(1,3)=="Nig" then claimedCard=obj break end
				end
				if claimedCard==nil then dummyTactic=nil end
			end
			broadcastToAll(joinLang({"{en}Dummy RANDOMLY gained Tactic for {ru}Виртуальный игрок получает СЛУЧАЙНУЮ Тактику для {zh-cn}虚拟玩家随机选取战术给{ko}가상 플레이어가 무작위의 전략 카드를 가져갑니다: {es}Dummy ganada ALEATORIAMENTE Táctica para {fr}Le mannequin a gagné au hasard une Tactique pour {pt-br}Jog. Fictício ALEATÓRIAMENTE ganhou a Tática por {de}Dummy hat ZUFÄLLIG eine Taktik für ", translateWord[turnOrder[gStates.turnNumber].mage]}), positionToColor(gStates.turnNumber))
			if claimedCard~=nil then
				claimedCard.unlock()
				claimedCard.setPositionSmooth({getObjectFromGUID(dummyBoard).getPosition()[1], 3.0, getObjectFromGUID(dummyBoard).getPosition()[3]-5.17})
			end
			turnOrder[gStates.turnNumber].tactic=dummyTactic
		end
		if gStates.tacticShown==false then
			--Draw Cards based on the crytal amount
			local cardDraw=3
			local volkareDrew={color="Blue", spell=2}--this will give Volkare a Frenzy result.
			gStates.volkareFrenzied=true
			local pass=1
			local dummyPos=nil
			function dummyDraw()
				local foundDeedDeck=nil
				local lastCard=nil
				for deck, search in pairs(getObjectFromGUID(deedDeckZones[dummyPos]).getObjects()) do
					if search.type=="Deck" or search.type=="Card" then foundDeedDeck=search break end
				end
				if foundDeedDeck~=nil then
					gStates.volkareFrenzied=false
					local destination=getObjectFromGUID(deedDeckDiscardZones[dummyPos]).getPosition()
					if foundDeedDeck.type=="Deck" then
						for dummyDraw=1, cardDraw, 1 do
							lastCard=foundDeedDeck.takeObject({position={destination[1], destination[2]+(dummyDraw*1.5)+((pass-1)*4.5), destination[3]}, rotation={0, 180, 0}})
						end
					else
						if cardDraw>0 then
							foundDeedDeck.setPositionSmooth({destination[1], destination[2]+1.5+((pass-1)*4.5), destination[3]})
							foundDeedDeck.setRotationSmooth({0, 180, 0})
							lastCard=foundDeedDeck
						end
					end
				end
				if pass==1 and lastCard~=nil then
					local cardColor=lastCard.getDescription()
					if cardColor=="Red Green" then cardDraw=turnOrder[gStates.turnNumber].dummyCrystals["Red"]+turnOrder[gStates.turnNumber].dummyCrystals["Green"] end
					if cardColor=="Green Blue" then cardDraw=turnOrder[gStates.turnNumber].dummyCrystals["Green"]+turnOrder[gStates.turnNumber].dummyCrystals["Blue"] end
					if cardColor=="Blue White" then cardDraw=turnOrder[gStates.turnNumber].dummyCrystals["Blue"]+turnOrder[gStates.turnNumber].dummyCrystals["White"] end
					if cardColor=="White Red" then cardDraw=turnOrder[gStates.turnNumber].dummyCrystals["Red"]+turnOrder[gStates.turnNumber].dummyCrystals["White"] end
					if cardColor=="Red" or cardColor=="Green" or cardColor=="Blue" or cardColor=="White" then
						if gStates.positionMageKnight[5]~="Volkare" then cardDraw=turnOrder[gStates.turnNumber].dummyCrystals[cardColor] else volkareDrew.color=cardColor end
					end
					if cardColor=="" then volkareDrew.color="Wound" end
					if lastCard.getName()~="Spell" then volkareDrew.spell=1 end
					return
				end
			end
			--draw cards for the standard dummy
			if gStates.positionMageKnight[5]~="Volkare" and gStates.endRoundCalled==false then
				--Count crystals in Inventory
				turnOrder[gStates.turnNumber].dummyCrystals["Red"]=0
				turnOrder[gStates.turnNumber].dummyCrystals["White"]=0
				turnOrder[gStates.turnNumber].dummyCrystals["Green"]=0
				turnOrder[gStates.turnNumber].dummyCrystals["Blue"]=0
				for a, b in pairs(getObjectFromGUID(playerCrystalAreas[turnOrder[gStates.turnNumber].seatPos]).getObjects()) do
					if b.getName()=="Red Mana" or b.getName()=="Blue Mana" or b.getName()=="Green Mana" or b.getName()=="White Mana" then
						turnOrder[gStates.turnNumber].dummyCrystals[b.getDescription()]=turnOrder[gStates.turnNumber].dummyCrystals[b.getDescription()]+1
					end
				end
				dummyPos=turnOrder[gStates.turnNumber].seatPos
				dummyDraw()
				Wait.time(function()
					pass=pass+1
					dummyDraw()
				end, 1.5)
			end
			--draw card for Volkare and process him
			if gStates.positionMageKnight[5]=="Volkare" and gStates.endRoundCalled==false and gStates.volkareState=="Start" then
				UI.setAttribute("VolkareAttackedFull", "interactable", "true")
				UI.setAttribute("VolkareAttackedFull", "onClick", "dummyTurn")
				UI.setAttribute("VolkareAttackedFullText", "text", "{en}Fully Attend the Battle{ru}Долгая подготовка к битве{zh-cn}完全参战{ko}전투 완전 참여{es}Participar en la Batalla por Completo{fr}Assistez pleinement à la bataille{pt-br}Participar Totalmente do Combate{de}Vollständig an der Schlacht teilnehmen")
				UI.setAttribute("VolkareAttackedFullImage", "image", "Sliced Button/Button New Active")
				UI.setAttribute("VolkareAttackedPartial", "interactable", "true")
				UI.setAttribute("VolkareAttackedPartial", "onClick", "volkarePartial")
				UI.setAttribute("VolkareAttackedPartialText", "text", "{en}Partially Attend the Battle{ru}Быстрая подготовка к битве{zh-cn}部分参战{ko}전투 부분 참여{es}Asiste Parcialmente a la Batalla{fr}Participez Partiellement à la Bataille{pt-br}Participe Parcialmente da Batalha{de}Teilweise an der Schlacht teilnehmen")
				UI.setAttribute("VolkareAttackedPartialImage", "image", "Sliced Button/Button New Active")
				UI.setAttribute("VolkareRetreat", "interactable", "true")
				UI.setAttribute("VolkareRetreat", "onClick", "volkareRetreat")
				UI.setAttribute("VolkareRetreatText", "text", "{en}Retreat from the Battle{ru}Отступить с поля битвы{zh-cn}退出战斗{ko}전투 후퇴{es}Retirarse de la Batalla{fr}Retraite de la bataille{pt-br}Recuar da Batalha{de}Rückzug von der Schlacht")
				UI.setAttribute("VolkareRetreatImage", "image", "Sliced Button/Button New Active")

				gStates.blurb=""
				if getObjectFromGUID("09a991").is_face_down==false then
					--draw a card if one exists
					dummyPos=turnOrder[gStates.turnNumber].seatPos
					cardDraw=1
					dummyDraw()
					--wound card will roll and remove unit
					if volkareDrew.color=="Wound" then
						gStates.blurb="{en}Volkare rests this turn{ru}Волкар отдыхает в этот ход{zh-cn}沃里卡这回合休息{ko}볼케어는 이번 차례에 휴식{es}Volkare descansa este turno{fr}Volkare se repose ce tour{pt-br}Volkare descansa esse turno{de}Volkare ruht diese Runde"
						--roll volkares dice and read result
						gStates.volkareState="Resting"
						local volkareDice=getObjectFromGUID("9a686a")
						volkareDice.randomize()
						Wait.condition(function()
							if gStates.volkareUnitCrystals[volkareDice.getRotationValue()]~=nil and getObjectFromGUID(gStates.volkareUnitCrystals[volkareDice.getRotationValue()]).getObjects()[1]~=nil then
								local unitCard=getObjectFromGUID(gStates.volkareUnitCrystals[volkareDice.getRotationValue()]).getObjects()[1]
								unitCard.destruct()
								--add a gray unit to Volkare's Army
								if gStates.gameScenario~="Volkare's Quest" then
