									end
								end
								--Update dungeon lords hex details if a reminder token dropped.
								if found==false and status=="enter" then
									if (hexFeature=="" or ((hexFeature=="draconum" or hexFeature=="rampaging") and gStates.rampage~=true))
										and terrainTiles[terTile.guid].hexType[tostring(bearing)]~="swamp"
