		else
			UI.setAttribute("Mage"..entry.."VolkareCellOne", "active", "true")
			UI.setAttribute("Mage"..entry.."VolkareCellTwo", "active", "true")
			UI.setAttribute("Mage"..entry.."AssaulterOpponentType", "text", "{en}Regular and{ru}Обычные и{zh-cn}常规和{ko}일반 및{es}Regular y{fr}Régulier et{pt-br}Regular e{de}Reguläre und")
			UI.setAttribute("Mage"..entry.."AssaulterOpponentType", "alignment", "MiddleCenter")
			UI.setAttribute("Mage"..entry.."AssaulterOpponentTypeTwo", "text", "{en}Elite Units{ru}Элитные отряды{zh-cn}精英部队{ko}엘리트 유닛{es}Unidades de Elite{fr}Unités d'élite{pt-br}Unidades Elites{de}Elite-Einheiten")
			if #assignedMonsters.primary==0 and #assignedMonsters.secondary==0 then
				UI.setAttribute("Mage"..entry.."AssaulterOpponentType", "text", "")
				UI.setAttribute("Mage"..entry.."AssaulterOpponentTypeTwo", "text", notParticipating)
			end
		end

		if #assignedMonsters.primary>=1 or #assignedMonsters.secondary>=1 then UI.setAttribute("Mage"..entry.."AssaulterMageName", "text", joinLang({translateWord[mage], "{en} fights{ru} сражается с{zh-cn} 打架{ko} 전투:{es} peleas{fr} combats{pt-br} lutas{de} kämpft"})) else UI.setAttribute("Mage"..entry.."AssaulterMageName", "text", translateWord[mage]) end
		if #assignedMonsters.primary>=1 then UI.setAttribute("Mage"..entry.."AssaulterAmountOne", "text", tostring(#assignedMonsters.primary)) else UI.setAttribute("Mage"..entry.."AssaulterAmountOne", "text", "") end
		if #assignedMonsters.primary==0 and #assignedMonsters.secondary>=1 then UI.setAttribute("Mage"..entry.."AssaulterAmountOne", "text", "no") end
		if #assignedMonsters.primary>=1 and entry~=1 then
			UI.setAttribute("Mage"..entry.."AssaultAdjustPrimDo", "interactable", "true")
