		else
			UI.setAttribute("Mage"..entry.."AssaultAdjustPrimDo", "interactable", "False")
			UI.setAttribute("Mage"..entry.."AssaultAdjustPrimDoImage", "image", "Sliced Button/Button New Deactive")
		end
		if ((#gStates.assaultData[leadMage].primary>=2 and size=="half") or (#gStates.assaultData[leadMage].primary>=1 and size=="full")) and entry~=1 then
			UI.setAttribute("Mage"..entry.."AssaultAdjustPrimUp", "interactable", "true")
			UI.setAttribute("Mage"..entry.."AssaultAdjustPrimUpImage", "image", "Sliced Button/Button New Active")
		else
			UI.setAttribute("Mage"..entry.."AssaultAdjustPrimUp", "interactable", "False")
			UI.setAttribute("Mage"..entry.."AssaultAdjustPrimUpImage", "image", "Sliced Button/Button New Deactive")
		end
		if #assignedMonsters.secondary>=1 then UI.setAttribute("Mage"..entry.."AssaulterAmountTwo", "text", tostring(#assignedMonsters.secondary)) else UI.setAttribute("Mage"..entry.."AssaulterAmountTwo", "text", "") end
		if #assignedMonsters.primary>=1 and #assignedMonsters.secondary==0 then UI.setAttribute("Mage"..entry.."AssaulterAmountTwo", "text", "no") end
		if #assignedMonsters.secondary>=1 and entry~=1 then
			UI.setAttribute("Mage"..entry.."AssaultAdjustSecoDo", "interactable", "true")
			UI.setAttribute("Mage"..entry.."AssaultAdjustSecoDoImage", "image", "Sliced Button/Button New Active")
		else
			UI.setAttribute("Mage"..entry.."AssaultAdjustSecoDo", "interactable", "False")
			UI.setAttribute("Mage"..entry.."AssaultAdjustSecoDoImage", "image", "Sliced Button/Button New Deactive")
		end
		if #gStates.assaultData[leadMage].secondary>=1 and entry~=1 then
			UI.setAttribute("Mage"..entry.."AssaultAdjustSecoUp", "interactable", "true")
			UI.setAttribute("Mage"..entry.."AssaultAdjustSecoUpImage", "image", "Sliced Button/Button New Active")
		else
			UI.setAttribute("Mage"..entry.."AssaultAdjustSecoUp", "interactable", "False")
			UI.setAttribute("Mage"..entry.."AssaultAdjustSecoUpImage", "image", "Sliced Button/Button New Deactive")
		end
		if size=="full" then UI.setAttribute("Mage"..entry.."AssaultAdjustSecoUp", "active", "true") UI.setAttribute("Mage"..entry.."AssaultAdjustSecoDo", "active", "true") else UI.setAttribute("Mage"..entry.."AssaultAdjustSecoUp", "active", "False") UI.setAttribute("Mage"..entry.."AssaultAdjustSecoDo", "active", "False") end
	end
	--complete 5 column volkare assault.
	UI.setAttribute("CoopAssault", "width", "525")
	UI.setAttribute("CoopAssault", "height", tostring(((entry+1)*30)+90))
	UI.setAttribute("CoopAssaultMainTableHeading", "columnSpan", "5")
	UI.setAttribute("CoopAssaultMainTableHeading", "preferredHeight", "90")
	UI.setAttribute("CoopAssaultMainTable", "columnWidths", "135 85 100 85 120")
	if size=="half" then
		UI.setAttribute("CoopAssault", "width", "340")
		UI.setAttribute("CoopAssault", "height", tostring(((entry+1)*30)+95))
		UI.setAttribute("CoopAssaultMainTableHeading", "columnSpan", "3")
		UI.setAttribute("CoopAssaultMainTableHeading", "preferredHeight", "95")
		UI.setAttribute("CoopAssaultMainTable", "columnWidths", "135 85 120 85 120")
	end
	UI.show("CoopAssault")
end

function assaultAdjust(player, mouseButton, id)
	if mouseButton=="-1" then
		local UIPos=id:sub(5,5)
		local army="primary"
		if id:sub(19,22)=="Seco" then army="secondary" end
		local action=id:sub(23, 24)--Up, Do=Down
		local leadMage=turnOrder[gStates.turnNumber].mage
		for mage, assignedMonsters in pairs (gStates.assaultData) do
			if leadMage==gStates.positionMageKnight[5] and assignedMonsters.UIPos[1]==1 then leadMage=mage end
				if assignedMonsters.UIPos[1]==tonumber(id:sub(5,5)) then
				if id:sub(23, 24)=="Up" then
					local found=false
					local randMon=nil
					while found==false do
						found=true
						randMon=math.random(1, #gStates.assaultData[leadMage][army])
						if gStates.assaultData[leadMage][army][randMon]==elementalist.token or gStates.assaultData[leadMage][army][randMon]==darkCrusader.token then found=false end
					end
					assignedMonsters[army][#assignedMonsters[army]+1]=gStates.assaultData[leadMage][army][randMon]
					table.remove(gStates.assaultData[leadMage][army], randMon)
				else
					local randMon=math.random(1, #assignedMonsters[army])
					gStates.assaultData[leadMage][army][#gStates.assaultData[leadMage][army]+1]=assignedMonsters[army][randMon]
					table.remove(assignedMonsters[army], randMon)
				end
			end
		end
		coopAssaultUIUpdate()
	end
end

--summun monsters to the left of a summoner.
function summonMonster(player, mouseButton, id)
	if mouseButton=="-1" then
		--draw tokens to the left of summoners token
		broadcastToAll("{en}Monster Summoned some support{ru}Враг призвал подмогу{zh-cn}怪物叫了些同谋{ko}몬스터가 소환되었습니다{es}Monster convocó algo de apoyo{fr}Monstre a invoqué du soutien{pt-br}Monstro Invocou algum suporte.{de}Monster beschwört etwas Unterstützung", positionToColor(gStates.turnNumber))
		local location=getObjectFromGUID(id).getPosition()
		local search=monsterPugs[id].monsters
		local tokenWait=0
		for order, monsterColor in pairs(search) do
			Wait.frames(function() tokenRefill() end, tokenWait+1)
			Wait.frames(function()
				local MCol=monsterColor
				if (id=="565ecd" or id==darkCrusader.token) and getObjectFromGUID(monsterPiles[monsterColor.."Dark"])~=nil and getObjectFromGUID(monsterPiles[monsterColor.."Dark"]).getQuantity()>0 then MCol=monsterColor.."Dark" end
				if getObjectFromGUID(monsterPiles[MCol]).getQuantity()>0 then
					local summonedMonster=getObjectFromGUID(monsterPiles[MCol]).takeObject({position={location[1]-(2*order), 2.5, location[3]}, rotation={0.00, 180.00, 0.00}})
					if id==darkCrusader.token or (id=="565ecd" and turnOrder[gStates.turnNumber].avatarLocation=="graveyard") then summonedMonster.addDecal({name="NightRules", position={0.85, 0.15, -0.85}, rotation={90, 180, 0}, scale={0.6, 0.6, 1}, url=nightRulesDecal}) end
					gStates.summonStates[summonedMonster.guid]="summoned"
					if gStates.monsterPerks[summonedMonster.guid]==nil then gStates.monsterPerks[summonedMonster.guid]={nightRules=true} else gStates.monsterPerks[summonedMonster.guid].nightRules=true end
					cityBonusDecals(getObjectFromGUID(id), summonedMonster)
				else
					broadcastToAll("{en}Sorry, there are no tokens left to deploy{zh-cn}抱歉，没有token可供部署{ko}여분의 토큰이 없습니다{es}Lo sentimos, no quedan tokens para implementar{fr}Désolé, il n'y a plus de jetons à déployer{pt-br}Desculpe, Não tem Fichas sobrando para distribuir", {1,0,0})
				end
			end, tokenWait+5)
			tokenWait=tokenWait+5
		end
		--turn off button
		if id==darkCrusader.token then
			getObjectFromGUID(id).UI.setXmlTable({
				{tag="Button", attributes={id=id.."OverkillUp", onMouseDown="global/ButtonClickDownOverkill", onMouseUp="global/ButtonClickUpOverkill",	onClick="global/adjustOverkill", height=50/0.9, width=50/0.9,
					color="rgba(0,0,0,0.0)", position="-62 "..tostring(-120/0.9).." "..tostring(-15/0.9), rotation="0 0 180"},
					children={{tag="Image", attributes={id=id.."OverkillUpImage", image="Overkill Up"}}}},
				{tag="Image", attributes={image="Overkill Text", height=50/0.9, width=55/0.9, position="0 "..tostring(-120/0.9).." "..tostring(-15/0.9), rotation="0 0 180"},
					children={{tag="Text", attributes={id=id.."Overkill",	color="rgb(0,0,0)", fontSize="45", fontStyle="Bold", alignment="MiddleCenter", text=gStates.leaderOverkill}}}},
				{tag="Button", attributes={id=id.."OverkillDown", onMouseDown="global/ButtonClickDown", onMouseUp="global/ButtonClickUp", onClick="global/adjustOverkill", height=50/0.9, width=50/0.9,
					color="rgba(0,0,0,0.0)", position="62 "..tostring(-120/0.9).." "..tostring(-15/0.9), rotation="0 0 180"},
					children={{tag="Image", attributes={id=id.."OverkillDownImage", image="Overkill Down"}}}}})
		else
			gStates.summonStates[id]="SummonDone"
			getObjectFromGUID(id).UI.setXmlTable({{}})
		end
	end
end

--Leader overkill adjust
function adjustOverkill(player, mouseButton, id)
	if mouseButton=="-1" then
		local level=gStates.elementalistLevel-gStates.leaderReduction
		if id:sub(1,6)==darkCrusader.token then level=gStates.darkCrusaderLevel-gStates.leaderReduction end
		if id:sub(7,16)=="OverkillUp" and gStates.leaderOverkill<level then
			gStates.leaderOverkill=gStates.leaderOverkill+1
		end
		if id:sub(7,18)=="OverkillDown" and gStates.leaderOverkill>1 then
			gStates.leaderOverkill=gStates.leaderOverkill-1
		end
		getObjectFromGUID(id:sub(1,6)).UI.setAttribute(id:sub(1,14), "Text", gStates.leaderOverkill)
		mainUIUpdate("Leader Overkilled")
	end
end

--Moves all rampaging tokens when Pursuit Variant Used
function pursuingRampagers(player, mouseButton, id)
	if mouseButton=="-1" then
		gStates.pursuitTwoOption=false
		--loop through all recorded pursuing monsters
		if gStates.pursuingMonsters[turnOrder[gStates.turnNumber].mage]~=nil and gStates.tacticShown==false then
			--delete the help arrows
			for guid, _ in pairs(gStates.arrowDelete) do
				if getObjectFromGUID(guid)~=nil then getObjectFromGUID(guid).destruct() end
			end
			gStates.arrowDelete={}
			local height=0.2
			local playerBoardDisplace=0
			for monsterGUID, monsterDetails in pairs(gStates.pursuingMonsters[turnOrder[gStates.turnNumber].mage]) do
				if monsterDetails.state=="Pursuing" then
					--find initial vector to move closer to the player
					local playerPos={}
					local playerRealPos=playerPos
					for b, details in pairs(mageKnights) do
						if details.mage==turnOrder[gStates.turnNumber].mage then
							if getObjectFromGUID(details.model)~=nil then playerPos=getObjectFromGUID(details.model).getPosition() end
							if getObjectFromGUID(details.token)~=nil then playerPos=getObjectFromGUID(details.token).getPosition() end
							if getObjectFromGUID(details.standee)~=nil then playerPos=getObjectFromGUID(details.standee).getPosition() end
						end
					end
					playerRealPos={playerPos[1], playerPos[2], playerPos[3]}
					if turnOrder[gStates.turnNumber].avatarLocation:sub(1, 4)=="city" or turnOrder[gStates.turnNumber].avatarLocation=="Volkare's Camp" then
						--figure out which city avatar is in
						for zone, citySearch in pairs(cityScriptZones) do
							for obj, detail in pairs(getObjectFromGUID(zone).getObjects()) do
								if detail.getName()==turnOrder[gStates.turnNumber].mage then
									playerPos=getObjectFromGUID(citySearch.cityGUID).getPosition()
									break
								end
							end
						end
					end
					local realBearing=(math.floor((math.deg(math.atan2(monsterDetails.location[3]-playerPos[3], monsterDetails.location[1]-playerPos[1]))/2)+0.5)*2)+2
					local playerBearing=math.floor((realBearing/60)+0.5)*60
					local inline=false
					if realBearing>=360 then playerBearing=playerBearing-360 realBearing=realBearing-360 end
					if realBearing<0 then playerBearing=playerBearing+360 realBearing=realBearing+360 end
					if realBearing<playerBearing+10 and realBearing>playerBearing-10 then inline=true end
					local clockwise=1
					if realBearing<playerBearing then clockwise=-1 end
					local canAttack=false
					local protection="none"
					local rampageNewPos={}
					function hexCheck()
						local objectsInPlay=getObjectFromGUID(mapArea).getObjects()
						local terrainFound=false
						for _, terTile in pairs(objectsInPlay) do
							local tilePos=terTile.getPosition()
							--make sure there is a terain tile
							if terrainTiles[terTile.guid]~=nil then
								local tileToObjDist=math.sqrt(((rampageNewPos[1]-tilePos[1])^2)+((rampageNewPos[3]-tilePos[3])^2))
								if tileToObjDist<3.1 then
									--make sure the hex isn't a fortified site
									local hexBearing="center"
									if tileToObjDist>1 then
										local temp=math.floor(((math.deg(math.atan2(tilePos[3]-rampageNewPos[3], tilePos[1]-rampageNewPos[1])))/60)+0.5)*60
										temp=temp+(math.floor(((terTile.getRotation()[2]-180)/60)+0.5)*60)--compensate for terrain tile rotation
										if temp>=360 then temp=temp-360 end
										if temp<0 then temp=temp+360 end
										hexBearing=tostring(temp)
									end
									if terrainTiles[terTile.guid].hexFeature[hexBearing]~="keep" and
										terrainTiles[terTile.guid].hexFeature[hexBearing]~="mage tower" and
										terrainTiles[terTile.guid].hexFeature[hexBearing]:sub(1, 4)~="city" then
										terrainFound=true
										if terrainTiles[terTile.guid].hexFeature[hexBearing]=="village" or
											terrainTiles[terTile.guid].hexFeature[hexBearing]=="camp" or
											terrainTiles[terTile.guid].hexFeature[hexBearing]=="monastery" and gStates.monasteryBurned[terTile.guid]~=true then
											protection="Interaction"
										end
										if terrainTiles[terTile.guid].wallList~=nil and terrainTiles[terTile.guid].wallList[hexBearing]~=nil then
										local tileToObjStartDist=math.sqrt(((monsterDetails.location[1]-tilePos[1])^2)+((monsterDetails.location[3]-tilePos[3])^2))
											if tileToObjStartDist<3.1 then
												local hexOroginBearing="center"
												if tileToObjStartDist>1 then
													local temp=math.floor(((math.deg(math.atan2(tilePos[3]-monsterDetails.location[3], tilePos[1]-monsterDetails.location[1])))/60)+0.5)*60
													temp=temp+(math.floor(((terTile.getRotation()[2]-180)/60)+0.5)*60)
													if temp>=360 then temp=temp-360 end
													if temp<0 then temp=temp+360 end
													hexOroginBearing=tostring(temp)
												end
												if terrainTiles[terTile.guid].wallList[hexBearing][hexOroginBearing]~=nil then
													protection="Wall"
												end
											end
										end
									else
										protection="Fortified"
										if terrainTiles[terTile.guid].hexFeature[tostring(hexBearing)]:sub(1, 4)=="city" then
											local cityZone={[cityModel.blue]="8a7266", [cityModel.red]="648da8", [cityModel.green]="213d78", [cityModel.white]="d2d65e"}
											for _, obj in pairs(objectsInPlay) do
												if cityZone[obj.guid]~=nil then
													local found=false
													for _, obj2 in pairs(getObjectFromGUID(cityZone[obj.guid]).getObjects()) do
														if obj2.getName()==turnOrder[gStates.turnNumber].mage then
															if math.sqrt(((rampageNewPos[1]-obj.getPosition()[1])^2)+((rampageNewPos[3]-obj.getPosition()[3])^2))<1 then
																cityBeatCheck()
																protection="City"
																if turnOrder[gStates.turnNumber].defeatedCities[obj.guid]==nil and gStates.cityLevels[#gStates.cityLevels]~=0 then canAttack=true end
																found=true
																break
															end
														end
													end
													if found==true then break end
												end
											end
										end
									end
									break
								end
							end
						end
						local avatarToRampageDist=math.sqrt(((rampageNewPos[1]-playerPos[1])^2)+((rampageNewPos[3]-playerPos[3])^2))
						if terrainFound==true then
							--make sure there isnt an other player
							local magefound=false
							local test={Arythea=1, Braevalar=1, Goldyx=1, Krang=1, Norowas=1, Tovak=1, Wolfhawk=1, Ymirgh=1, Novak=1, Duscenia=1, Jormund=1, Volkare=1}
							for _, obj in pairs(objectsInPlay) do
								if obj.getName()~=turnOrder[gStates.turnNumber].mage and test[obj.getName()]==1 then
									if math.sqrt(((rampageNewPos[1]-obj.getPosition()[1])^2)+((rampageNewPos[3]-obj.getPosition()[3])^2))<1 then
										magefound=true
										break
									end
								end
							end
							if magefound==false then
								--see if it moves on to player boards
								if avatarToRampageDist<0.5 and protection=="none" then canAttack=true end
								return "Good"
							end
						end
						if terrainFound==false and protection~="none" and avatarToRampageDist<0.5 then
							--need to check if the site has a shield or not to determin if he attacks or stays
							local shieldfound=false
							for _, obj in pairs(objectsInPlay) do
								if obj.getName()=="Shield" and obj.getDescription()==turnOrder[gStates.turnNumber].mage then
									if math.sqrt(((rampageNewPos[1]-obj.getPosition()[1])^2)+((rampageNewPos[3]-obj.getPosition()[3])^2))<1 then
										shieldfound=true
										break
									end
								end
							end
							if shieldfound==false and protection~="City" then canAttack=true end
							return "Good"
						end
						return "Bad"
					end

					--check he won't move out of bounds and alter his course
					local hexIncrement={60, -120, 180, -240, 300}
					local hexFound=false
					local count=0
					while hexFound==false do
						rampageNewPos={monsterDetails.location[1]-(2.39*math.cos(math.rad(playerBearing))), monsterDetails.location[2], monsterDetails.location[3]-(2.39*math.sin(math.rad(playerBearing)))}
						if hexCheck()=="Bad" and count<5 then
							count=count+1
							playerBearing=playerBearing+(hexIncrement[count]*clockwise)
						else
							hexFound=true
						end
					end

					--check for scondary option
					local otherBearing=math.floor((math.deg(math.atan2(monsterDetails.location[3]-playerPos[3], monsterDetails.location[1]-playerPos[1]))/2)+0.5)*2
					if otherBearing>=360 then otherBearing=otherBearing-360 end
					if otherBearing<0 then otherBearing=otherBearing+360 end
					local twoOptions=1
					if (inline==true and count>0 and count<4) or (inline==false and (count==0 or count==2)) then
						if inline==false and count==0 then otherBearing=playerBearing+(hexIncrement[count+1]*clockwise) end
						if inline==false and count==2 and (clockwise==1 or (otherBearing~=30 and otherBearing~=90 and otherBearing~=150 and otherBearing~=210 and otherBearing~=270 and otherBearing~=330)) then
							otherBearing=playerBearing+(hexIncrement[count-1]*clockwise) end
						if inline==false and count==2 and clockwise==-1 and (otherBearing==30 or otherBearing==90 or otherBearing==150 or otherBearing==210 or otherBearing==270 or otherBearing==330) then
							otherBearing=playerBearing+(hexIncrement[count+1]*clockwise) end
						if inline==true and (count==1 or count==3) then otherBearing=playerBearing+(hexIncrement[count+1]*clockwise) end
						if otherBearing>=360 then otherBearing=otherBearing-360 end
						if otherBearing<0 then otherBearing=otherBearing+360 end
						rampageNewPos={monsterDetails.location[1]-(2.39*math.cos(math.rad(otherBearing))), monsterDetails.location[2], monsterDetails.location[3]-(2.39*math.sin(math.rad(otherBearing)))}
						if hexCheck()=="Good" then
							twoOptions=2
							gStates.pursuitTwoOption=true
						end
					end

					--move rampage monster one hex in a closer direction
					local noMove=false
					local rampageNewPos={monsterDetails.location[1]-(2.39*math.cos(math.rad(playerBearing))), monsterDetails.location[2]+height, monsterDetails.location[3]-(2.39*math.sin(math.rad(playerBearing)))}
					if math.sqrt(((turnOrder[gStates.turnNumber].turnStartLoc.x-playerRealPos[1])^2)+((turnOrder[gStates.turnNumber].turnStartLoc.z-playerRealPos[3])^2))<2 and id==nil then
						rampageNewPos=monsterDetails.location
						noMove=true
						gStates.pursuitTwoOption=false
					else
						if id~=nil then gStates.skippedMove=true else gStates.skippedMove=false end
						if math.sqrt(((rampageNewPos[1]-playerPos[1])^2)+((rampageNewPos[3]-playerPos[3])^2))<0.5 or count>3 then
							rampageNewPos=monsterDetails.location
							noMove=true
							if count<4 and canAttack==false then
								if protection=="Interaction" or protection=="City" then broadcastToAll(joinLang({translateWord[turnOrder[gStates.turnNumber].mage], "{en} avoids pursuit at an Interaction site.{ru} избегает преследования в месте взаимодействия.{zh-cn}避免在有交涉的板块追击{ko}: 교류 장소에선 추적을 회피합니다.{es} evita la persecución en un sitio de Interacción.{fr} évite les poursuites sur un site d'Interaction.{pt-br} Evita perseguir em um lugar de interação.{de} vermeidet die Verfolgung an einem Interaktionsort."}), positionToColor(gStates.turnNumber)) end
								if protection=="Wall" then broadcastToAll(joinLang({translateWord[turnOrder[gStates.turnNumber].mage], "{en} avoids pursuit behind the wall.{ru} избегает преследования, находясь за стеной.{zh-cn}避免在有城墙的板块追击{ko}: 벽 뒤에선 추적을 회피합니다.{es} evita la persecución detrás de la pared.{fr} évite les poursuites derrière le mur.{pt-br} Evita perseguir atrás de um Muro.{de} vermeidet die Verfolgung hinter einer Mauer."}), positionToColor(gStates.turnNumber)) end
								if protection=="Fortified" then broadcastToAll(joinLang({translateWord[turnOrder[gStates.turnNumber].mage], "{en} avoids pursuit at a Fortified site.{ru} избегает преследования в укрепленном месте.{zh-cn}避免在有城防的板块追击{ko}: 요새화된 장소에선 추적을 회피합니다.{es} evita la persecución en un sitio Fortificado.{fr} évite les poursuites sur un site Fortifié.{pt-br} Evita perseguir em um local Fortificado.{de} vermeidet die Verfolgung an einem befestigten Ort."}), positionToColor(gStates.turnNumber)) end
							end
						end
						if canAttack==true then
							rampageNewPos={(turnOrder[gStates.turnNumber].seatPos*40)-98+playerBoardDisplace, 2.5, -39}
							playerBoardDisplace=playerBoardDisplace+2
							noMove=false
							 gStates.monsterPlayLocation[monsterGUID]=monsterDetails.location
							getObjectFromGUID(monsterGUID).UI.setXmlTable({{}})
							broadcastToAll(joinLang({"{en}Pursuing Monster Attacked {ru}Преследующие враги напали на {zh-cn}被追击怪物所攻击{ko}추적 중인 몬스터의 공격: {es}Persecución de Monstruos Atacados por {fr}Poursuivant le Monstre Attaqué {pt-br}Monstro Perseguidor Atacado {de}Verfolgtes Monster angegriffen ", translateWord[turnOrder[gStates.turnNumber].mage]}), positionToColor(gStates.turnNumber))
						end
					end
					getObjectFromGUID(monsterGUID).setPositionSmooth(rampageNewPos)

					if canAttack==false then gStates.monsterPlayLocation[monsterGUID]=rampageNewPos end
					height=height+0.2

					--Add an arrow to help find which tokens moved
					if noMove==false then
						for i=1, twoOptions, 1 do
							local arrow=getObjectFromGUID("6647eb").clone({position={monsterDetails.location[1]-(1.1*math.cos(math.rad(playerBearing))), 1.11, monsterDetails.location[3]-(1.1*math.sin(math.rad(playerBearing)))}})
							local convert={[0]=270, [30]=240, [60]=210, [90]=180, [120]=150, [150]=120, [180]=90, [210]=60, [240]=30, [270]=0, [300]=330, [330]=300, [360]=270}
							if playerBearing>=360 then playerBearing=playerBearing-360 end
							if playerBearing<0 then playerBearing=playerBearing+360 end
							arrow.setRotation({90.00, convert[playerBearing], 0.00})
							arrow.setColorTint("Orange")
							Wait.frames(function()
								arrow.lock()
								gStates.arrowDelete[arrow.guid]="Del"
							end, 50)
							playerBearing=otherBearing
						end
					end
					mainUIUpdate("pursuit")
				end
			end
			Wait.frames(function() addAvatarButtons() end, 60)
		end
	end
end

--Adjust the offer size
local OfferPause=false
function offerAdjust(player, mouseButton, id)
	if mouseButton=="-1" and OfferPause==false then
		OfferPause=true
		--update Offer size expected.
		if id=="e4372aOfferUp" then gStates.offerSize=gStates.offerSize+1 else gStates.offerSize=gStates.offerSize-1 end
		--move both decks and their detecting Zones, drop the decks onto existing cards.
		getObjectFromGUID("e4372a").setPositionSmooth({(4.8*(gStates.offerSize+1))+21.6, 2.5, -22.2})
		getObjectFromGUID("e926ba").setPositionSmooth({(4.8*(gStates.offerSize+1))+21.6, 2.5, -16.2})
		getObjectFromGUID("f752bb").setPosition({(4.8*(gStates.offerSize+1))+21.6, 2.05, -22.2})
		getObjectFromGUID("7ce69e").setPosition({(4.8*(gStates.offerSize+1))+21.6, 2.05, -16.2})
		--change size of offer Zone
		getObjectFromGUID("45cc44").setScale({4.8*gStates.offerSize, 0.3, 9.57})
		getObjectFromGUID("45cc44").setPosition({(2.4*(gStates.offerSize-1))+26.4, 1.13, -19.2})
		if id=="e4372aOfferUp" then
			--run fill slide after a wait frame.
			fillSlide()
			--Wait.condition(function() fillSlide() end, function() return getObjectFromGUID("e4372a").resting end)
		else
			--flip existing cards if shrinking the offer.
			for _, card in pairs(getObjectFromGUID("45cc44").getObjects()) do
				if math.floor(((card.getPosition()[1]-21.6)/4.8)+0.5)==gStates.offerSize+1 and card.type=="Card" then card.unlock() card.setRotation({0.00, 180.00, 180.00}) end
			end
		end
		Wait.frames(function()
			OfferPause=false
			getObjectFromGUID("e4372a").UI.setXmlTable({	{tag="Button", attributes={id="e4372aOfferUp", onClick="global/offerAdjust", onMouseDown="global/ButtonClickDown", onMouseUp="global/ButtonClickUp", height=150, width=240, position="60 190 -10", rotation="0 180 180", scale="0.32 0.32"},
															children={	{tag="Image", attributes={id="e4372aOfferUpImage", image="Sliced Button/Button Object Active", type="Sliced"}},
																		{tag="Text", attributes={fontSize="90", fontStyle="Normal", alignment="MiddleCenter", text=">"}}}},
															{tag="Button", attributes={id="e4372aOfferDown", onClick="global/offerAdjust", onMouseDown="global/ButtonClickDown", onMouseUp="global/ButtonClickUp", height=150, width=240, position="-60 190 -10", rotation="0 180 180", scale="0.32 0.32"},
															children={	{tag="Image", attributes={id="e4372aOfferDownImage", image="Sliced Button/Button Object Active", type="Sliced"}},
																		{tag="Text", attributes={fontSize="90", fontStyle="Normal", alignment="MiddleCenter", text="<"}}}}})
		end, 60)
	end
end

--Add a row of buttons to allow changing of hand color
function applyColorBarButtons()
	for position, barGUID in pairs(colorBand) do
		local buttons={{tag="Button", attributes={id=barGUID.."changeMatDown",
			onClick="global/changeMatImage", onMouseDown="global/ButtonClickDownOverkill", onMouseUp="global/ButtonClickUpOverkill",
			height=29, width=3, color="rgba(0,0,0,0.0)",
			position="-90 30 -40", rotation="0 0 180"},
				children={{tag="Image", attributes={id=barGUID.."changeMatDownImage", image="Overkill Down"}}}},
			{tag="Button", attributes={id=barGUID.."changeMatUp",
			onClick="global/changeMatImage", onMouseDown="global/ButtonClickDownOverkill", onMouseUp="global/ButtonClickUpOverkill",
			height=29, width=3, color="rgba(0,0,0,0.0)",
			position="-95 30 -40", rotation="0 0 180"},
				children={	{tag="Image", attributes={id=barGUID.."changeMatUpImage", image="Overkill Up"}}}}}
		if getObjectFromGUID(barGUID)~=nil then
			local barSkip=false
			for _, playerData in pairs(turnOrder) do
				if playerData.mage==gStates.positionMageKnight[5] and playerData.seatPos==position then barSkip=true end
			end
			local handColorList={"White", "Brown", "Red", "Orange", "Yellow", "Green", "Teal", "Blue", "Purple", "Pink"}
			local loopCount=1
			for _, handColor in pairs(handColorList) do
				local available=true
				for _, playerData in pairs(turnOrder) do
					for _, seat in pairs(Player.getAvailableColors()) do
						if playerData.mage~=gStates.positionMageKnight[5] and math.ceil((Player[seat].getHandTransform().position[1]+97.59)/40)==playerData.seatPos and seat==handColor then available=false break end
					end
				end
				if available==true then
					buttons[#buttons+1]={tag="Button", attributes={id=barGUID..handColor,
						onClick="global/changePositionColor",
						height=25, width=3,
						position=tostring(102-(loopCount*5)).." 30 -40", rotation="0 0 180",
						color=handColor}}
					loopCount=loopCount+1
				end
			end
			if barSkip==false then getObjectFromGUID(barGUID).UI.setXmlTable(buttons) end
		end
	end
end

--Change a hand's color and refresh.
function changePositionColor(player, mouseButton, id)
	local barConversion={[colorBand[1]]=1, [colorBand[2]]=2, [colorBand[3]]=3, [colorBand[4]]=4}
	local barGUID=id:sub(1,6)
	local newColor=id:sub(7, string.len(id))
	local currentColor=Hands.getHands()[barConversion[barGUID]].getValue()
	if mouseButton=="-1" and legalPlayerCheck(player.color, gStates.handColors[currentColor], "NoDummyException")==true then
		--swap an existing unused color to stop two hands having the same colour
		if gStates.handColors[newColor]~=nil then
			for _, freeHandColor in pairs(Player.getColors()) do
				if gStates.handColors[freeHandColor]==nil then
					Hands.getHands()[gStates.handColors[newColor]].setValue(freeHandColor)
					gStates.handColors[freeHandColor]=gStates.handColors[newColor]
					gStates.handColors[newColor]=nil
					break
				end
			end
		end
		--change hand colour
		gStates.handColors[newColor]=gStates.handColors[currentColor]
		gStates.handColors[currentColor]=nil
		Hands.getHands()[barConversion[barGUID]].setValue(newColor)
		Player[currentColor].changeColor(newColor)
		applyColorBarButtons()
		mainUIUpdate("Player Changed Colour")
		Wait.frames(function() Player[newColor].lookAt({position={getObjectFromGUID(barGUID).getPosition()[1], getObjectFromGUID(barGUID).getPosition()[2], getObjectFromGUID(barGUID).getPosition()[3]-10}, pitch=75, yaw=0, distance=30}) end, 2)
	end
end

function changeMatImage(player, mouseButton, id)
	local barConversion={[colorBand[1]]=1, [colorBand[2]]=2, [colorBand[3]]=3, [colorBand[4]]=4}
	if mouseButton=="-1" and legalPlayerCheck(player.color, gStates.handColors[Hands.getHands()[barConversion[id:sub(1,6)]].getValue()], "NoDummyException")==true then
	--if mouseButton=="-1" and legalPlayerCheck(player.color, turnOrder[gStates.turnNumber].seatPos)==true then
		local convert={[colorBand[1]]=playerBoard[1], [colorBand[2]]=playerBoard[2], [colorBand[3]]=playerBoard[3], [colorBand[4]]=playerBoard[4]}
		local board=getObjectFromGUID(convert[id:sub(1, 6)])
		local direction=1
		local boardImages={	"https://steamusercontent-a.akamaihd.net/ugc/1684895445424376912/3EE3230EE7EDE9465FBACB66989433E76889EE1B/",
							"https://steamusercontent-a.akamaihd.net/ugc/1684895445424553574/3C342119E5460E99D2CBA90E02703DEFE192A8D2/",
							"https://steamusercontent-a.akamaihd.net/ugc/1684895445424553344/A14FCE5B44805580B609C6331AE493DBF57DFF16/",
							"https://steamusercontent-a.akamaihd.net/ugc/1684895445424553120/FDF4B2E37BB40F81AD7A1DFC45FD3080EDBDD479/",
							"https://steamusercontent-a.akamaihd.net/ugc/1684895445424552867/531D8782F39294923F405B4A8BD33749FFCDC397/",
							"https://steamusercontent-a.akamaihd.net/ugc/1684895445424552298/DCE7288AD482269EF78E138258AEF64E02FB75F0/",
							"https://steamusercontent-a.akamaihd.net/ugc/1684895445424551898/6ED5EFA1552854F7F03E318B5DF1181E4A6388F1/",
							"https://steamusercontent-a.akamaihd.net/ugc/1684895445424551449/B2E1AD69C97515E4AA0B3B99B899DF3F00303E3A/",
							"https://steamusercontent-a.akamaihd.net/ugc/1684895445424553771/4BC2365C114D1D2EFA40127F12FE662927D7A658/",
							"https://steamusercontent-a.akamaihd.net/ugc/1684895445424553972/80BE3DDEAA19CADEAACE68ED263F52DB65465CF6/",
							"https://steamusercontent-a.akamaihd.net/ugc/1684895445424554181/1E919EDF42F1F900A53EE84DC6B24E0CCAE551B0/",
							"https://steamusercontent-a.akamaihd.net/ugc/1684895445424555147/6F7C91142DBDC2CC969E4C55760359791F0D89F8/",
							"https://steamusercontent-a.akamaihd.net/ugc/1684895445424601741/960077146FB0A7EFA4F5F54B6BD5B477BDFF5A6F/",
							"https://steamusercontent-a.akamaihd.net/ugc/1684895445424554674/5FC29A5A6972EED68545A897F9280FA3C954179F/",
							"https://steamusercontent-a.akamaihd.net/ugc/1684895445424554433/5E1CAFCDD9764C7370E9CA387E1E250FFBE95EEA/",
							"https://steamusercontent-a.akamaihd.net/ugc/1684895445424467915/9C5DD81B7345C49DB8ED3F9A5BA9E1E867855EF7/",
							"https://steamusercontent-a.akamaihd.net/ugc/1684895445424555440/E6D119CAA5633518305C512D82D87D033BCD27F2/",
							"https://steamusercontent-a.akamaihd.net/ugc/1684895445440810937/BD5AB7FC76EBA62C6041C19BEDFF187A191B9A3C/",
							"https://steamusercontent-a.akamaihd.net/ugc/1684895445440811336/57CCCDB1CA59C7EC8D78F36A8F41D867232E751A/",
							"https://steamusercontent-a.akamaihd.net/ugc/1684895445440811734/D2494176727E75376EC01F16BBB70E8AE1799238/",
							"https://steamusercontent-a.akamaihd.net/ugc/2546304515596768692/19801470032E2AD7FBC69C3817AD64A01998963F/",
							"https://steamusercontent-a.akamaihd.net/ugc/2546304515596768226/A7A269B1B5492AF4E3692015A1588B3EBD7A0414/"}
		if id:sub(7, 17)=="changeMatUp" then direction=-1 end
		for a=1, #boardImages, 1 do
			if boardImages[a]==board.getCustomObject().image and ((a>1 and direction==-1) or (a<#boardImages and direction==1)) then
				board.setCustomObject({image=boardImages[a+direction]})
				break
			end
			if boardImages[a]==board.getCustomObject().image and a==#boardImages then
				board.setCustomObject({image=boardImages[1]})
				break
			end
			if boardImages[a]==board.getCustomObject().image and a==1 then
				board.setCustomObject({image=boardImages[#boardImages]})
				break
			end
		end
		board.reload()
		Wait.time(function() getObjectFromGUID(convert[id:sub(1, 6)]).interactable=false end, 0.2)
	end
end

