function scaleBags(bag, obj, state)
	if getObjectFromGUID(bag.guid)~=nil and bag.getGMNotes()=="monsterBag" or bag.getGMNotes()=="Skills" or bag.getGMNotes()=="terrainBag" or bag.getGMNotes()=="Command Tokens" then
		--color tint the bag
		local contents=#getObjectFromGUID(bag.guid).getObjects()
		if state=="enter" and bag.guid==bagSearch then contents=contents+1 end
		if contents==0 then bag.setColorTint({r=0.4, g=0.4, b=0.4}) contents=1 else bag.setColorTint({r=1, g=1, b=1}) end
		if bag.getGMNotes()=="terrainBag" then
			if gStates.dayRound==false and gStates.firstStarted==true then
				bag.setColorTint({r=0.6, g=0.6, b=0.6})
				if state=="exit" then obj.setColorTint({r=0.6, g=0.6, b=0.6}) end
			else
				if state=="exit" then obj.setColorTint({r=1.0, g=1.0, b=1.0}) end
			end
		end
		--scale the bag
		local bagScaleDetails={	["monsterBag"]=		{scaleMult=1, 		bagPos=1, 		bagScaleMult=0.15},
								["Command Tokens"]=	{scaleMult=1, 		bagPos=1, 		bagScaleMult=0.15},
								["Skills"]=			{scaleMult=0.55, 	bagPos=1, 		bagScaleMult=0.05},
								["terrainBag"]=		{scaleMult=2.5, 	bagPos=0.97, 	bagScaleMult=0.125}}
		bag.setScale({x=bag.getScale()[1], y=contents*bagScaleDetails[bag.getGMNotes()].scaleMult, z=bag.getScale()[3]})
		if bag.getGMNotes()=="Skills" or bag.getGMNotes()=="terrainBag" then bag.setPosition({bag.getPosition()[1], bagScaleDetails[bag.getGMNotes()].bagPos+(contents*bagScaleDetails[bag.getGMNotes()].bagScaleMult), bag.getPosition()[3]}) end
		if state=="exit" and bagSearch~=bag.guid then obj.setPosition({bag.getPosition()[1], 2.00+(contents*bagScaleDetails[bag.getGMNotes()].bagScaleMult), bag.getPosition()[3]}) end
	end

	--Change the face of discard bags to simulate stacks
	local faceUpdateBags={["ed0ec9"]={empty="https://steamusercontent-a.akamaihd.net/ugc/938341811900383093/5C0B0863A2A684CC86F239B0AFC2B66CDB44281E/", last=""},--Orcs
