							["730898"]={empty="https://steamusercontent-a.akamaihd.net/ugc/938341811900384652/5F42B8B0CE7061B9D56B69693C88441D97ADC874/", last=""},--City
							["869a0f"]={empty="https://steamusercontent-a.akamaihd.net/ugc/775101936467726708/78E1EAC6AA943CA3A7C4DCCB0EB53B0CC9DFE388/", last=""},--Ruins
							["f9d3a4"]={empty="https://steamusercontent-a.akamaihd.net/ugc/938341811900383197/E0745EA1293600D6004CC8C56D11462620900FB9/", last=""},--Dark Crusader Rewards
