local volkareDiceRolled=false
function volkareTokenRandomize(token)--9a686a
	local VolkareReminder={	["Black Mana"]="https://steamusercontent-a.akamaihd.net/ugc/1617311203414015137/203E9CF64831CC5BBB43AAEC5CCBC9B450B2304E/",
							["Blue Mana"]="https://steamusercontent-a.akamaihd.net/ugc/1617311203413988434/BF2446CF89EF2F4398C38B32F5CAB104FCCE94AC/",
							["White Mana"]="https://steamusercontent-a.akamaihd.net/ugc/1617311203414024554/8541C7CC8BC88442619F8921DAA50CAE0BCD88E9/",
							["Green Mana"]="https://steamusercontent-a.akamaihd.net/ugc/1617311203414009198/C52B548C26AC08BCE1237A114A47DC973D0CE7D9/",
							["Red Mana"]="https://steamusercontent-a.akamaihd.net/ugc/1617311203414000318/7F26EE486FD34E0FD08E0653EF4DACCB69F38A87/",
							["Gold Mana"]="https://steamusercontent-a.akamaihd.net/ugc/1617311203413995197/64E0C4E59A98DAFB09633F31CA9D1279F0593CFD/",}
	--roll volkares dice and read result
	local volkareDice=getObjectFromGUID("9a686a")
	if volkareDiceRolled==false then volkareDice.randomize() volkareDiceRolled=true end
	Wait.frames(function() Wait.condition(function()
		if token~=nil then
			token.setCustomObject({image=VolkareReminder[volkareDice.getRotationValue()]})
			token.reload()
			if gStates.monsterPerks[token.guid]==nil then gStates.monsterPerks[token.guid]={} end
			gStates.monsterPerks[token.guid].arcaneImmunity=true
			gStates.monsterPerks[token.guid].brutal=true
			gStates.monsterPerks[token.guid].assassination=true
			if volkareDice.getRotationValue()=="Red Mana" then gStates.monsterPerks[token.guid].attack={F={3}} end
			if volkareDice.getRotationValue()=="Blue Mana" then gStates.monsterPerks[token.guid].attack={I={3}} end
			if volkareDice.getRotationValue()=="Green Mana" then gStates.monsterPerks[token.guid].poison=true gStates.monsterPerks[token.guid].attack={P={4}} end
			if volkareDice.getRotationValue()=="White Mana" then gStates.monsterPerks[token.guid].swiftness=true gStates.monsterPerks[token.guid].attack={P={3}} end
			if volkareDice.getRotationValue()=="Black Mana" then gStates.monsterPerks[token.guid].paralyse=true	gStates.monsterPerks[token.guid].attack={P={3}} end
			if volkareDice.getRotationValue()=="Gold Mana" then gStates.monsterPerks[token.guid].attack={IF={3}} end
			if volkareDiceRolled==true then
				broadcastToAll("{en}Volkare's Attack randomly picked{ru}Атака Волкара была определена{zh-cn}沃里卡随机挑选攻击对象{ko}볼케어의 공격이 결정되었습니다{es}Ataque de Volkare elegido al azar{fr}Attaque de Volkare choisie au hasard{pt-br}Ataque de Volkare aleatóriamente escolhido{de}Volkare's Angriff zufällig ausgewählt", {1,1,0.5})
				volkareDiceRolled=false
			end
		end
	end, function() return token==nil or (token.resting and volkareDice.resting) end) end, 2)
end

local mirroredManaDeployed=false
function mirrorSourceUpdate(from)
	if getObjectFromGUID("2cd825")~=nil and getObjectFromGUID("5cf042")~=nil then
		--record existing mana die and sort them
		local colorConvert={["Blue Mana"]=1, ["White Mana"]=2, ["Green Mana"]=3, ["Red Mana"]=4, ["Gold Mana"]=5, ["Black Mana"]=6}
		if gStates.dayRound==false then colorConvert["Gold Mana"]=6 colorConvert["Black Mana"]=5 end
		local colorRotate={{0, 0, 0}, {0, 0, 270}, {0, 0, 90}, {0, 0, 180}, {90, 0, 0}, {270, 0, 0}}
		if gStates.dayRound==false then colorRotate[5]={270, 0, 0} colorRotate[6]={90, 0, 0} end
		--erase existing mirror dice
		if gStates.manaMirror~=nil then
			for dieDel, _ in pairs (gStates.manaMirror) do
				if getObjectFromGUID(dieDel)~=nil then getObjectFromGUID(dieDel).destruct() end--and gStates.manaMirror[dieDel]~=nil
			end
		end
		--rebuild data base
		gStates.manaMirror={}
		gStates.manaSource={}
		local seperate=0
		for _, manaDie in pairs(getObjectFromGUID("2cd825").getObjects()) do
			if manaDie.type=="Dice" then
				gStates.manaSource[#gStates.manaSource+1]={manaDie=manaDie.guid, color=colorConvert[manaDie.getRotationValue()]}
				if colorConvert[manaDie.getRotationValue()]==6 then seperate=0.25 end
			end
		end
		table.sort(gStates.manaSource, function (k1, k2) return k1.color<k2.color end)
		--deploy a new set of dice infront of player boards.
		mirroredManaDeployed=true
		for _, playerDetails in pairs(turnOrder) do
			if playerDetails.mage~=gStates.positionMageKnight[5] then
				local spacing=0
				local first=false
				for pos, die in pairs(gStates.manaSource) do
					if die.color==6 and first==false then
						spacing=0.5 first=true
						if pos==1 then seperate=0 spacing=0 end
					end
					local mirrorDie=getObjectFromGUID("5cf042").takeObject({position={-105+(40*playerDetails.seatPos)+((1.5*pos)+spacing)+(((8-gStates.diceNeeded)/2)*1.5)-seperate, 1.57 , -28.1}, rotation=colorRotate[die.color], smooth=false})--Mana Dice Container
					gStates.manaMirror[mirrorDie.guid]=die.manaDie
				end
			end
		end
	end
end

local exitWaitID={}
local mirroredManaDeployedPause=nil
function diceResting(dice, state)
	if mirroredManaDeployed==false then
		if dice.type=="Dice" then
			if exitWaitID[dice.guid]~=nil then Wait.stop(exitWaitID[dice.guid]) end

			function updateDice()
				exitWaitID[dice.guid]=nil
				--Removed a dice
				if gStates.manaMirror[dice.guid]~=nil and getObjectFromGUID(gStates.manaMirror[dice.guid])~=nil and state=="exit" then
					getObjectFromGUID(gStates.manaMirror[dice.guid]).destruct()
					gStates.manaMirror[dice.guid]=nil
					return
				end
				--update an existing dice
				if state=="enter" then
					if getObjectFromGUID(gStates.manaMirror[dice.guid])~=nil then
						getObjectFromGUID(gStates.manaMirror[dice.guid]).setRotation(dice.getRotation())
					else--Re add dice to source.
						local NewDie=getObjectFromGUID("5cf042").takeObject({position={-12.5+(math.random()*7), 1.5 , -24.0+(math.random()*3.5)}, rotation=dice.getRotation(), smooth=false})--Mana Dice Container
						onObjectRandomize({type="Dice"})
						if getObjectFromGUID(dice.guid)~=nil then getObjectFromGUID(dice.guid).destruct() end
						return
					end
				end
				exitWaitID[dice.guid]=nil
				local moreDice=false
				for dice, waitfunction in pairs(exitWaitID) do
					if waitfunction~=nil then moreDice=true break end
				end
				if moreDice==false then exitWaitID={} Wait.frames(function() exitWaitID={} mirrorSourceUpdate("last dice resting in mirror") end, 2) end--wait for new dice to spawn
			end

			exitWaitID[dice.guid]=Wait.condition(updateDice, function() return getObjectFromGUID(dice.guid)==nil or dice.resting end, 10, updateDice)
		end
	else
		if mirroredManaDeployedPause~=nil then Wait.stop(mirroredManaDeployedPause) end
		mirroredManaDeployedPause=Wait.time(function() mirroredManaDeployed=false end, 0.3)
	end
end

function DealWound(paramaters)
	local woundbag=getObjectFromGUID(paramaters.guid)
	local playerPosition=math.ceil((woundbag.getPosition()[1]+80)/40)
	if legalPlayerCheck(paramaters.player.color, playerPosition)==true then
		woundbag.takeObject({position={(playerPosition*40)-91, 2.98, -48.40}})
		if paramaters.id=="DealPoison" then
			woundbag.takeObject({position={(playerPosition*40)-110.54, 2, -43.20}})
		end
	end
end

local explorePause=false
function exploreMap(player, mouseButton, id)
	if mouseButton=="-1" and legalPlayerCheck(player.color, turnOrder[gStates.turnNumber].seatPos)==true and explorePause==false then
		explorePause=true
		--convert index to location
		local pos={}
		local index=1
		for value in string.gmatch(id, "([^,]+)") do
			if index==1 then pos[index]=tonumber(value:sub(7, value:len())) else pos[index]=tonumber(value) end
			index=index+1
		end
		--Move city cards
		local found=false
		local cityCardTest={["White City Stats"]="d2d65e", ["White Blue Megapolis"]="d2d65e", ["White Red Megapolis"]="d2d65e", ["White Green Megapolis"]="d2d65e",
							["Blue City Stats"]="8a7266", ["Blue White Megapolis"]="8a7266", ["Blue Red Megapolis"]="8a7266", ["Blue Green Megapolis"]="8a7266",
							["Red City Stats"]="648da8", ["Red Blue Megapolis"]="648da8", ["Red White Megapolis"]="648da8", ["Red Green Megapolis"]="648da8",
							["Green City Stats"]="213d78", ["Green Blue Megapolis"]="213d78", ["Green Red Megapolis"]="213d78", ["Green White Megapolis"]="213d78"}
		for _, mightBeCityCard in pairs(getObjectFromGUID(mapArea).getObjects()) do
			if cityCardTest[mightBeCityCard.getName()]~=nil then
				local existingCard=mightBeCityCard.getPosition()
				if math.sqrt(((pos[1]-existingCard[1])^2)+((pos[2]-existingCard[3])^2))<3 then
					local locationTest={{-1.2, 1.09, 6.23},{4.8, 1.09, 4.15},{-6, 1.09, 2.08},{6, 1.09, -2.08},{-4.8, 1.09, -4.15},{1.2, 1.09, -6.23}--end first ring
										,{-7.2, 1.09, 8.33},{3.6, 1.09, 10.24},{10.82, 1.09, 2.12},{7.2, 1.09, -8.33},{-3.6, 1.09, -10.24},{-10.82, 1.09, -2.12},{9.6, 1.09, 8.23}}
					function freeSpace(desiredLocation)
						for _, playObj in pairs(getObjectFromGUID(mapArea).getObjects()) do
							if math.sqrt(((desiredLocation[1]-playObj.getPosition()[1])^2)+((desiredLocation[3]-playObj.getPosition()[3])^2))<3.1 then
								return false
							end
						end
						return true
					end
					for loop=1, #locationTest, 1 do
						if freeSpace({mightBeCityCard.getPosition()[1]+locationTest[loop][1], 1, mightBeCityCard.getPosition()[3]+locationTest[loop][3]})==true then
							--move the remaining monsters *AND SHIELDS AND MODELS*
							for _, cityCardObj in pairs(getObjectFromGUID(cityCardTest[mightBeCityCard.getName()]).getObjects()) do
								if cityCardObj.guid~="3d4319" and cityCardObj.guid~="519f96" then
									local originalPos=cityCardObj.getPosition()
									local relocation={originalPos[1]+locationTest[loop][1], originalPos[2], originalPos[3]+locationTest[loop][3]}
									cityCardObj.setPositionSmooth(relocation)
									if gStates.monsterPlayLocation[cityCardObj.guid]~=nil then gStates.monsterPlayLocation[cityCardObj.guid]=relocation end
								end
							end
							if gStates.cityMonsterQty[cityScriptZones[cityCardTest[mightBeCityCard.getName()]].cityGUID].extra.megapolisPair~=nil then
								local cityModelToZone={[cityModel.blue]="8a7266", [cityModel.red]="648da8", [cityModel.green]="213d78", [cityModel.white]="d2d65e"}
								local zoneToMove=gStates.cityMonsterQty[cityScriptZones[cityCardTest[mightBeCityCard.getName()]].cityGUID].extra.megapolisPair
								if zoneToMove==cityScriptZones[cityCardTest[mightBeCityCard.getName()]].cityGUID then
									for cityGUID, data in pairs(gStates.cityMonsterQty) do
										if data.extra.megapolisPair~=nil and data.extra.megapolisPair==zoneToMove and zoneToMove~=cityGUID then zoneToMove=cityGUID end
									end
								end
								zoneToMove=cityModelToZone[zoneToMove]
								for _, cityCardObj in pairs(getObjectFromGUID(zoneToMove).getObjects()) do
									if cityCardObj.guid~="3d4319" and cityCardObj.guid~="519f96" then
										local originalPos=cityCardObj.getPosition()
										local relocation={originalPos[1]+locationTest[loop][1], originalPos[2], originalPos[3]+locationTest[loop][3]}
										cityCardObj.setPositionSmooth(relocation)
										if gStates.monsterPlayLocation[cityCardObj.guid]~=nil then gStates.monsterPlayLocation[cityCardObj.guid]=relocation end
									end
								end
							end
							break
						end
					end
					break
				end
			end
		end
		--Life and Death not pulling the wrong city.
		local drawFrom="966e0e"
		if getObjectFromGUID(drawFrom).getQuantity()==0 then drawFrom="37d9b4" end
		if getObjectFromGUID(drawFrom).getQuantity()==0 then drawFrom="c87444" end
		local index=getObjectFromGUID(drawFrom).getQuantity()-1
		if gStates.gameScenario=="Life and Death" and getObjectFromGUID("966e0e").getQuantity()>1 then
			local northBearing=40
			local startTileGUID=startTerrain.open
			if getObjectFromGUID(startTileGUID)==nil then startTileGUID=startTerrain.wedge northBearing=70 end
			local startBearing=math.deg(math.atan2(pos[2]-getObjectFromGUID(startTileGUID).getPosition()[3], pos[1]-getObjectFromGUID(startTileGUID).getPosition()[1]))
			--Check if a City tile is played to wrong side in Life and Death
			local terainBagTest=getObjectFromGUID("966e0e").clone()
			terainBagTest.setGMNotes("")
			local nextTile=terainBagTest.takeObject()
			if (nextTile.guid=="53d847" and startBearing<=northBearing-1) or (nextTile.guid=="314081" and startBearing>=northBearing+1) then index=index-1 end
			terainBagTest.destruct()
			nextTile.destruct()
		end
		--Deploy Terrain tile
		local tileRotation={0, 180, 0}
		if gStates.randomTileOrientation==true then tileRotation[2]=math.random(1,6)*60 end
		if getObjectFromGUID(drawFrom).getQuantity()>0 then
			local drawnTile=getObjectFromGUID(drawFrom).takeObject({position={pos[1], 2, pos[2]}, rotation=tileRotation, smooth=false, index=index})
			drawnTile.setPositionSmooth({pos[1], 0.97, pos[2]})
			Wait.frames(function() Wait.condition(function()
				mainUIUpdate("Moved city card")
				explorePause=false
			end, function() return drawnTile.resting end) end, 2)
		end
	end
end

function cityBonusDecals(obj1, obj2)--obj2 is the rare case of a summoned monster. otherwise will be a duplicate of obj1
	local cityFound=false
	for _, cityDetail in pairs(gStates.cityMonsterQty) do
		for monsterGUID, monsterDetail in pairs(cityDetail) do
			if obj1.guid==monsterGUID then
				cityFound=true
				if cityDetail.extra~=nil and cityDetail.extra.monsterPerk~=nil then
					for _, perk in pairs(cityDetail.extra.monsterPerk) do
						--defense white city
						if perk=="Defense" and obj1.guid==obj2.guid then
							local found=false
							if obj2.getDecals()~=nil then
								for _, decalDetails in pairs(obj2.getDecals()) do
									if decalDetails.name=="Defense" then found=true break end
								end
							end
							if found==false then
								obj2.addDecal({name="Defense", url="https://steamusercontent-a.akamaihd.net/ugc/1673611238067673089/52A7BBBCEC031A7DACF3E6380E1A6551B442BD58/",	position={0.0, 0.15, -1.2}, rotation={90, 180, 0}, scale={0.6, 0.6, 1}})
								if gStates.monsterPerks[obj2.guid]==nil then gStates.monsterPerks[obj2.guid]={defence=true} else gStates.monsterPerks[obj2.guid].defence=true end
							end
						end
						--working
						if (perk=="Poison" or perk=="Brutal") and monsterPugs[obj2.guid].attack~=nil and monsterPugs[obj2.guid].attack.P~=nil then
							--poison green city
							if perk=="Poison" and monsterPugs[obj2.guid].poison==nil then
								local found=false
								if obj2.getDecals()~=nil then
									for _, decalDetails in pairs(obj2.getDecals()) do
										if decalDetails.name=="Poison" then found=true break end
									end
								end
								if found==false then
									obj2.addDecal({name="Poison", url="https://steamusercontent-a.akamaihd.net/ugc/1673611238067673667/F92475B8E390DB85DBE893576ED2D3D694ED9DB1/", position={-1.1, 0.15, 0.25}, rotation={90, 180, 0}, scale={0.6, 0.6, 1}})
									if gStates.monsterPerks[obj2.guid]==nil then gStates.monsterPerks[obj2.guid]={poison=true} else gStates.monsterPerks[obj2.guid].poison=true end
								end
							end
							--brutal red city
							if perk=="Brutal" and monsterPugs[obj2.guid].brutal==nil then
								local found=false
								if obj2.getDecals()~=nil then
									for _, decalDetails in pairs(obj2.getDecals()) do
										if decalDetails.name=="Brutal" then found=true break end
									end
								end
								if found==false then
									obj2.addDecal({name="Brutal", url="https://steamusercontent-a.akamaihd.net/ugc/1673611238067672015/23EA4CA2B804F86477D9F5051D91629FED16EB5A/", position={-1.1, 0.15, -0.25}, rotation={90, 180, 0}, scale={0.6, 0.6, 1}})
									if gStates.monsterPerks[obj2.guid]==nil then gStates.monsterPerks[obj2.guid]={brutal=true} else gStates.monsterPerks[obj2.guid].brutal=true end
								end
							end
						end
						--Elemental blue city
						if perk=="Elemental" and monsterPugs[obj2.guid].attack~=nil and (monsterPugs[obj2.guid].attack.F~=nil or monsterPugs[obj2.guid].attack.I~=nil or monsterPugs[obj2.guid].attack.IF~=nil) then
							local found=false
							if obj2.getDecals()~=nil then
								for _, decalDetails in pairs(obj2.getDecals()) do
									if decalDetails.name=="Elemental" then found=true break end
								end
							end
							if found==false then
								if monsterPugs[obj2.guid].attack.F~=nil then obj2.addDecal({name="Elemental", url="https://steamusercontent-a.akamaihd.net/ugc/1673611238067806764/12F642495CA4D514DEEED87077E8ABA9A18260E4/",
								position={1.2, 0.15, 0}, rotation={90, 180, 0}, scale={0.6, 0.6, 1}}) end
								if monsterPugs[obj2.guid].attack.I~=nil then obj2.addDecal({name="Elemental", url="https://steamusercontent-a.akamaihd.net/ugc/1673611238067808116/62CEE613A2A3FBAB108325F1D810A267AB61DECB/",
								position={1.2, 0.15, 0.05}, rotation={90, 180, 0}, scale={0.6, 0.6, 1}}) end
								if monsterPugs[obj2.guid].attack.IF~=nil then obj2.addDecal({name="Elemental", url="https://steamusercontent-a.akamaihd.net/ugc/1673611238067807411/95A06C6568F9D41023BE06F6D49C57833C17C21F/",
								position={1.2, 0.15, 0}, rotation={90, 180, 0}, scale={0.6, 0.6, 1}}) end
								if gStates.monsterPerks[obj2.guid]==nil then gStates.monsterPerks[obj2.guid]={elemental=true} else gStates.monsterPerks[obj2.guid].elemental=true end
							end
						end
						--fortified
						if perk=="Fortified" and monsterPugs[obj2.guid].unfortified==nil and gStates.gameScenario~="The Chaos Rift" and obj1.guid==obj2.guid then
							local found=false
							if obj2.getDecals()~=nil then
								for _, decalDetails in pairs(obj2.getDecals()) do
									if decalDetails.name=="Fortified" then found=true break end
								end
							end
							if found==false then
								obj2.addDecal({name="Fortified", url="https://steamusercontent-a.akamaihd.net/ugc/1673611238067672640/A38B0521789914C98C53A6E0688BB7577A2C7F56/", position={0.8, 0.15, -0.8}, rotation={90, 180, 0}, scale={0.6, 0.6, 1}})
								if gStates.monsterPerks[obj2.guid]==nil then gStates.monsterPerks[obj2.guid]={fortified=true} else gStates.monsterPerks[obj2.guid].fortified=true end
							end
						end
					end
					break
				end
			end
		end
		if cityFound==true then break end
	end
end

function straightenCrooked()
	--send city cards to bottom so tokens don't spawn under.
	local sendToBottom={dummyBoard, gStates.cityCard[cityModel.blue], gStates.cityCard[cityModel.red], gStates.cityCard[cityModel.green], gStates.cityCard[cityModel.white], "e47fc3", "62d3c3", "12a3b1", "6f815c", "94c021", "d9c252", "7a56fa", "19c6ce", "aa6c1d", "d80815", "fdbc08", "0b57b9"}
	for _, objGUID in pairs(sendToBottom) do
		if getObjectFromGUID(objGUID)~=nil then
			--getObjectFromGUID(objGUID).unlock()
			getObjectFromGUID(objGUID).setPosition({getObjectFromGUID(objGUID).getPosition()[1], 0.98, getObjectFromGUID(objGUID).getPosition()[3]})
			local rot={0.00, 180.00, 0.00}
			if getObjectFromGUID(objGUID).getRotation()[3]>=170 and getObjectFromGUID(objGUID).getRotation()[3]<=190 then rot=({0.00, 180.00, 180.00}) end
			getObjectFromGUID(objGUID).setRotation(rot)
			--Wait.time(function() getObjectFromGUID(objGUID).lock() end, 0.5)
		end
	end
end

function monsterImageSwap(player, mouseButton, id)
	if mouseButton=="-1" then
		for monsterGuid, monsterDetails in pairs(monsterPugs) do
			if getObjectFromGUID(monsterGuid)~=nil then
				if gStates.useAlternatePugs==false and (monsterDetails.original~="" or monsterDetails.alternate~="") then
					getObjectFromGUID(monsterGuid).setCustomObject({image=monsterDetails.alternate})
				else
					getObjectFromGUID(monsterGuid).setCustomObject({image=monsterDetails.original})
				end
				getObjectFromGUID(monsterGuid).reload()
			end
		end
		if gStates.useAlternatePugs==false then
			gStates.useAlternatePugs=true
			getObjectFromGUID("d7a165").UI.setAttribute("d7a165swapMonsterImageText", "text", "Stefano Colombo's Monster Tokens - ON")
		else
			gStates.useAlternatePugs=false
			getObjectFromGUID("d7a165").UI.setAttribute("d7a165swapMonsterImageText", "text", "Stefano Colombo's Monster Tokens - OFF")
		end
		--discard containers
		local discardContainers={"6ae8c3", "b336a7", "730898", "869a0f", "b23c77", "763c2d", "ed0ec9", "9860ce", "e9b18c", "61ba30", "f9d3a4", "80c10d", "236555", "4aecb4", "076ab9"}
		for _, containerGuid in pairs(discardContainers) do
			if getObjectFromGUID(containerGuid)~=nil and getObjectFromGUID(containerGuid).getQuantity()>0 then
				temp=getObjectFromGUID(containerGuid).takeObject({position={getObjectFromGUID(containerGuid).getPosition()[1], 5, getObjectFromGUID(containerGuid).getPosition()[3]}, smooth=false})
			end
		end
	end
end

