		local c="{en}Friendly, but no one is the leader.{ru}дружественные, но никто не является их владельцем.{zh-cn}善意模式，无领导者。{ko}우호적이며 아무도 지도자가 아닙니다.{es}son Amistosas, pero nadie es el líder.{fr}Amical, mais personne n'est le leader.{pt-br}Amistosas, mas ninguém é o líder.{de}Freundlich, aber niemand ist der Anführer."
		if gStates.gameScenario=="First Reconnaissance" then c="{en}meant to be discovered only.{ru}только должны быть разведаны.{zh-cn}意味着仅能被发现。{ko}오직 발견될 목적에만 있습니다.{es}deben ser descubiertas.{fr}destiné à être uniquement découvert.{pt-br}Para serem descobertas apenas.{de}soll nur entdeckt werden." end
		if gStates.gameScenario=="Conquer and Hold" then c="{en}Barred, No players may enter.{ru}закрыты, ни один игрок не может войти.{zh-cn}玩家不可以进入。{ko}닫혀있습니다. 아무도 들어갈 수 없습니다.{es}están bloqueadas. Ningún jugador puede entrar.{fr}Interdit, aucun joueur ne peut entrer.{pt-br}Barradas, nenhum jogador pode entrar.{de}Gesperrt, kein Spieler darf eintreten." end
		if gStates.gameScenario=="The Lost Relic Blitz" then c="{en}Ruined, find only dragons there.{ru}разрушены, там можно найти только драконов.{zh-cn}完球了，这里只找到一条恶龙。{ko}파괴됐습니다. 오직 용만이 존재할뿐.{es}están en ruinas, solo hay dragones en ellas.{fr}Ruiné, on n'y trouve que des dragons.{pt-br}Arruinadas, encontre apenas Dragões lá.{de}Ruiniert, finde dort nur Drachen." end
		b=joinLang({b, c})
		UI.setAttribute("CityNote", "text", b)
	end
	--Volkare's Camp as City Menu Access
	if #scenarioList[gStates.scenarioRef][gStates.playersRef].cityLevels==5 and gStates.gameScenario~="Volkare's Return" and gStates.gameScenario~="Volkare's Return Blitz" and gStates.gameScenario~="Volkare's Quest" and gStates.gameScenario~="The War of Four" then
		UI.setAttribute("volkareCampAsCity", "interactable", "False")
		UI.setAttribute("volkareCampAsCity", "isOn", "true")
		gStates.volkareCampAsCity=true
	else
		--UI.setAttribute("volkareCampAsCity", "interactable", "True")
		if (gStates.megapolis==0 and
			(gStates.gameScenario=="First Conquest" or
			gStates.gameScenario=="Conquest" or
			gStates.gameScenario=="Conquest Blitz" or
			gStates.gameScenario=="Conquer and Hold" or
			gStates.gameScenario=="Fast Forwarded Conquest" or
			gStates.gameScenario=="The Lost Relic Blitz")) or gStates.gameScenario=="Ultimate Conquest" then
			UI.setAttribute("volkareCampAsCity", "interactable", "True")
		else
			UI.setAttribute("volkareCampAsCity", "interactable", "False")
			UI.setAttribute("volkareCampAsCity", "isOn", "false")
			gStates.volkareCampAsCity=false
		end
	end
	--Display the Scenario End rules
	UI.setAttribute("ScenarioEnd", "text", scenarioList[gStates.scenarioRef].scenarioDetails.scenarioEnd)
	--Only allow Start button if 2 or more knights are selected
	UI.setAttribute("WarOfFourStartButton", "active", "false")
	UI.setAttribute("StartButton", "active", "false")
	UI.setAttribute("StartButton", "width", "1000")
	--UI.setAttribute("StartButton", "rectAlignment", "LowerCenter")
	if gStates.playerCount>=2 or (gStates.playerCount>=1 and gStates.positionMageKnight[5]~="nobody") then
		UI.setAttribute("StartButton", "interactable", "True")
		UI.setAttribute("StartButtonImage", "image", "Sliced Button/Button New Active")
		if gStates.gameScenario=="The War of Four" and gStates.playerCount>=2 then
			UI.setAttribute("WarOfFourStartButton", "active", "True")
			UI.setAttribute("StartButton", "width", "500")
			--UI.setAttribute("StartButton", "rectAlignment", "LowerLeft")
		end
		UI.setAttribute("StartButton", "active", "true")
	else
		UI.setAttribute("StartButton", "interactable", "False")
		UI.setAttribute("StartButtonImage", "image", "Sliced Button/Button New Deactive")
		UI.setAttribute("StartButtonText", "text", "{en}Start - Select at least two Mage Knights first{ru}Начало - Сначала выберите как минимум двух Рыцарей-магов.{zh-cn}开始 - 首先选择至少两位魔法骑士{ko}시작 - 먼저 두 명 이상의 플레이어를 선택하세요{es}Comenzar - Selecciona al menos dos Mage Knight {fr}Démarrer - Sélectionnez d'abord au moins deux Mages{pt-br}Início - Selecione ao menos dois Mage Knights primeiro{de}Start - Wähle vorher mindestens 2 Mage Knights")
		UI.setAttribute("StartButton", "active", "true")
	end
end

function DisplayScore(player, mouseButton, id)
	if mouseButton=="-1" then
		--Count all objects required for scoring
		local seatRecord=5
		for a=1, #turnOrder, 1 do
			if turnOrder[a].mage==gStates.positionMageKnight[5] then
				seatRecord=turnOrder[a].seatPos
				turnOrder[a].seatPos=5
				break
			end
		end
		table.sort(turnOrder, function (k1, k2) return k1.seatPos<k2.seatPos end)
		for a=1, #turnOrder, 1 do
			if turnOrder[a].mage==gStates.positionMageKnight[5] then
				turnOrder[a].seatPos=seatRecord
				break
			end
		end
		local foundRelic=0--Not individually scored
		local coopGraveYard=0
		local objectsInPlay=getObjectFromGUID(mapArea).getObjects()
		table.sort(objectsInPlay, function (k1, k2) return k1.getPosition()[2]>k2.getPosition()[2] end)
		for a=1, #turnOrder, 1 do
			if turnOrder[a].mage~=gStates.positionMageKnight[5] then
				local obj={}
				local artifactDupeCheck={}
				for b, c in pairs(objectsInPlay) do obj[#obj+1]=c end
				--Look for Cards
				for b, c in pairs(getObjectFromGUID(deedDeckZones[turnOrder[a].seatPos]).getObjects()) do obj[#obj+1]=c end
				for b, c in pairs(getObjectFromGUID(deedDeckDiscardZones[turnOrder[a].seatPos]).getObjects()) do obj[#obj+1]=c end
				for b, c in pairs(getObjectFromGUID(handZones[turnOrder[a].seatPos]).getObjects()) do obj[#obj+1]=c end
				for b, c in pairs(getObjectFromGUID(playerPlayAreas[turnOrder[a].seatPos]).getObjects()) do obj[#obj+1]=c end
				--look for Crystals and reward tokens
				for b, c in pairs(getObjectFromGUID(playerCrystalAreas[turnOrder[a].seatPos]).getObjects()) do obj[#obj+1]=c end
				--look for Units
				local playerUnits=getObjectFromGUID(playerUnitAreas[turnOrder[a].seatPos]).getObjects()
				for b, c in pairs(playerUnits) do obj[#obj+1]=c end
				--Zero out any existing scores
				local scoreVariable={"AdvanceAction", "Spell", "Artifact", "Wound", "Crystal", "Potion", "Units", "UnitsLevel", "WoundedUnits", "WoundedUnitsLevel", "Keep", "Reward", "GraveYard", "Glade"
									, "MageTower", "Monastery", "VolkareCamp", "DungeonTomb", "SpawningDen", "Ruin", "Maze", "Relic", "CountryMine", "CoreMine"}
				for b, c in pairs(scoreVariable) do
					turnOrder[a].score[c]=0
				end
				--count found objects
				for b, c in pairs(obj) do
					--Count Card Types
					if c.type=="Card" then
						if c.getGMNotes()=="Advanced Action" then turnOrder[a].score.AdvanceAction=turnOrder[a].score.AdvanceAction+1 end
						if c.getName()=="Spell" then turnOrder[a].score.Spell=turnOrder[a].score.Spell+1 end
						if c.getName()=="Artifact" and artifactDupeCheck[c.guid]==nil then turnOrder[a].score.Artifact=turnOrder[a].score.Artifact+1 artifactDupeCheck[c.guid]=1 end
						if c.getName()=="Wound" then turnOrder[a].score.Wound=turnOrder[a].score.Wound+1 end
						if c.getName()=="Regular Unit" or c.getName()=="Elite Unit" then
							--look for wound
							local found=false
							local unitLocation=c.getPosition()[1]
							for e, woundToken in pairs(playerUnits) do
								if woundToken.getGMNotes()=="Unit Wound" then
									local woundLocation=woundToken.getPosition()[1]
									if woundLocation<=unitLocation+1.7 and woundLocation>=unitLocation-1.7 then
										turnOrder[a].score.WoundedUnits=turnOrder[a].score.WoundedUnits+1
										turnOrder[a].score.WoundedUnitsLevel=turnOrder[a].score.WoundedUnitsLevel+math.floor(gameCards[c.guid].level/2)
										found=true
										break
									end
								end
							end
							if found==false then
								turnOrder[a].score.Units=turnOrder[a].score.Units+1
								turnOrder[a].score.UnitsLevel=turnOrder[a].score.UnitsLevel+gameCards[c.guid].level
							end
						end
				 	end
					if c.type=="Deck" then
						for _, card in pairs(c.getObjects()) do
							if card.gm_notes=="Advanced Action" then turnOrder[a].score.AdvanceAction=turnOrder[a].score.AdvanceAction+1 end
							if card.nickname=="Spell" then turnOrder[a].score.Spell=turnOrder[a].score.Spell+1 end
							if card.nickname=="Artifact" then turnOrder[a].score.Artifact=turnOrder[a].score.Artifact+1 end
							if card.nickname=="Wound" then turnOrder[a].score.Wound=turnOrder[a].score.Wound+1 end
						end
					end
					--count Crystals
					if c.type=="Figurine" then
						if c.getPosition()[1]<turnOrder[a].seatPos*40-109.76 and c.getPosition()[3]<-31 then turnOrder[a].score.Crystal=turnOrder[a].score.Crystal+1 end
					end
					--count Faction Rewards
					if c.type=="Tile" then
						if c.getPosition()[1]<turnOrder[a].seatPos*40-109.76 and c.getPosition()[3]<-31 then
							if c.getName()~="Red Potion" and c.getName()~="Blue Potion" and c.getName()~="Green Potion" and c.getName()~="White Potion" then
								if c.getGMNotes()=="Dark Crusader Reward" or c.getGMNotes()=="Elementalist Reward" then turnOrder[a].score.Reward=turnOrder[a].score.Reward+1 end
							else
								turnOrder[a].score.Potion=turnOrder[a].score.Potion+1
							end
						end
					end
					--Count Shield tokens
					if c.getName()=="Shield" and c.getDescription()==turnOrder[a].mage then
						local found=false
						local shieldPos=c.getPosition()
						for e, terTile in pairs(objectsInPlay) do
							local tilePos=terTile.getPosition()
							local shieldToTileDist=math.sqrt(((shieldPos[1]-tilePos[1])^2)+((shieldPos[3]-tilePos[3])^2))
							--Figure out which hex it is on
							if terrainTiles[terTile.guid]~=nil then
								if shieldToTileDist<3.1 then
									found=true
									if terTile.guid==gStates.cityVolkareTile then turnOrder[a].score.VolkareCamp=turnOrder[a].score.VolkareCamp+1 end
									local bearing="center"
									if shieldToTileDist>1 then
										local temp=(60*(math.floor((math.deg(math.atan2(shieldPos[3]-tilePos[3], shieldPos[1]-tilePos[1]))+terTile.getRotation()[2]+30)/60)))
										if temp>=360 then temp=temp-360 end
										if temp<0 then temp=temp+360 end
										bearing=tostring(temp)
									end
									for hexLocation, hexFeature in pairs(terrainTiles[terTile.guid].hexFeature) do
										if hexLocation==bearing or (bearing=="center" and hexFeature:sub(1, 4)=="city") then
											if hexFeature=="keep" then turnOrder[a].score.Keep=turnOrder[a].score.Keep+1 end
											if hexFeature=="mage tower" then turnOrder[a].score.MageTower=turnOrder[a].score.MageTower+1 end
											if hexFeature=="monastery" then turnOrder[a].score.Monastery=turnOrder[a].score.Monastery+1 end
											if hexFeature=="ruin" then turnOrder[a].score.Ruin=turnOrder[a].score.Ruin+1 end
											if hexFeature=="glade" then turnOrder[a].score.Glade=turnOrder[a].score.Glade+1 end
											if hexFeature=="dungeon" or hexFeature=="tomb" then turnOrder[a].score.DungeonTomb=turnOrder[a].score.DungeonTomb+1 end
											if hexFeature=="monster den" or hexFeature=="spawning grounds" then turnOrder[a].score.SpawningDen=turnOrder[a].score.SpawningDen+1 end
											if hexFeature=="maze" or hexFeature=="labyrinth"then turnOrder[a].score.Maze=turnOrder[a].score.Maze+1 end
											if (hexFeature:sub(1,4)=="city" or hexFeature=="Volkare's Camp") and gStates.gameScenario=="The Lost Relic Blitz" then turnOrder[a].score.Relic=turnOrder[a].score.Relic+1 foundRelic=foundRelic+1 end
											if hexFeature:sub(1,4)=="mine" and gStates.gameScenario=="Mines Liberation" then
												if terrainTiles[terTile.guid].tileType=="core" then
													turnOrder[a].score.CoreMine=turnOrder[a].score.CoreMine+1
												else
													turnOrder[a].score.CountryMine=turnOrder[a].score.CountryMine+1
												end
											end
											break
										end
									end
								end
							end
							if shieldToTileDist<1 then
								--dungeons for Dungeon Lords
								if terTile.getRotationValues()[2]~=nil and gStates.gameScenario=="Dungeon Lords" then
									if terTile.getRotationValues()[2].value=="Dungeon Monster" or terTile.getRotationValues()[2].value=="Draconum" then
										turnOrder[a].score.DungeonTomb=turnOrder[a].score.DungeonTomb+1
										found=true
									end
								end
								--GraveYards
								if terTile.getName()=="GraveYard" then
									turnOrder[a].score.GraveYard=turnOrder[a].score.GraveYard+1
									coopGraveYard=coopGraveYard+1
									found=true
								end
							end
							if found==true then break end
						end
					end
				end
			else
				--count the amount of cards left in the dummy or Volkare's deck
				turnOrder[a].score.CardsLeft=0
				for b, c in pairs(getObjectFromGUID(deedDeckZones[turnOrder[a].seatPos]).getObjects()) do
					if c.type=="Card" then turnOrder[a].score.CardsLeft=1 break end
					if c.type=="Deck" then turnOrder[a].score.CardsLeft=c.getQuantity() break end
				end
			end
		end
		--Figure out who leads and assisted in cities
		cityBeatCheck()
		--find the greatest in a category for competative games
		local coopScore=0
		local coopKey={}
		local scoreMax=0
		local scoreMin=999
		local key={}
		--Lowest fame
		if gStates.coop==1 then
			for a=1, #turnOrder, 1 do
				local currentLowScore=999
				if turnOrder[a].mage~=gStates.positionMageKnight[5] then currentLowScore=turnOrder[a].fame+turnOrder[a].score.Reward end
				if currentLowScore==scoreMin then key[#key+1]=a end
				if currentLowScore<scoreMin then scoreMin=currentLowScore key={a} end
			end
			coopScore=coopScore+turnOrder[key[1]].fame+turnOrder[key[1]].score.Reward coopKey.lFame=key[1]
		end
		--Find Greatest in all the categories
		local greatestTable={gKnowledge=	{function(z) return turnOrder[z].score.AdvanceAction+(turnOrder[z].score.Spell*2) end},
							 gLoot=			{function(z) return (turnOrder[z].score.Artifact*2)+math.floor(turnOrder[z].score.Crystal/2)+turnOrder[z].score.Potion end},
							 gLeader=		{function(z) return turnOrder[z].score.UnitsLevel+turnOrder[z].score.WoundedUnitsLevel end},
							 gAdventurer=	{function(z) return (turnOrder[z].score.DungeonTomb+turnOrder[z].score.SpawningDen+turnOrder[z].score.Ruin+turnOrder[z].score.Maze)*2 end,
											 function(z) return (turnOrder[z].score.DungeonTomb*4)+(turnOrder[z].score.SpawningDen+turnOrder[z].score.Ruin+turnOrder[z].score.Maze)*2 end},
							 gConqueror=	{function(z) return ((turnOrder[z].score.Keep+turnOrder[z].score.MageTower+turnOrder[z].score.Monastery)*2)+turnOrder[z].score.VolkareCamp end},
							 gLiberator=	{function(z) return (turnOrder[z].score.CoreMine*7)+(turnOrder[z].score.CountryMine*4) end,
							 				function(z) return (turnOrder[z].score.CoreMine*7)+(turnOrder[z].score.CountryMine*4) end},
							 gBeating=		{function(z) return turnOrder[z].score.Wound*2 end},
							 gCityLead=		{function(z) return (turnOrder[z].score.CityLead*7)+(turnOrder[z].score.CityAssist*4) end, function(z) return (turnOrder[z].score.CityLead*7)+(turnOrder[z].score.CityAssist*4) end},
							 gRelic=		{function(z) return turnOrder[z].score.Relic*5 end, nil ,
						 					 function(z) return turnOrder[z].score.Relic*4 end}}
		local greatestBonus={{3, 1}, {5, 2}, {4, 2}}
		for greatName, scoreMath in pairs(greatestTable) do
			local ref=1
			if gStates.gameScenario=="Mines Liberation" and greatName=="gLiberator" then ref=2 end
			if gStates.gameScenario=="Dungeon Lords" and greatName=="gAdventurer" then ref=2 end
			if (gStates.gameScenario=="Conquest" or gStates.gameScenario=="Conquest Blitz" or gStates.gameScenario=="Ultimate Conquest" or gStates.gameScenario=="Fast Forwarded Conquest") and greatName=="gCityLead" then ref=2 end
			if gStates.gameScenario=="The Lost Relic Blitz" and gStates.coop==0 and greatName=="gRelic" then ref=3 end
			scoreMax=0
			key={}
			for player=1, #turnOrder, 1 do
				turnOrder[player].score[greatName]=0
				local currentHighScore=-1
				if turnOrder[player].mage~=gStates.positionMageKnight[5] then currentHighScore=scoreMath[ref](player) end
				if currentHighScore==scoreMax then key[#key+1]=player end
				if currentHighScore>scoreMax then scoreMax=currentHighScore key={player} end
			end
			if #key==1 and scoreMax~=0 and (gStates.coop==0 or gStates.WarOfFourComp==true) then turnOrder[key[1]].score[greatName]=greatestBonus[ref][1] end
			if #key>1 and scoreMax~=0 and (gStates.coop==0 or gStates.WarOfFourComp==true) then for a=1, #key, 1 do turnOrder[key[a]].score[greatName]=greatestBonus[ref][2] end end
			if gStates.coop==1 and greatName~="gBeating" and greatName~="gCityLead" then coopScore=coopScore+scoreMath[ref](key[1]) coopKey[greatName]=key[1] end
			if gStates.coop==1 and greatName=="gBeating" and greatName~="gCityLead" then coopScore=coopScore-scoreMath[ref](key[1]) coopKey[greatName]=key[1] end
		end

		--Update Score Card
		local scoreCardSections={	"KnowledgeScoreHeading",	"KnowledgeScoreData",
									"LootScoreHeading",			"LootScoreData",
									"LeaderScoreHeading",		"LeaderScoreData",
									"ConquerorScoreHeading",	"ConquerorScoreData",
									"AdventurerScoreHeading",	"AdventurerScoreData",
									"LiberatorScoreHeading",	"LiberatorScoreData",
									"BeatingScoreHeading",		"BeatingScoreData",
									"RelicScoreHeading",		"RelicScoreData",
									"RewardScoreHeading",		"RewardScoreData",
									"CityScoreHeading",			"CityScoreData",
									"VolkareScoreHeading",		"VolkareScoreData",
									"TezlaScoreHeading",		"TezlaScoreData",
									"EfficiencyScoreHeading",	"EfficiencyScoreData"}
		for a, b in pairs(scoreCardSections) do
			UI.setAttribute(b, "active", "false")
		end
		local pannel=1
		local totalHeight=54+25+30+30
		local assembledText=""
		local lineFeed=0
		local heights={Knowledge=0, Loot=0, Leader=0, Conqueror=0, Adventurer=0, Liberator=0, Beating=0, Volkare=0, Efficiency=0, City=0, Relic=0, Tezla=0, Reward=0}

		--Display and add up score pannel heights
		function updateScorePannel(scoreName, lineFeed, assembledText)
			local pannelText=tostring(pannel)
			local textCol="rgb(0, 0, 0)"
			if coopKey["g"..scoreName]~=pannel and coopKey["g"..scoreName]~=nil and gStates.coop==1 and scoreName~="Relic" then textCol="rgb(0.2, 0.2, 0.4)" end
			if scoreName=="Volkare" or scoreName=="Efficiency" then pannelText="" end
			UI.setAttribute(scoreName..pannelText.."ScoreText", "text", "")
			UI.setAttribute(scoreName..pannelText.."ScoreCell", "active", "true")
			local scoreHieght=0
			if lineFeed>0 then scoreHieght=(lineFeed*25)-((lineFeed-1)*8) end
			if scoreHieght>heights[scoreName] then
				if lineFeed>0 then totalHeight=totalHeight+scoreHieght-heights[scoreName] end
				heights[scoreName]=scoreHieght
				UI.setAttribute(scoreName.."ScoreData", "preferredHeight", heights[scoreName])
			end
			if lineFeed>0 then
				UI.setAttribute(scoreName.."ScoreHeading", "active", "true")
				UI.setAttribute(scoreName.."ScoreData", "active", "true")
				UI.setAttribute(scoreName..pannelText.."ScoreText", "Color", textCol)
				UI.setAttribute(scoreName..pannelText.."ScoreText", "text", assembledText)
			end
		end

		--Work out which scores to display
		for a=1, #turnOrder, 1 do
			local totalScore=0
			if turnOrder[a].mage~=gStates.positionMageKnight[5] then
				if gStates.gameScenario~="Conquer and Hold" and gStates.gameScenario~="One to Return" then
					--Base Score
					local textCol="rgb(0, 0, 0)"
					if coopKey.lFame~=a and gStates.coop==1 then textCol="rgb(0.2, 0.2, 0.4)" end
					UI.setAttribute("Mage"..pannel.."BaseScoreText", "Color", textCol)
					UI.setAttribute("Mage"..pannel.."BaseScoreCell", "active", "true")
					UI.setAttribute("Mage"..pannel.."BaseScoreText", "text", joinLang({translateWord[turnOrder[a].mage], "{en}'s Base Fame: {ru}имеет Славы: {zh-cn}的基础名望: {ko} 의 기본 명성: {es} Fama Base: {fr} Gloire Base: {pt-br} Fama Base: {de}Basis-Ruhm: ", turnOrder[a].fame}))
					totalScore=turnOrder[a].fame

					--Knowledge Score
					assembledText="" lineFeed=0
					if turnOrder[a].score.AdvanceAction>0 then
						assembledText=joinLang({turnOrder[a].score.AdvanceAction, "{en} Advanced Action(s): +{ru} Особое действие: +{zh-cn}张高级行动卡: +{ko} 상급 액션: +{es} Acciones Avanzadas: +{fr} Actions Avancées: +{pt-br} Ações Avançadas: +{de} Fortgeschrittene Aktion(en): +", turnOrder[a].score.AdvanceAction})
						lineFeed=lineFeed+1
						totalScore=totalScore+turnOrder[a].score.AdvanceAction
					end
					if turnOrder[a].score.Spell>0 then
						if lineFeed>0 then assembledText=joinLang({assembledText, "\n"}) end
						assembledText=joinLang({assembledText, turnOrder[a].score.Spell, "{en} Spell(s): +{ru} Заклинание: +{zh-cn}张法术卡: +{ko} 마법: +{es} Hechizos: +{fr} Sorts: +{pt-br} Feitiços: +{de} Zauberspruch(e): +", (turnOrder[a].score.Spell*2)})
						lineFeed=lineFeed+1
						totalScore=totalScore+(turnOrder[a].score.Spell*2)
					end
					if turnOrder[a].score.gKnowledge>0 then
						if lineFeed>0 then assembledText=joinLang({assembledText, "\n"}) end
						assembledText=joinLang({assembledText, "{en}Greatest Knowledge: +{ru}Великий мудрец: +{zh-cn}博古通今： +{ko}위대한 지식: +{es}Mayor Conocimiento: +{fr}Plus Grand Connaissance: +{pt-br}Mais Conhecimento: +{de}Größtes Wissen: +", turnOrder[a].score.gKnowledge})
						lineFeed=lineFeed+1
						totalScore=totalScore+turnOrder[a].score.gKnowledge
					end
					updateScorePannel("Knowledge", lineFeed, assembledText)

					--Loot Score
					assembledText="" lineFeed=0
					if turnOrder[a].score.Artifact>0 then
						assembledText=joinLang({turnOrder[a].score.Artifact, "{en} Artifact(s): +{ru} Артефакт: +{zh-cn}张圣器卡: +{ko} 유물: +{es} Artefactos: +{fr} Artefacts: +{pt-br} Artefatos: +{de} Artefakt(e): +", (turnOrder[a].score.Artifact*2)})
						lineFeed=lineFeed+1
						totalScore=totalScore+(turnOrder[a].score.Artifact*2)
					end
					if turnOrder[a].score.Crystal>0 then
						if lineFeed>0 then assembledText=joinLang({assembledText, "\n"}) end
						assembledText=joinLang({assembledText, turnOrder[a].score.Crystal, "{en} Mana Crystal(s): +{ru} Кристалл маны: +{zh-cn}个未使用的魔晶: +{ko} 마나 수정: +{es} Cristales de Maná: +{fr} Cristaux de Mana: +{pt-br} Cristais de Mana: +{de} Manakristall(e): +", math.floor(turnOrder[a].score.Crystal/2)})
						lineFeed=lineFeed+1
						totalScore=totalScore+math.floor(turnOrder[a].score.Crystal/2)
					end
					if turnOrder[a].score.Potion>0 then
						if lineFeed>0 then assembledText=joinLang({assembledText, "\n"}) end
						assembledText=joinLang({assembledText, turnOrder[a].score.Potion, "{en} Potion(s): +{ru} Зелье: +{zh-cn}瓶药剂： +{ko} 포션: +{es} Pociones: +{fr} Potion: +{pt-br} Poções: +{de} Trank(e): +", turnOrder[a].score.Potion})
						lineFeed=lineFeed+1
						totalScore=totalScore+turnOrder[a].score.Potion
					end
					if turnOrder[a].score.gLoot>0 then
						if lineFeed>0 then assembledText=joinLang({assembledText, "\n"}) end
						assembledText=joinLang({assembledText, "{en}Greatest Loot: +{ru}Великая добыча: +{zh-cn}至多战利品： +{ko}위대한 전리품: +{es}Mayor Botín: +{fr}Plus Grand Butin: +{pt-br}Maior Saque: +{de}Größte Beute: +", turnOrder[a].score.gLoot})
						lineFeed=lineFeed+1
						totalScore=totalScore+turnOrder[a].score.gLoot
					end
					updateScorePannel("Loot", lineFeed, assembledText)

					--Leader Score
					assembledText="" lineFeed=0
					if turnOrder[a].score.Units>0 then
						assembledText=joinLang({turnOrder[a].score.Units, "{en} Healthy Unit(s): +{ru} Здоровый отряд: +{zh-cn}个健康的部队: +{ko} 보유 유닛: +{es} Unidades Saludables: +{fr} Unités Saines: +{pt-br} Unidades Saudáveis: +{de} Gesunde Einheit(en): +", turnOrder[a].score.UnitsLevel})
						lineFeed=lineFeed+1
						totalScore=totalScore+turnOrder[a].score.UnitsLevel
					end
					if turnOrder[a].score.WoundedUnits>0 then
						if lineFeed>0 then assembledText=joinLang({assembledText, "\n"}) end
						assembledText=joinLang({assembledText, turnOrder[a].score.WoundedUnits, "{en} Wounded Unit(s): +{ru} Раненный отряд: +{zh-cn}个受伤的部队: +{ko} 부상받은 유닛: +{es} Unidades Heridas: +{fr} Unités Blessées: +{pt-br} Unidades Feridas: +{de} Verwundete Einheit(en): +", turnOrder[a].score.WoundedUnitsLevel})
						lineFeed=lineFeed+1
						totalScore=totalScore+turnOrder[a].score.WoundedUnitsLevel
					end
					if turnOrder[a].score.gLeader>0 then
						if lineFeed>0 then assembledText=joinLang({assembledText, "\n"}) end
						assembledText=joinLang({assembledText, "{en}Greatest Leader: +{ru}Великий лидер: +{zh-cn}至高领袖： +{ko}위대한 지도자: +{es}Mayor Líder: +{fr}Plus Grand Chef: +{pt-br}Maior Líder: +{de}Größter Anführer: +", turnOrder[a].score.gLeader})
						lineFeed=lineFeed+1
						totalScore=totalScore+turnOrder[a].score.gLeader
					end
					updateScorePannel("Leader", lineFeed, assembledText)

					--Adventurer Score
					assembledText="" lineFeed=0
					if turnOrder[a].score.Ruin>0 then
						assembledText=joinLang({turnOrder[a].score.Ruin, "{en} Ruin(s): +{ru} Руины: +{zh-cn}个远古遗迹已探索: +{ko} 유적: +{es} Ruinas: +{fr} Ruines: +{pt-br} Ruínas: +{de} Ruine(n): +", turnOrder[a].score.Ruin*2})
						lineFeed=lineFeed+1
						totalScore=totalScore+(turnOrder[a].score.Ruin*2)
					end
					if turnOrder[a].score.DungeonTomb>0 then
						if lineFeed>0 then assembledText=joinLang({assembledText, "\n"}) end
						local b=turnOrder[a].score.DungeonTomb*2
						if gStates.gameScenario=="Dungeon Lords" then
							b=turnOrder[a].score.DungeonTomb*4
						end
						assembledText=joinLang({assembledText, turnOrder[a].score.DungeonTomb, "{en} Dungeon / Tomb(s): +{ru} Подземелье / Гробница: +{zh-cn}个地下城或墓穴已征服: +{ko} 던전과 무덤: +{es} Mazmorras / Tumbas: +{fr} Donjons / Tombeaux: +{pt-br} Masmorras / Tumbas: +{de} Verlies / Grabmal(e): +", b})
						lineFeed=lineFeed+1
						totalScore=totalScore+b
					end
					if turnOrder[a].score.SpawningDen>0 then
						if lineFeed>0 then assembledText=joinLang({assembledText, "\n"}) end
						assembledText=joinLang({assembledText, turnOrder[a].score.SpawningDen, "{en} Den / Spawn Grnd(s): +{ru} Логово / Проклятые земли: +{zh-cn}个怪物巢穴或孵化领地已征服： +{ko} 은신처와 산란지: +{es} Den / Zonas Desove: +{fr} Tanière / Frayère: +{pt-br} Covil / Nascedouro: +{de} Höhle(n) / Laichplatz(e): +", turnOrder[a].score.SpawningDen*2})
						lineFeed=lineFeed+1
						totalScore=totalScore+(turnOrder[a].score.SpawningDen*2)
					end
					if turnOrder[a].score.Maze>0 then
						if lineFeed>0 then assembledText=joinLang({assembledText, "\n"}) end
						assembledText=joinLang({assembledText, turnOrder[a].score.Maze, "{en} Maze / Labyrinth(s): +{ru} Катакомбы / Лабиринт: +{zh-cn}个迷宫或迷城已征服: +{ko} 미로와 미궁: +{es} Maze / Laberintos: +{fr} Maze / Labyrinthes: +{pt-br} Labirintos / Dédalos: +{de} Irrgarten / Labyrinth(e): +", turnOrder[a].score.Maze*2})
						lineFeed=lineFeed+1
						totalScore=totalScore+(turnOrder[a].score.Maze*2)
					end
					if turnOrder[a].score.gAdventurer>0 then
						if lineFeed>0 then assembledText=joinLang({assembledText, "\n"}) end
