						if gStates.defeatedCities.amount==gStates.cityTiles then--+gStates.megapolis
							if lineFeed>0 then assembledText=joinLang({assembledText, "\n"}) end
							assembledText=joinLang({assembledText, "{en}All Cities are Conquered: +15{ru}Все города захвачены: +15{zh-cn}征服了所有城市: +15{ko}모든 도시 정복됨: +15{es}Todas las Ciudades son Conquistadas: +15{fr}Toutes les Villes Sont Conquises: +15{pt-br}Todas Cidades Conquistadas: +15{de}Alle Städte sind erobert: +15"})
							lineFeed=lineFeed+1
							coopScore=coopScore+15
						end
					end
					if gStates.gameScenario=="The Gauntlet" and gStates.endGameAchieved=="true" then
						assembledText="{en}Entered the Red City: +10\nBought the Artifact: +10{ru}Красный город посещен: +10\nАртефакт куплен: +10{zh-cn}进入红色城市： +10\n购买圣器： +10{ko}빨간색 도시 입장: +10\n유물 구입: +10{es}Entró en la Ciudad Roja: +10\nCompró la Reliquia: +10{fr}Entrée dans la Ville Rouge: +10\nAcheté la Relique: +10{pt-br}Entrou na Cidade Vermelha:+10\nComprou a Relíquia: +10{de}Die Rote Stadt betreten: +10\nKaufte das Artefakt: +10"
						lineFeed=2
						coopScore=coopScore+20
					end

					local temp=pannel
					pannel=1
					UI.setAttribute("City1ScoreCell", "columnSpan", "4")
					UI.setAttribute("City1ScoreText", "alignment", "MiddleCenter")
					updateScorePannel("City", lineFeed, assembledText)
					pannel=temp
				end

				--Faction Leader Coop Score
				assembledText="" lineFeed=0
				if (gStates.gameScenario=="Life and Death" or gStates.gameScenario=="Ultimate Conquest") and gStates.coop==1 and gStates.defeatedFaction>0 then
					assembledText=joinLang({gStates.defeatedFaction, "{en} Leader(s) Defeated: +{ru} Лидер побежден: +{zh-cn}个领袖已击败: +{ko} 처치한 지도자: +{es} Líderes Derrotados: +{fr} Chefs Vaincus: +{pt-br} Líderes Derrotados: +{de} Anführer besiegt: +", (gStates.defeatedFaction*10)})
					lineFeed=lineFeed+1
					coopScore=coopScore+(gStates.defeatedFaction*10)
					if gStates.defeatedFaction==2 then
						if lineFeed>0 then assembledText=joinLang({assembledText, "\n"}) end
						assembledText=joinLang({assembledText, "{en}Both Leaders are defeated: +15{ru}Оба Лидера побеждены: +15{zh-cn}两位领袖都被击败: +15{ko}모든 지도자 처치됨: +15{es}Ambos Líderes son Derrotados: +15{fr}Les deux Chefs sont Vaincus: +15{pt-br}Ambos líderes derrotados: +15{de}Beide Anführer sind besiegt: +15"})
						lineFeed=lineFeed+1
						coopScore=coopScore+15
						if gStates.playersRef~=5 then
							if gStates.allPlayersFoughtAFactionLeaderCheck==true then
								if lineFeed>0 then assembledText=joinLang({assembledText, "\n"}) end
								assembledText=joinLang({assembledText, "{en}Every player helped defeat a Leader: +10{ru}Каждый игрок помог победить Лидера: +10{zh-cn}每个玩家都帮助击败了一个领袖: +10{ko}모든 플레이어가 지도자 처치에 참여: +10{es}Cada Jugador Ayudó a Derrotar a un Líder: +10{fr}Chaque Joueur a Aidé à Vaincre un Leader: +10{pt-br}Cada Jogador ajudou a derrotar um Líder: +10{de}Jeder Spieler hat geholfen, einen Anführer zu besiegen: +10"})
								lineFeed=lineFeed+1
								coopScore=coopScore+10
							end
							if gStates.allPlayersFoughtBothFactionLeaderCheck==true then
								if lineFeed>0 then assembledText=joinLang({assembledText, "\n"}) end
								assembledText=joinLang({assembledText, "{en}Every player helped defeat Both Leaders: +10{ru}Каждый игрок помог победить обоих Лидеров: +10{zh-cn}每个玩家都帮助击败了两个领袖: +10{ko}모든 플레이어가 두 지도차 처치에 참여: +10{es}Cada Jugador Ayudó a Derrotar a Ambos Líderes: +10{fr}Chaque Joueur a Aidé à Vaincre les Deux Leaders: +10{pt-br}Cada Jogador ajudou a derrotar ambos Líderes: +10{de}Jeder Spieler hat geholfen, beide Anführer zu besiegen: +10"})
								lineFeed=lineFeed+1
								coopScore=coopScore+10
							end
						end
					end
				end
				if gStates.gameScenario=="The Realm of the Dead Blitz" and gStates.coop==1 then
					if gStates.defeatedFaction>0 then
						assembledText="{en}Necromancer is Defeated: +10{ru}Некромант побежден: +10{zh-cn}亡灵法师被击败: +10{ko}네크로맨서 처치됨: +10{es}Nigromante es Derrotado: +10{fr}Nécromancien est Vaincu: +10{pt-br}Necromante derrotado: +10{de}Nekromant ist besiegt: +10"
						lineFeed=lineFeed+1
						coopScore=coopScore+10
					end
					if coopGraveYard>0 then
						if lineFeed>0 then assembledText=joinLang({assembledText, "\n"}) end
						assembledText=joinLang({assembledText, coopGraveYard, "{en} Graveyard(s) sealed: +{ru} Кладбище запечатано: +{zh-cn}个墓穴已封印: +{ko} 봉인된 묘지: +{es} Cementerios Sellados: +{fr} Cimetières Scellés: +{pt-br} Cemitérios Selados: +{de} Friedhof(e) versiegelt: +", (coopGraveYard*5)})
						lineFeed=lineFeed+1
						coopScore=coopScore+(coopGraveYard*5)
					end
					if gStates.defeatedFaction>0 and coopGraveYard>=gStates.playerCount+1 then
						if lineFeed>0 then assembledText=joinLang({assembledText, "\n"}) end
						assembledText=joinLang({assembledText, "{en}Necromancer defeated & Graveyards sealed: +10{ru}Некромант побежден & Кладбища запечатаны: +10{zh-cn}亡灵法师被击败并封印墓穴: +10{ko}네크로맨서 처치 & 묘지 봉인됨: +10{es}Nigromante derrotado y Cementerios sellados: +10{fr}Nécromancien vaincu & Cimetières scellés: +10{pt-br}Necromante derrotado e Cemitérios Selados: +10{de}Nekromant besiegt & Friedhöfe versiegelt: +10"})
						lineFeed=lineFeed+1
						coopScore=coopScore+10
					end
				end
				if (gStates.gameScenario=="The Realm of the Dead Blitz" or gStates.gameScenario=="The Hidden Valley Blitz") and gStates.coop==1 and gStates.playersRef~=5 and gStates.allPlayersFoughtAFactionLeaderCheck==true and gStates.defeatedFaction>0 then
					if lineFeed>0 then assembledText=joinLang({assembledText, "\n"}) end
					assembledText=joinLang({assembledText, "{en}Every player helped defeat the Leader: +20{ru}Каждый игрок помог победить Лидера: +20{zh-cn}所有玩家都帮助击败了首领: +20{ko}모든 플레이어가 지도자 처치에 참여: +20{es}Todos los Jugadores Ayudaron a Derrotar al Líder: +20{fr}Chaque Joueur a Aidé à Vaincre le Leader: +20{pt-br}Cada Jogador ajudou a derrotar o Líder: +20{de}Jeder Spieler hat geholfen, den Anführer zu besiegen: +20"})
					lineFeed=lineFeed+1
					coopScore=coopScore+20
				end
				if gStates.gameScenario=="The Hidden Valley Blitz" and gStates.coop==1 and gStates.defeatedFaction>0 then
					if lineFeed>0 then assembledText=joinLang({assembledText, "\n"}) end
					assembledText=joinLang({assembledText, "{en}Defeated the High Priestess: +20{ru}Верховная Жрица побеждена: +20{zh-cn}击败高阶祭司: +20{ko}하이 프리스트 처치됨: +20{es}Derrota a la Suma Sacerdotisa: +20{fr}Vaincre la Grande Prêtresse: +20{pt-br}Derrotou a Alta Sacerdotiza: +20{de}Die Hohepriesterin besiegt: +20"})
					lineFeed=lineFeed+1
					coopScore=coopScore+20
				end
				local temp=pannel
				pannel=1
				UI.setAttribute("TezlaScoreHeadingText", "text", "{en}Faction Scoring{ru}Подсчет очков фракций{zh-cn}派系得分{ko}세력 점수{es}Puntuación de Facción{fr}Décompte des Factions{pt-br}Pontuação de Facção{de}Faction-Wertung")
				UI.setAttribute("Tezla1ScoreCell", "columnSpan", "4")
				UI.setAttribute("Tezla1ScoreText", "alignment", "MiddleCenter")
				updateScorePannel("Tezla", lineFeed, assembledText)
				pannel=temp

				--Total Score
				UI.setAttribute("CoopScoreData", "active", "true")
				UI.setAttribute("CoopScoreText", "text", joinLang({"{en}Final Fame: {ru}Итого Славы: {zh-cn}最终名望: {ko}최종 명성: {es}Fama Final: {fr}Gloire Finale: {pt-br}Fama Final: {de}Endgültiger Ruhm: ", coopScore}))
				for count=1, #turnOrder-1 ,1 do
					turnOrder[count].score.finalScore=coopScore
				end
			end
		end

		--final scoreboard tweaks
		UI.show("ScoreBoard")
		local visibility=""
		if player~="all" then
			scoreViewing[#scoreViewing+1]=player.color
			for a=1, #scoreViewing, 1 do
				visibility=visibility..scoreViewing[a]
				if a<#scoreViewing then visibility=visibility.."|" end
			end
		end
		UI.setAttribute("ScoreBoard", "visibility", visibility)
		for a, b in pairs(heights) do
			if b>24 then totalHeight=totalHeight+30 end
		end
		UI.setAttribute("ScoreBoard", "height", totalHeight)
		UI.setAttribute("ScoreBoard", "width", (pannel-1)*280)
		if gStates.playersRef==5 then
			UI.setAttribute("ScoreBoard", "width", 400)
			UI.setAttribute("ScoreBoardTable", "columnWidths", "400")
		end
		if gameOver==true and gStates.scoreRecorded==false then UI.show("SendScoreRequest") gStates.scoreRecorded=true end
		table.sort(turnOrder, function (k1, k2) return k1.tactic<k2.tactic end)
	end
end

function cityBeatCheck()
	--Figure out who leads and assisted in cities
	local leadTest={}
	local factionAssistTest={}
	local bothTest=0

	gStates.allPlayersFoughtAFactionLeaderCheck=false
	gStates.allPlayersFoughtBothFactionLeaderCheck=false
	gStates.allLeaderCheck=false
	gStates.defeatedFaction=0
	gStates.defeatedCities={amount=0}
	gStates.defeatedFactionTest={}
	--Zero out any existing scores
	local scoreVariable={"CityLead", "CityAssist", "ElemFactionAssist", "DarkFactionAssist", "ElemFactionLead", "DarkFactionLead"}
	for a=1, #turnOrder, 1 do
		turnOrder[a].defeatedCities={}
		for b, c in pairs(scoreVariable) do
			turnOrder[a].score[c]=0
		end
	end
	--read each city
	for cityZone, cityStuff in pairs(cityScriptZones) do
		if gStates.defeatedCities[cityStuff.cityGUID]==nil then gStates.defeatedCities[cityStuff.cityGUID]=false end
		if gStates.cityMonsterQty[cityStuff.cityGUID]~=nil and gStates.cityMonsterQty[cityStuff.cityGUID].extra~=nil and gStates.cityMonsterQty[cityStuff.cityGUID].extra.megapolisPair~=cityStuff.cityGUID then
			if getObjectFromGUID(cityZone)~=nil then
				local count=0
				local firstShield=true
				local objectsOnCity=getObjectFromGUID(cityZone).getObjects()
				--add megapolis second city items
				if gStates.cityMonsterQty[cityStuff.cityGUID].extra.megapolisPair~=nil then
					for cityZone2, cityStuff2 in pairs(cityScriptZones) do
						if cityStuff2.cityGUID==gStates.cityMonsterQty[cityStuff.cityGUID].extra.megapolisPair then
							for _, Object in pairs(getObjectFromGUID(cityZone2).getObjects()) do
								local found=false
								for _, testObject in pairs(objectsOnCity) do
									if testObject.guid==Object.guid then found=true end
								end
								if found==false then objectsOnCity[#objectsOnCity+1]=Object end
							end
						end
					end
				end
				--Sort objects in city zones
				if cityZone==darkCrusader.discZone or cityZone==elementalist.discZone then
					--counter clockwise from the top position
					local tilePos=getObjectFromGUID(cityZone).getPosition()
					table.sort(objectsOnCity, function(k1, k2)
						local rot=math.rad(90)
						local Var1=math.atan2(((k1.getPosition()[3]-tilePos[3])*math.cos(rot))+((k1.getPosition()[1]-tilePos[1])*math.sin(rot)), ((k1.getPosition()[1]-tilePos[1])*math.cos(rot))-((k1.getPosition()[3]-tilePos[3])*math.sin(rot)))
						local Var2=math.atan2(((k2.getPosition()[3]-tilePos[3])*math.cos(rot))+((k2.getPosition()[1]-tilePos[1])*math.sin(rot)), ((k2.getPosition()[1]-tilePos[1])*math.cos(rot))-((k2.getPosition()[3]-tilePos[3])*math.sin(rot)))
						return Var1 < Var2
					end)
				else
					--from left to right
					table.sort(objectsOnCity, function (k1, k2) return k1.getPosition()[1]<k2.getPosition()[1] end)
				end
				--count shields found in city zone
				local cityScoring={}
				for a, shield in pairs(objectsOnCity) do
					if shield.getName()=="Shield" then
						if cityScoring[shield.getDescription()]~=nil then
							cityScoring[shield.getDescription()]=cityScoring[shield.getDescription()]+1
						else
							if firstShield==true then cityScoring[shield.getDescription()]=1.5 firstShield=false else cityScoring[shield.getDescription()]=1 end
						end
						count=count+1
					end
				end
				--add grave yards and glades to Faction ammounts
				if (cityZone==darkCrusader.discZone or cityZone==elementalist.discZone) and (gStates.coop==0 or gStates.WarOfFourComp==true) then
					for c=1, #turnOrder, 1 do
						if turnOrder[c].mage~=gStates.positionMageKnight[5] then
							if cityScoring[turnOrder[c].mage]==nil then cityScoring[turnOrder[c].mage]=0 end
							--if turnOrder[c].score.GraveYard==nil then turnOrder[c].score.GraveYard=0 end
							--if turnOrder[c].score.Glade==nil then turnOrder[c].score.Glade=0 end
							if cityZone==elementalist.discZone then cityScoring[turnOrder[c].mage]=cityScoring[turnOrder[c].mage]+turnOrder[c].score.Glade end
							if cityZone==darkCrusader.discZone then cityScoring[turnOrder[c].mage]=cityScoring[turnOrder[c].mage]+turnOrder[c].score.GraveYard end
						end
					end
				end
				--Work out Leader for City
				local highest={0, nil}
				local beaten=true
				for _, state in pairs(gStates.cityMonsterQty[cityStuff.cityGUID]) do
					if state=="alive" then beaten=false break end
				end
				if beaten==true then
					if gStates.gameScenario=="The War of Four" and cityZone~=darkCrusader.discZone and cityZone~=elementalist.discZone then--needs to be recorded when beaten not when revealed.
						local found=false
						for _, city in pairs(gStates.cityRevealed) do if city.model==cityStuff.cityGUID then found=true end end
						if found==false then gStates.cityRevealed[#gStates.cityRevealed+1]={model=cityStuff.cityGUID, terrain=gStates.cityMonsterQty[cityStuff.cityGUID].extra.terainGUID} end
					end
					if cityStuff.cityGUID~=darkCrusader.terrainHex and cityStuff.cityGUID~=elementalist.terrainHex then
						if gStates.cityLevels[gStates.cityDeployOrder[cityStuff.cityGUID]]~=0 then gStates.defeatedCities.amount=gStates.defeatedCities.amount+1 gStates.defeatedCities[cityStuff.cityGUID]=true end
						if gStates.cityMonsterQty[cityStuff.cityGUID].extra.megapolisPair~=nil then gStates.defeatedCities[gStates.cityMonsterQty[cityStuff.cityGUID].extra.megapolisPair]=true end
						--Assign lead and assist values to player scores
						for d, e in pairs(cityScoring) do
							for c=1, #turnOrder, 1 do
								if turnOrder[c].mage==d then
									turnOrder[c].score.CityAssist=turnOrder[c].score.CityAssist+1
									turnOrder[c].defeatedCities[cityStuff.cityGUID]="Assist"
									if gStates.cityMonsterQty[cityStuff.cityGUID].extra.megapolisPair~=nil then turnOrder[c].defeatedCities[gStates.cityMonsterQty[cityStuff.cityGUID].extra.megapolisPair]="Assist" end
									if highest[1]<e then highest[1]=e highest[2]=d end
									break
								end
							end
						end
						for c=1, #turnOrder, 1 do
							if turnOrder[c].mage==highest[2] then
								turnOrder[c].score.CityAssist=turnOrder[c].score.CityAssist-1
								turnOrder[c].score.CityLead=turnOrder[c].score.CityLead+1
								turnOrder[c].defeatedCities[cityStuff.cityGUID]="Lead"
								if gStates.cityMonsterQty[cityStuff.cityGUID].extra.megapolisPair~=nil then turnOrder[c].defeatedCities[gStates.cityMonsterQty[cityStuff.cityGUID].extra.megapolisPair]="Lead" end
								leadTest[c]=true
								break
							end
						end
					else
						gStates.defeatedFaction=gStates.defeatedFaction+1
						gStates.defeatedFactionTest[cityStuff.cityGUID]="Beat"
					end
				end
				--Faction Leader
				if cityZone==darkCrusader.discZone or cityZone==elementalist.discZone then
					local factionBothAssistTest={}
					for d, e in pairs(cityScoring) do
						if e>0 then
							for c=1, #turnOrder, 1 do
								if turnOrder[c].mage==d then
									if cityZone==elementalist.discZone then turnOrder[c].score.ElemFactionAssist=turnOrder[c].score.ElemFactionAssist+1 end
									if cityZone==darkCrusader.discZone then turnOrder[c].score.DarkFactionAssist=turnOrder[c].score.DarkFactionAssist+1 end
									if highest[1]<e then highest[1]=e highest[2]=d end
									factionAssistTest[turnOrder[c].mage]=true
									factionBothAssistTest[turnOrder[c].mage]=true
									break
								end
							end
						end
					end
					for c=1, #turnOrder, 1 do
						if turnOrder[c].mage==highest[2] then
							if cityZone==darkCrusader.discZone then
								turnOrder[c].score.DarkFactionAssist=turnOrder[c].score.DarkFactionAssist-1
								turnOrder[c].score.DarkFactionLead=turnOrder[c].score.DarkFactionLead+1
							end
							if cityZone==elementalist.discZone then
								turnOrder[c].score.ElemFactionAssist=turnOrder[c].score.ElemFactionAssist-1
								turnOrder[c].score.ElemFactionLead=turnOrder[c].score.ElemFactionLead+1
							end
							break
						end
					end
					--All Players fought Both Leader Check
					local count=0
					for a, b in pairs (factionBothAssistTest) do count=count+1 end
					if count==#turnOrder-1 then bothTest=bothTest+1 end
				end
			end
		end
	end
	--All players are city Leaders Check
	local count=0
	for a, b in pairs (leadTest) do count=count+1 end
	if count==#turnOrder-1 then gStates.allLeaderCheck=true end
	--All players fought both leaders check
	if bothTest==2 then gStates.allPlayersFoughtBothFactionLeaderCheck=true end
	--All Players fought a Leader Check
	local count=0
	for a, b in pairs (factionAssistTest) do count=count+1 end
	if count==#turnOrder-1 then gStates.allPlayersFoughtAFactionLeaderCheck=true end
end

function SendDataRequest(player, mouseButton, id)
	if mouseButton=="-1" and (player=="skip" or Player[player.color].admin==true) then
		UI.setAttribute("SendDataRequest", "active", "false")
		UI.setAttribute("SendBugRequest", "active", "false")
		UI.setAttribute("SendScoreRequest", "active", "false")
		if id=="SendDataRequestYes" or id=="SendBugRequestYes" or id=="SendScoreRequestYes" then
			local STAT_URL="https://script.google.com/macros/s/AKfycbzwG2H6x5om4JZ0K4S0y7f6TBBvp9VP9EGnIgxd3Nrs-4RVT5xgntE_WKVzcT1tK2JfNg/exec"
			if id=="SendBugRequestYes" then STAT_URL="https://script.google.com/macros/s/AKfycbzU1dSg2mafsUbUTNqOHce0cdWId2I8fkYiNO1JUgG73wtV9E2DCvm7uZ02bXviO-vnFw/exec" end
			if id=="SendScoreRequestYes" then STAT_URL="https://script.google.com/macros/s/AKfycbzLnjL_IH1gOb1hwgfDLrnrsnRkHM9bve20ph4PVqViMe5lhYtBzTOndL4T6DWo4HFXbQ/exec" end
			log("Writing stats.")
			local GameRecord={gameScenario=gStates.gameScenario,
				blitz=gStates.blitz,
				rounds=scenarioList[gStates.scenarioRef][gStates.playersRef].rounds,
				mapShape=scenarioList[gStates.scenarioRef][gStates.playersRef].mapShape,
				countryTiles=scenarioList[gStates.scenarioRef][gStates.playersRef].countryTiles,
				coreTiles=scenarioList[gStates.scenarioRef][gStates.playersRef].coreTiles,
				cityTiles=scenarioList[gStates.scenarioRef][gStates.playersRef].cityTiles,
				randomTileOrientation=gStates.randomTileOrientation,
				volkareCampAsCity=gStates.volkareCampAsCity,
				megapolis=gStates.megapolis,
				randomCities=gStates.randomCities,
				positionMageKnight1=gStates.positionMageKnight[1],
				positionMageKnight2=gStates.positionMageKnight[2],
				positionMageKnight3=gStates.positionMageKnight[3],
				positionMageKnight4=gStates.positionMageKnight[4],
				positionMageKnight5=gStates.positionMageKnight[5],
				includeYmirgh=gStates.includeYmirgh,
				dummyAllSkills=gStates.dummyAllSkills,
				mageKnightLevels=gStates.mageKnightLevels,
				rampagePursuit=gStates.rampagePursuit,
				rampageAmbush=gStates.rampageAmbush,
				rampage=gStates.rampage,
				removeLostLegionExpansion=gStates.removeLostLegionExpansion,
				shadesOfTezlaPugs=gStates.shadesOfTezlaPugs,
				removeBonusCards=gStates.removeBonusCards,
				volkareCombatLevel=" ",
				volkareRaceLevel=" ",
				darknessComing=gStates.darknessComing,
				startAtNight=gStates.startAtNight,
				questMod=gStates.questMod,
				weatherMod=gStates.weatherMod,
				itemShopMod=gStates.itemShopMod,
				removeTerrain=gStates.removeTerrain,
				useAlternatePugs=gStates.useAlternatePugs,
				riseOfTheForgemasters=gStates.riseOfTheForgemasters,
				autoFlip=gStates.autoFlip,
				offerSize=gStates.offerSize}
			if GameRecord.mapShape=="{en}Open Limited to 4 Columns{ru}Открытое поле с ограничением в 4 ряда{zh-cn}地图限制为 4 列{ko}4열 제한{es}Abierto Limitado a 4 Columnas{fr}Ouvert Limité à 4 Colonnes{pt-br}Aberto Limitado a 4 Colunas{de}Offen Begrenzt auf 4 Spalten" then GameRecord.mapShape="4 Columns" end
			if GameRecord.mapShape=="{en}Open Limited to 3 Columns{ru}Открытое поле с ограничением в 3 ряда{zh-cn}地图限制为 3 列{ko}3열 제한{es}Abierto Limitado a 3 Columnas{fr}Ouvert Limité à 3 Colonnes{pt-br}Aberto Limitado a 3 Colunas{de}Offen Begrenzt auf 3 Spalten" then GameRecord.mapShape="3 Columns" end
			if GameRecord.mapShape=="{en}Wedge with No Limitations{ru}Клиновидное поле без ограничений{zh-cn}随机板块方向{ko}쐐기형(무제한){es}En Cuña sin Límites{fr}Coin sans Limites{pt-br}Cônico sem Limitações{de}Keil ohne Begrenzungen" then GameRecord.mapShape="Wedge" end
			if GameRecord.mapShape=="{en}Wedge{ru}Клиновидное поле{zh-cn}锥形地图{ko}쐐기형{es}En Cuña{fr}Coin{pt-br}Cônico{de}Keil" then GameRecord.mapShape="Wedge" end
			if GameRecord.mapShape=="{en}Fully Open{ru}Полностью открытое поле{zh-cn}完全开放地图{ko}전체 개방형{es}Totalmente Abierto{fr}Entièrement Ouvert{pt-br}Totalmente Aberto{de}Vollständig Offen" then GameRecord.mapShape="Fully Open" end
			if GameRecord.mapShape=="{en}Predefined{ru}Предопределенное поле{zh-cn}按剧本预设{ko}미리 정해짐{es}Predefinido{fr}Prédéfini{pt-br}Pré-definido{de}Vordefiniert" then GameRecord.mapShape="Predefined" end
			if gStates.positionMageKnight[5]=="Volkare" then
				GameRecord.volkareCombatLevel=gStates.volkareCombatLevel
				GameRecord.volkareRaceLevel=gStates.volkareRaceLevel
			end
			GameRecord["cityLevel"]="[ "
			for a, b in pairs(gStates.cityLevels) do
				GameRecord["cityLevel"]=GameRecord["cityLevel"]..tostring(b).." "
			end
			for a=1, 5, 1 do
				if gStates.originalChoiceMageKnights[a]=="Random" or gStates.originalChoiceMageKnights[a]=="All Skills" then GameRecord["positionMageKnight"..tostring(a)]=GameRecord["positionMageKnight"..tostring(a)].." [R]" end
			end
			GameRecord["cityLevel"]=GameRecord["cityLevel"].."]"
			GameRecord["Comment"]=UI.getAttribute("SendBugComment", "text")
			if id=="SendScoreRequestYes" then GameRecord["Comment"]=UI.getAttribute("SendScoreComment", "text") end
			local count=0
			for index, color in pairs(Player.getAvailableColors()) do
				if Player[color].seated==true then count=count+1 end
			end
			if Player["Black"].seated==true then count=count+1 end
			GameRecord.multihand=false
			if count==1 and gStates.playerCount>1 then GameRecord.multihand=true end
			if gStates.playerCount==1 then GameRecord.gameType="Solo" end
			if gStates.playerCount>1 and (gStates.coop==0 or gStates.WarOfFourComp==true) then GameRecord.gameType="Comp" end
			if gStates.playerCount>1 and (gStates.coop==1 and gStates.WarOfFourComp==false) then GameRecord.gameType="Coop" end
			if getObjectFromGUID("519f96").getScale().x==1 then GameRecord["table"]="Original" else GameRecord["table"]="New" end
			if id=="SendBugRequestYes" then GameRecord["reporter"]=Player[player.color].steam_name end
			for _, playerDetails in pairs(turnOrder) do
				--if playerDetails.score==nil then playerDetails["score"]={["finalScore"]=0} end
				if playerDetails.score.finalScore==nil then playerDetails.score.finalScore=0 end
			end
			table.sort(turnOrder, function (k1, k2) return k1.score.finalScore>k2.score.finalScore end)
			if id=="SendScoreRequestYes" then for c=1, 4, 1 do GameRecord["positionMageKnight"..c]="" end end
			for playerNo=1, #turnOrder, 1 do
				for _, color in pairs(Player.getAvailableColors()) do
					local colorPos=math.ceil((Player[color].getHandTransform().position[1]+97.59)/40)
					if turnOrder[playerNo].seatPos==colorPos then
						--steam user name
						if gStates.positionMageKnight[colorPos]~="nobody" then
							local recordPos=colorPos
							if id=="SendScoreRequestYes" then recordPos=playerNo end
							GameRecord["steamName"..recordPos]=Player[color].steam_name
							if GameRecord["steamName"..recordPos]==nil then
								if player.color~=nil then GameRecord["steamName"..recordPos]=Player[player.color].steam_name end
								if player.color==nil then GameRecord["steamName"..recordPos]=Player["black"].steam_name end
								if GameRecord["steamName"..recordPos]==nil then GameRecord["steamName"..recordPos]="No Player" end
							end
						end
						if id=="SendScoreRequestYes" then
							--Mage knight used
							GameRecord["positionMageKnight"..playerNo]=gStates.positionMageKnight[colorPos]
							if GameRecord["positionMageKnight"..playerNo]=="nobody" then GameRecord["positionMageKnight"..playerNo]="" end
							--score achieved
							GameRecord["score"..playerNo]=turnOrder[playerNo].score.finalScore
							if GameRecord["score"..playerNo]==0 then GameRecord["score"..playerNo]="" end
							if GameRecord["riseOfTheForgemasters"]==0 then GameRecord["riseOfTheForgemasters"]="" end
						end
						break
					end
				end
			end
			table.sort(turnOrder, function (k1, k2) return k1.tactic<k2.tactic end)
			WebRequest.post(STAT_URL, GameRecord, function(w)
				log(w.text)
				if id=="SendBugRequestYes" or id=="SendScoreRequestYes" then
					broadcastToAll("{en}Data Received, Thank You{ru}Данные получены, спасибо!{zh-cn}数据已收到，谢谢{ko}데이터 수신 완료. 감사합니다.{es}Datos Recibidos, Gracias{fr}Données Reçues, Merci{pt-br}Dados recebidos, obrigado{de}Daten Erfasst, Danke", {1,1,0.5})
				end
			end)
		end
	end
end

function SetupMenu(player, mouseButton, id)
	if mouseButton=="-1" then
		UI.setAttribute("Setup", "active", "true")
		UI.setAttribute("helpButtonRealImage", "image", "Sliced Button/Button New Deactive")
		UI.setAttribute("helpButtonReal", "interactable", "false")
		--UI.hide("HelpButton")
	end
end

