	local baseValues={	HealiAmountPlainText=joinLang({"{en}Healing : {ru}Лечение: {zh-cn}治疗：{ko}치유 : {es}Curación : {fr}Guérison : {pt-br}Cura : {de}Heilung : ", gStates.resourceTracker.healing.healing}),
