							AttacAmountIcexxText=joinLang({"{en}Ice : {ru}Ледяная(ой): {zh-cn}寒冰：{ko}얼음 : {es}Hielo : {fr}Glace : {pt-br}Gelo : {de}Eis : ", gStates.resourceTracker.attack.ice}),
							AttacAmountColdFText=joinLang({"{en}Cold Fire : {ru}Холодный огонь: {zh-cn}冰火：{ko}차가운 불 : {es}Fuego Frío :{fr}Feu Froid : {pt-br}Fogo Frio : {de}Kaltes Feuer : ", gStates.resourceTracker.attack.iceFire}),
						InfluAmountPlainText=joinLang({"{en}Influence : {ru}Влияние: {zh-cn}影响力：{ko}영향력 : {es}Influencia : {fr}Influence : {pt-br}Influência : {de}Beeinflussung : ", resourceTotal.influence}),
							InfluAmountPhysiText=joinLang({"{en}Generated : {ru}Сгенерировано: {zh-cn}产生的：{ko}사용 : {es}Generación : {fr}Généré : {pt-br}Gerado : {de}Erzeugt : ", gStates.resourceTracker.influence.generated}),
							InfluAmountReputText=joinLang({"{en}Generated : {ru}Сгенерировано: {zh-cn}产生的：{ko}사용 : {es}Generación : {fr}Généré : {pt-br}Gerado : {de}Erzeugt : ", gStates.resourceTracker.influence.reputation}),
							InfluAmountCitySText=joinLang({"{en}City Shields : {ru}Щиты на городе: {zh-cn}城防：{ko}도시 방패 토큰 : {es}Escudos de la Ciudad : {fr}Boucliers de Ville : {pt-br}Escudos das Cidades : {de}Stadtschilde : ", gStates.resourceTracker.influence.cityShields}),
						MovemAmountPlainText=joinLang({"{en}Move : {ru}Движение: {zh-cn}移动：{ko}이동 : {es}Mover : {fr}Se déplacer : {pt-br}Mover : {de}Bewegen : ", gStates.resourceTracker.move.move}),
							MoveCostPlainText=joinLang({"{en}Plains : {ru}Равнины: {zh-cn}平原：{ko}평지 :{es}Llanuras : {fr}Plaines : {pt-br}Planícies : {de}Ebenen : ", gStates.moveCost.plains}),
							MoveCostHillsText=joinLang({"{en}Hills : {ru}Холмы: {zh-cn}山丘：{ko}언덕 : {es}Colinas : {fr}Collines : {pt-br}Colinas : {de}Hügel : ", gStates.moveCost.hills}),
							MoveCostForesText=joinLang({"{en}Forests : {ru}Леса: {zh-cn}森林：{ko}숲 : {es}Bosques : {fr}Forêts : {pt-br}Florestas : {de}Wälder : ", gStates.moveCost.forest}),
							MoveCostWasteText=joinLang({"{en}Wastelands : {ru}Пустоши: {zh-cn}废土：{ko}황무지 : {es}Páramos : {fr}Terrains Vagues : {pt-br}Terras Devastadas : {de}Ödland : ", gStates.moveCost.wasteland}),
							MoveCostDeserText=joinLang({"{en}Deserts : {ru}Пустыни: {zh-cn}沙漠：{ko}사막 : {es}Desiertos : {fr}Déserts : {pt-br}Desertos : {de}Wüsten : ", gStates.moveCost.desert}),
							MoveCostSwampText=joinLang({"{en}Swamps : {ru}Болота: {zh-cn}沼泽：{ko}늪 : {es}Pantanos : {fr}Marécages : {pt-br}Pântanos : {de}Sümpfe : ", gStates.moveCost.swamp}),
							MoveCostLakesText=joinLang({"{en}Lakes : {ru}Озера: {zh-cn}湖泊：{ko}호수 : {es}Lagos : {fr}Lacs : {pt-br}Lagos : {de}Seen : ", lake}),
							MoveCostMountText=joinLang({"{en}Mountains : {ru}Горы: {zh-cn}山脉：{ko}산 : {es}Montañas : {fr}Montagnes : {pt-br}Montanhas : {de}Berge : ", mountain})}
	for element, value in pairs(baseValues) do
		UI.setAttribute(element, "text", value)
	end
end

function updateMoveDisplay(id)
	--remove existing hex markers
	local existingDecals=Global.getDecals()
	local cleanedDecals={}
	if existingDecals~=nil then
		for set, decal in pairs(existingDecals) do
			if decal.name~="Hex Highlight" then cleanedDecals[#cleanedDecals+1]=decal end
		end
	end
	Global.setDecals(cleanedDecals)

	--create a digital map of the existing terrain tiles
	if gStates.resourceTracker.move.move>0 then
		local startTileGUID=startTerrain.open
		if getObjectFromGUID(startTileGUID)==nil then startTileGUID=startTerrain.wedge end
		local playAreaObjects=getObjectFromGUID(mapArea).getObjects()
		local hexMap={}
		for _, mightBeMap in pairs(playAreaObjects) do
			--record a terrain tile found.
			if terrainTiles[mightBeMap.guid]~=nil and mightBeMap.is_face_down==false then
				--work out where tile is in relation to portal tile and convert to Axial Hex Grid coordinate
				local terTile=mightBeMap.getPosition()
				local hexGridHorizontal=math.floor(((terTile[3]-getObjectFromGUID(startTileGUID).getPosition()[3])/2.0785)+0.5)
				local hexGridAxial=math.floor(((terTile[1]-getObjectFromGUID(startTileGUID).getPosition()[1])/2.4)+(hexGridHorizontal/2)+0.5)

				--loop through all the hexes on the tile
				local terrainRotationAdjust=(math.floor(((mightBeMap.getRotation()[2]-180)/60)+0.5)*60)
				if terrainRotationAdjust<0 then terrainRotationAdjust=terrainRotationAdjust+360 end
				local bearingAdjust={center={0,0}, ["0"]={0,-1}, ["60"]={-1,-1}, ["120"]={-1,0}, ["180"]={0,1}, ["240"]={1,1}, ["300"]={1,0}}
				for hexBearing, hexType in pairs(terrainTiles[mightBeMap.guid].hexType) do
					local fixedBearing="center"
					if hexBearing~="center" then fixedBearing=tostring(tonumber(hexBearing)-terrainRotationAdjust) end
					if fixedBearing~="center" and tonumber(fixedBearing)<0 then fixedBearing=tostring(tonumber(fixedBearing)+360) end
					if hexMap[tostring(hexGridHorizontal+bearingAdjust[fixedBearing][1])]==nil then hexMap[tostring(hexGridHorizontal+bearingAdjust[fixedBearing][1])]={} end
					if hexMap[tostring(hexGridHorizontal+bearingAdjust[fixedBearing][1])][tostring(hexGridAxial+bearingAdjust[fixedBearing][2])]==nil then hexMap[tostring(hexGridHorizontal+bearingAdjust[fixedBearing][1])][tostring(hexGridAxial+bearingAdjust[fixedBearing][2])]={hexType=hexType} end
					--record if hex is a fortified site
					if (terrainTiles[mightBeMap.guid].hexFeature[hexBearing]=="keep" or terrainTiles[mightBeMap.guid].hexFeature[hexBearing]=="mage tower") and hexMap[tostring(hexGridHorizontal)][tostring(hexGridAxial)].fortified==nil then
						hexMap[tostring(hexGridHorizontal+bearingAdjust[fixedBearing][1])][tostring(hexGridAxial+bearingAdjust[fixedBearing][2])].fortified=terrainTiles[mightBeMap.guid].hexFeature[hexBearing]
					end
				end
				--record walls as 0.5 on the grid
				if terrainTiles[mightBeMap.guid].wallList~=nil then
					for hexBearing, hexAdjacent in pairs(terrainTiles[mightBeMap.guid].wallList) do
						for hexAdjacentBearing, _ in pairs(hexAdjacent) do
							local fixedBearing="center"
							if hexBearing~="center" then fixedBearing=tostring(tonumber(hexBearing)-terrainRotationAdjust) end
							if fixedBearing~="center" and tonumber(fixedBearing)<0 then fixedBearing=tostring(tonumber(fixedBearing)+360) end
							local fixedAdjacentBearing="center"
							if hexAdjacentBearing~="center" then fixedAdjacentBearing=tostring(tonumber(hexAdjacentBearing)-terrainRotationAdjust) end
							if fixedAdjacentBearing~="center" and tonumber(fixedAdjacentBearing)<0 then fixedAdjacentBearing=tostring(tonumber(fixedAdjacentBearing)+360) end
							local bearingAdjacentAdjust={	["0"]=		{["300"]=	{0.5,-0.5},	["center"]=	{0,-0.5}, 	["60"]=	{-0.5,-0.5}},
															["60"]=		{["0"]=		{-0.5,-1},	["center"]=	{-0.5,-0.5},["120"]={-1,-0.5}},
															["120"]=	{["60"]=	{-1,-0.5}, 	["center"]=	{-0.5,0}, 	["180"]={-0.5,0.5}},
															["180"]=	{["120"]=	{-0.5,0.5},	["center"]=	{0,0.5}, 	["240"]={0.5,1}},
															["240"]=	{["180"]=	{0.5,1}, 	["center"]=	{0.5,0.5},	["300"]={1,0.5}},
															["300"]=	{["240"]=	{1,0.5}, 	["center"]=	{0.5,0}, 	["0"]=	{0.5,-0.5}},
															["center"]=	{["0"]=		{0,-0.5}, 	["60"]=		{-0.5,-0.5},["120"]={-0.5,0}, ["180"]={0,0.5}, ["240"]={0.5,0.5}, ["300"]={0.5,0}}}
							if hexMap[tostring(hexGridHorizontal+bearingAdjacentAdjust[fixedBearing][fixedAdjacentBearing][1])]==nil then hexMap[tostring(hexGridHorizontal+bearingAdjacentAdjust[fixedBearing][fixedAdjacentBearing][1])]={} end
							hexMap[tostring(hexGridHorizontal+bearingAdjacentAdjust[fixedBearing][fixedAdjacentBearing][1])][tostring(hexGridAxial+bearingAdjacentAdjust[fixedBearing][fixedAdjacentBearing][2])]={hexType="wall"}
						end
					end
				end
			end
			--Record other objects of interest
			if (mightBeMap.guid==cityModel.white or mightBeMap.guid==cityModel.blue or mightBeMap.guid==cityModel.red or mightBeMap.guid==cityModel.green or mightBeMap.guid==volkare.terrainHex or mightBeMap.guid==darkCrusader.terrainHex or mightBeMap.guid==elementalist.terrainHex) or
				(mightBeMap.getName()=="Shield" and ((mightBeMap.getDescription()==turnOrder[gStates.turnNumber].mage and gStates.coop==0) or gStates.coop==1)) or
				(monsterPugs[mightBeMap.guid]~=nil and (monsterPugs[mightBeMap.guid].pugType=="green" or monsterPugs[mightBeMap.guid].pugType=="red")) then
				local terTile=mightBeMap.getPosition()
				local hexGridHorizontal=math.floor(((terTile[3]-getObjectFromGUID(startTileGUID).getPosition()[3])/2.0785)+0.5)
				local hexGridAxial=math.floor(((terTile[1]-getObjectFromGUID(startTileGUID).getPosition()[1])/2.4)+(hexGridHorizontal/2)+0.5)
				if hexMap[tostring(hexGridHorizontal)]==nil then hexMap[tostring(hexGridHorizontal)]={} end
				--Record a shield token found
				if (mightBeMap.getName()=="Shield" and ((mightBeMap.getDescription()==turnOrder[gStates.turnNumber].mage and gStates.coop==0) or gStates.coop==1)) then
					if hexMap[tostring(hexGridHorizontal)][tostring(hexGridAxial)]==nil then hexMap[tostring(hexGridHorizontal)][tostring(hexGridAxial)]={} end
					hexMap[tostring(hexGridHorizontal)][tostring(hexGridAxial)].fortified="shield"
				end
				--Record city model locations into hexgrid
				if (mightBeMap.guid==cityModel.white or mightBeMap.guid==cityModel.blue or mightBeMap.guid==cityModel.red or mightBeMap.guid==cityModel.green or mightBeMap.guid==volkare.terrainHex or mightBeMap.guid==darkCrusader.terrainHex or mightBeMap.guid==elementalist.terrainHex) then
					hexMap[tostring(hexGridHorizontal)][tostring(hexGridAxial)]={hexType="city", fortified="city"}
					--change fortified to shield if city is beaten.
				end
				--Record rampaging tokens found.
				if (monsterPugs[mightBeMap.guid]~=nil and mightBeMap.getPosition()[2]<1.09 and (monsterPugs[mightBeMap.guid].pugType=="green" or monsterPugs[mightBeMap.guid].pugType=="red")) then
					hexMap[tostring(hexGridHorizontal)][tostring(hexGridAxial)]={hexType="rampager"}
				end
			end
		end
		--add explore hex to boundary
		-- for _, buttonDetail in pairs(gStates.exploreButtons) do
		-- 	if buttonDetail.attributes~=nil then
		-- 		local hexGridHorizontal=math.floor(((buttonDetail.attributes.tilePosZ-getObjectFromGUID(startTileGUID).getPosition()[3])/2.0785)+0.5)
		-- 		local hexGridAxial=math.floor(((buttonDetail.attributes.tilePosX-getObjectFromGUID(startTileGUID).getPosition()[1])/2.4)+(hexGridHorizontal/2)+0.5)
		-- 		local bearingAdjust={{1,0}, {0,-1}, {-1,-1}, {-1,0}, {0,1}, {1,1}, {1,0}, {0,-1}}--Each end are wrap around values.
		-- 		for primaryHexLoop=2, 7 ,1 do
		-- 			local hexGridHorizontal2=hexGridHorizontal+bearingAdjust[primaryHexLoop][1]
		-- 			local hexGridAxial2=hexGridAxial+bearingAdjust[primaryHexLoop][2]
		-- 			for secondaryHexLoop=primaryHexLoop-1, primaryHexLoop+1, 1 do
		-- 				local hexGridHorizontal3=hexGridHorizontal2+bearingAdjust[secondaryHexLoop][1]
		-- 				local hexGridAxial3=hexGridAxial2+bearingAdjust[secondaryHexLoop][2]
		-- 				if hexMap[tostring(hexGridHorizontal3)]~=nil and hexMap[tostring(hexGridHorizontal3)][tostring(hexGridAxial3)]~=nil then
		-- 					if hexMap[tostring(hexGridHorizontal2)]==nil then hexMap[tostring(hexGridHorizontal2)]={} end
		-- 					hexMap[tostring(hexGridHorizontal2)][tostring(hexGridAxial2)]={hexType="explore"}
		-- 					break
		-- 				end
		-- 			end
		-- 		end
		-- 	end
		-- end

		--work out players hex grid position
		local playerPos={-36.03, 0.97, -11.93}
		if getObjectFromGUID(startTerrain.wedge)~=nil then playerPos={-24.03, 0.97, -16.08} end
		if gStates.resourceTracker.playerPos==nil and turnOrder[gStates.turnNumber].turnStartLoc[1]~=nil and turnOrder[gStates.turnNumber].turnStartLoc[1]>-42 then
			gStates.resourceTracker.playerPos={turnOrder[gStates.turnNumber].turnStartLoc[1], turnOrder[gStates.turnNumber].turnStartLoc[2], turnOrder[gStates.turnNumber].turnStartLoc[3]}--{0, 0, 0}
		end
		if id=="MovemAmountUpdate" then
			for b, details in pairs(mageKnights) do
				if details.mage==turnOrder[gStates.turnNumber].mage then
					if getObjectFromGUID(details.model)~=nil then gStates.resourceTracker.playerPos={getObjectFromGUID(details.model).getPosition()[1], getObjectFromGUID(details.model).getPosition()[2], getObjectFromGUID(details.model).getPosition()[3]} end
					if getObjectFromGUID(details.token)~=nil then gStates.resourceTracker.playerPos=getObjectFromGUID(details.token).getPosition() end
					if getObjectFromGUID(details.standee)~=nil then gStates.resourceTracker.playerPos=getObjectFromGUID(details.standee).getPosition() end
				end
			end
			if turnOrder[gStates.turnNumber].avatarLocation:sub(1, 4)=="city" or turnOrder[gStates.turnNumber].avatarLocation=="Volkare's Camp" then
				--figure out which city avatar is in
				for zone, citySearch in pairs(cityScriptZones) do
					for obj, detail in pairs(getObjectFromGUID(zone).getObjects()) do
						if detail.getName()==turnOrder[gStates.turnNumber].mage then
							gStates.resourceTracker.playerPos=getObjectFromGUID(citySearch.cityGUID).getPosition()
							break
						end
					end
				end
			end
		end
		if gStates.resourceTracker.playerPos~=nil then playerPos=gStates.resourceTracker.playerPos end

		local playerHexGridHorizontal=math.floor(((playerPos[3]-getObjectFromGUID(startTileGUID).getPosition()[3])/2.0785)+0.5)
		local playerHexGridAxial=math.floor(((playerPos[1]-getObjectFromGUID(startTileGUID).getPosition()[1])/2.4)+(playerHexGridHorizontal/2)+0.5)
		local moveMap={[tostring(playerHexGridHorizontal)]={[tostring(playerHexGridAxial)]={main=0}}}
		local fringe={{coord={playerHexGridHorizontal, playerHexGridAxial}}}
		local tempFringe={}

		--Search fringe hexes recorded from the previous loop
		local searchLimit=10
		local noMove=false
		while noMove==false do
			noMove=true
			--check every hex added in the last round
			for checkingHex, hexDetail in pairs(fringe) do
				local moveSpent=99
				if moveMap[tostring(hexDetail.coord[1])]~=nil and moveMap[tostring(hexDetail.coord[1])][tostring(hexDetail.coord[2])]~=nil then
					moveSpent=moveMap[tostring(hexDetail.coord[1])][tostring(hexDetail.coord[2])].main
					if moveMap[tostring(hexDetail.coord[1])][tostring(hexDetail.coord[2])].tricky~=nil then moveSpent=moveMap[tostring(hexDetail.coord[1])][tostring(hexDetail.coord[2])].tricky end
				end

				--figure out the move cost to reach surrounding hexs
				local vectorCheck={{0,-1}, {-1,-1}, {-1,0}, {0,1}, {1,1}, {1,0}}
				for currentVector, vector in pairs(vectorCheck) do
					local hor=hexDetail.coord[1]+vector[1]
					local vec=hexDetail.coord[2]+vector[2]
					--See if the destination hex has a recorded terrain type
					if hexMap~=nil and hexMap[tostring(hor)]~=nil and hexMap[tostring(hor)][tostring(vec)]~=nil then
						local hexCost=999
						if hexMap[tostring(hor)][tostring(vec)].hexType~=nil and gStates.moveCost[hexMap[tostring(hor)][tostring(vec)].hexType]~=nil then hexCost=gStates.moveCost[hexMap[tostring(hor)][tostring(vec)].hexType]+moveSpent end
						local wallhor=hexDetail.coord[1]+(vector[1]/2)
						local wallvec=hexDetail.coord[2]+(vector[2]/2)
						if hexMap[tostring(wallhor)]~=nil and hexMap[tostring(wallhor)][tostring(wallvec)]~=nil then hexCost=hexCost+1 end
						local recordedMoveTotal=99
						if moveMap[tostring(hor)]~=nil and moveMap[tostring(hor)][tostring(vec)]~=nil then
							recordedMoveTotal=moveMap[tostring(hor)][tostring(vec)].main
							if moveMap[tostring(hor)][tostring(vec)].tricky~=nil then recordedMoveTotal=moveMap[tostring(hor)][tostring(vec)].tricky end
						end
						if hexCost<gStates.resourceTracker.move.move+searchLimit and hexCost<recordedMoveTotal then
							if moveMap[tostring(hor)]==nil then moveMap[tostring(hor)]={} end
							if moveMap[tostring(hor)][tostring(vec)]==nil then moveMap[tostring(hor)][tostring(vec)]={} end
							--Don't add hex to fringe if passing a rampager
							local vectorCheck2={{1,0}, {0,-1}, {-1,-1}, {-1,0}, {0,1}, {1,1}, {1,0}, {0,-1}}
							local vectorCheck3={{0.5,-0.5}, {-0.5,-1}, {-1,-0.5}, {-0.5,0.5}, {0.5,1}, {1,0.5}, {0.5,-0.5}}
							local rampageNeighbor=false
							local rampageHor={tostring(hexDetail.coord[1]+vectorCheck2[currentVector][1]), tostring(hexDetail.coord[1]+vectorCheck2[currentVector+2][1])}
							local rampageVec={tostring(hexDetail.coord[2]+vectorCheck2[currentVector][2]), tostring(hexDetail.coord[2]+vectorCheck2[currentVector+2][2])}
							local rampageWallHor={tostring(hexDetail.coord[1]+vectorCheck3[currentVector][1]), tostring(hexDetail.coord[1]+vectorCheck3[currentVector+1][1])}
							local rampageWallVec={tostring(hexDetail.coord[2]+vectorCheck3[currentVector][2]), tostring(hexDetail.coord[2]+vectorCheck3[currentVector+1][2])}
							if (hexMap[rampageHor[1]]~=nil and hexMap[rampageHor[1]][rampageVec[1]]~=nil and hexMap[rampageHor[1]][rampageVec[1]].hexType=="rampager" and (hexMap[rampageWallHor[1]]==nil or hexMap[rampageWallHor[1]][rampageWallVec[1]]==nil)) or
								(hexMap[rampageHor[2]]~=nil and hexMap[rampageHor[2]][rampageVec[2]]~=nil and hexMap[rampageHor[2]][rampageVec[2]].hexType=="rampager" and (hexMap[rampageWallHor[2]]==nil or hexMap[rampageWallHor[2]][rampageWallVec[2]]==nil)) then
								rampageNeighbor=true
								if moveMap[tostring(hor)][tostring(vec)].main~=nil then
									moveMap[tostring(hor)][tostring(vec)].tricky=moveMap[tostring(hor)][tostring(vec)].main
									moveMap[tostring(hor)][tostring(vec)].main=hexCost
								else
									moveMap[tostring(hor)][tostring(vec)].main=hexCost
									moveMap[tostring(hor)][tostring(vec)].tricky=hexCost--maybe 99 is better
								end
							end
							if rampageNeighbor==false then
								if moveMap[tostring(hor)][tostring(vec)].tricky==nil then
									moveMap[tostring(hor)][tostring(vec)].main=hexCost
								else
									moveMap[tostring(hor)][tostring(vec)].tricky=hexCost
								end
							end
							--if hex is a fortified site don't record as a fringe hex
							if rampageNeighbor==false and hexMap[tostring(hor)][tostring(vec)].hexType~="explore" and (hexMap[tostring(hor)][tostring(vec)].fortified==nil or hexMap[tostring(hor)][tostring(vec)].fortified=="shield") then
								local found=false
								for _, hexDetail2 in pairs(tempFringe) do
									if hexDetail2.coord[1]==hor and hexDetail2.coord[2]==vec then found=true end
								end
								if found==false then
									tempFringe[#tempFringe+1]={coord={hor, vec}}
									noMove=false
								end
							end
						end
					end
				end
			end
			fringe=tempFringe
			tempFringe={}
		end
		--highlight hex
		local numberDecal={	{"https://steamusercontent-a.akamaihd.net/ugc/1834662762012221593/F117EB04B95D3E1485E6709A1BFB178FE57384EE/", "https://steamusercontent-a.akamaihd.net/ugc/1834662762012220819/862110145DE4DF0876B90643C94CF44F20417A01/"},
