				local lowestHex=hexCost.main
				if hexCost.tricky~=nil and hexCost.tricky<lowestHex then lowestHex=hexCost.tricky end
				local hexGridX=((vec-(hor/2))*2.4)+getObjectFromGUID(startTileGUID).getPosition()[1]
