					local url="https://steamusercontent-a.akamaihd.net/ugc/1834662762011923619/52F7934BF6B5FF52FDDE02ED7FF9BC12B053E649/"
					if numberDecal[lowestHex]~=nil then url=numberDecal[lowestHex][1] end
					Global.addDecal({name="Hex Highlight", url=url, position={hexGridX, 1.3, hexGridZ}, rotation={90.0, 0.0, 0.0}, scale={2.5, 2.5, 2.5}})
				else
					if lowestHex<gStates.resourceTracker.move.move+searchLimit then
						local url="https://steamusercontent-a.akamaihd.net/ugc/1834662762011969210/56A9D26E5D1CF91A7026B1F76A84FA98F4FA74FB/"
						if numberDecal[lowestHex]~=nil then url=numberDecal[lowestHex][2] end
						Global.addDecal({name="Hex Highlight", url=url, position={hexGridX, 1.3, hexGridZ}, rotation={90.0, 0.0, 0.0}, scale={2.5, 2.5, 2.5}})
					end
				end
			end
		end
	end
end

function ButtonClickDownOverkill(player, mouseButton, ButtonPressed)
	if mouseButton=="-1" then
		if ButtonPressed:sub(13, 19)=="LevelUp" or ButtonPressed:sub(7, 16)=="OverkillUp" or ButtonPressed:sub(7, 16)=="ArtifactUp" or ButtonPressed:sub(7, 17)=="changeMatUp" then
			getObjectFromGUID(ButtonPressed:sub(1, 6)).UI.setAttribute(ButtonPressed.."Image", "image", "Overkill Up Deactive")
		end
		if ButtonPressed:sub(13, 21)=="LevelDown" or ButtonPressed:sub(7, 18)=="OverkillDown" or ButtonPressed:sub(7, 18)=="ArtifactDown" or ButtonPressed:sub(7, 19)=="changeMatDown" then
			getObjectFromGUID(ButtonPressed:sub(1, 6)).UI.setAttribute(ButtonPressed.."Image", "image", "Overkill Down Deactive")
		end
	end
end
function ButtonClickUpOverkill(player, mouseButton, ButtonPressed)
	if mouseButton=="-1" then
		if ButtonPressed:sub(13, 19)=="LevelUp" or ButtonPressed:sub(7, 16)=="OverkillUp" or ButtonPressed:sub(7, 16)=="ArtifactUp" or ButtonPressed:sub(7, 17)=="changeMatUp" then
			getObjectFromGUID(ButtonPressed:sub(1, 6)).UI.setAttribute(ButtonPressed.."Image", "image", "Overkill Up")
		end
		if ButtonPressed:sub(13, 21)=="LevelDown" or ButtonPressed:sub(7, 18)=="OverkillDown" or ButtonPressed:sub(7, 18)=="ArtifactDown" or ButtonPressed:sub(7, 19)=="changeMatDown" then
			getObjectFromGUID(ButtonPressed:sub(1, 6)).UI.setAttribute(ButtonPressed.."Image", "image", "Overkill Down")
		end
	end
end

function ButtonClicked(player, mouseButton, ButtonPressed)
	if mouseButton=="-1" then
		local buttonImage="Sliced Button/Button New Deactive"
		if getObjectFromGUID(ButtonPressed:sub(1, 6))==nil then
			if UI.getAttribute(ButtonPressed.."Image", "image")=="Sliced Button/Button New Deactive" then buttonImage="Sliced Button/Button New Active" end
			UI.setAttribute(ButtonPressed.."Image", "image", buttonImage)
		else
			buttonImage="Sliced Button/Button Object Deactive"
			if getObjectFromGUID(ButtonPressed:sub(1, 6)).UI.getAttribute(ButtonPressed.."Image", "image")=="Sliced Button/Button Object Deactive" then buttonImage="Sliced Button/Button Object Active" end
			getObjectFromGUID(ButtonPressed:sub(1, 6)).UI.setAttribute(ButtonPressed.."Image", "image", buttonImage)
		end
	end
end

function valueAdjust(player, mouseButton, id)
	if mouseButton=="-1" and legalPlayerCheck(player.color, turnOrder[gStates.turnNumber].seatPos)==true then
		if id=="GrowHand" and turnOrder[gStates.turnNumber].hand+turnOrder[gStates.turnNumber].handBonus+gStates.tactic4HandBonus<20 then turnOrder[gStates.turnNumber].handBonus=turnOrder[gStates.turnNumber].handBonus+1 end
		if id=="ShrinkHand" and turnOrder[gStates.turnNumber].hand+turnOrder[gStates.turnNumber].handBonus+gStates.tactic4HandBonus>turnOrder[gStates.turnNumber].baseHand then turnOrder[gStates.turnNumber].handBonus=turnOrder[gStates.turnNumber].handBonus-1 end
		if id=="GrowFame" then turnOrder[gStates.turnNumber].fameGain=turnOrder[gStates.turnNumber].fameGain+1 end
		if id=="ShrinkFame" and turnOrder[gStates.turnNumber].fameGain>0 then turnOrder[gStates.turnNumber].fameGain=turnOrder[gStates.turnNumber].fameGain-1 end
		if id=="GrowRep" and turnOrder[gStates.turnNumber].repGain< (7-turnOrder[gStates.turnNumber].reputation) then turnOrder[gStates.turnNumber].repGain=turnOrder[gStates.turnNumber].repGain+1 end
		if id=="ShrinkRep" and turnOrder[gStates.turnNumber].repGain>(-7-turnOrder[gStates.turnNumber].reputation) then turnOrder[gStates.turnNumber].repGain=turnOrder[gStates.turnNumber].repGain-1 end
		mainUIUpdate("Value Adjusted")
	end
end

function closeSplash() UI.hide("welcome") end

function autoflip()
	if gStates.autoFlip==true then
		gStates.autoFlip=false
		UI.setAttribute("AutoFlipButtonRealImage", "image", "Sliced Button/Button New Active")
		broadcastToAll("{en}Monster tokens need to be flipped manually.{ru}Жетоны врагов необходимо переворачивать вручную.{zh-cn}怪物标记需要手动翻转{ko}규칙에 따라 직접 토큰을 뒤집어야 합니다{es}Las fichas de monstruo deben voltearse manualmente.{fr}Les jetons Monstre doivent être retournés manuellement.{pt-br}Fichas de Monstros precisam ser viradas manualmente{de}Monsterplättchen müssen manuell umgedreht werden.", {1,1,0.5})
	else
		gStates.autoFlip=true
		UI.setAttribute("AutoFlipButtonRealImage", "image", "Sliced Button/Button New Deactive")
		broadcastToAll("{en}Script will flip monster tokens for you.{ru}Скрипт будет переворачивать жетоны врагов за вас.{zh-cn}脚本将为你翻转怪物标记. {ko}스크립트가 자동으로 토큰을 뒤집습니다.{es}Script le dará la vuelta a las fichas de monstruos.{fr}Le script retournera les jetons monstre pour vous.{pt-br}O Script virará as fichas de monstros por você.{de}Das Skript dreht die Monsterplättchen für dich um.", {1,1,0.5})
	end
end

