function lowerTable(player, mouseButton, id)
	if mouseButton=="-1" then
		if getObjectFromGUID("3d4319").getPosition()[2]==0 then
			getObjectFromGUID("3d4319").setPosition({0.00, -0.2, -5.00})
			getObjectFromGUID("519f96").setScale({200, 1, 200})
			getObjectFromGUID("519f96").setPosition({0.00, 0.77, -5.00})
			skillButtonActivate()
			return
		end
		if getObjectFromGUID("3d4319").getPosition()[2]<0 then
			getObjectFromGUID("3d4319").setPosition({0.00, 0.0, -5.00})
			getObjectFromGUID("519f96").setScale({1, 1, 1})
			getObjectFromGUID("519f96").setPosition({0.00, -0.2, -5.00})
			skillButtonActivate()
		end
	end
end

--Used to join a table of strings with translation brackets
function joinLang(full_string)
	--convert a string with translation brackets into a table.
    local languageSeperated={}
	for count, translationString in pairs(full_string) do
    	local pos=1
		languageSeperated[count]={}
		local found=false
		repeat
		    local i, j, lang=tostring(translationString):find("{([^{}]*)}", pos)
		    if i then
		        table.insert(languageSeperated[count], {pos1=i, pos2=j, lang=lang})
		        pos=i+1
			end
		until not i
		--adds the language string to table
		local last_pos=#tostring(translationString)
		for i=#languageSeperated[count], 1, -1 do
		    local data=languageSeperated[count][i]
		    local pos1, pos2, lang=data.pos1, data.pos2, data.lang
		    languageSeperated[count][lang]=translationString:sub(pos2+1, last_pos)
		    languageSeperated[count][i]=nil
		    last_pos=pos1-1
			found=true
		end
		--if no language braket found asign the string to all languages
		if found==false then
			languageSeperated[count]["en"]=tostring(translationString)
		end
	end
	--re assemble table into a valid translation string
    local DEFAULT_ORDER={"en", "ru", "zh-cn", "ko", "es", "fr", "pt-br", "de"}
	local languageJoined=""
    for _, lang in ipairs(DEFAULT_ORDER) do
        languageJoined=languageJoined.."{"..lang.."}"
        for count, phraseSeperated in pairs(languageSeperated) do
            languageJoined=languageJoined..(phraseSeperated[lang] or phraseSeperated["en"])
        end
    end
	return languageJoined
end
